-- =============================================================================
-- city_data Wikipedia leírások – 1/4. fájl
-- Települések: 773 (Aba … Gadács)
-- Futtasd sorban: 01 → 02 → 03 → 04 (az 1. fájl tartalmazza a setupot is).
-- =============================================================================

ALTER TABLE public.city_data
  ADD COLUMN IF NOT EXISTS panel_leiras TEXT;

UPDATE public.city_data SET panel_leiras = NULL;

UPDATE public.city_data AS c
SET panel_leiras = v.panel_leiras
FROM (
  VALUES
    ('Aba', 'Székesfehérvártól 20 kilométerre dél-délkeletre, a Mezőföld északi részén, a Sárvíz völgyében fekszik. Közigazgatási területe 8805 hektár. A közúti tömegközlekedést a Volánbusz autóbuszai biztosítják.'),
    ('Abaliget', 'Közkedvelt kiránduló- és üdülőhely. Álló háromszögű, ezüstszínű pajzs az alap. Alul, a vizet jelképező kék szín fölött zöld színű hármashalom látható. A kék mezőben a zöld halomba is felnyúló, íves fekete barlangbejárat van, alul és felül is ezüstszínű cseppkő-képződményekkel. Az ezüstszínű mezőben a szélső halmokon egy jobbra tekintő, kiterjesztett szárnyú, vörös lábú és csőrű fekete sas áll.'),
    ('Abasár', 'A Mátrai borvidék meghatározó települése. Itt van Magyarország legmagasabban fekvő szőlőtermesztő vidéke, a Sár-hegy. A Keleti-Mátraalján, a Sár-hegy lejtőjén, a Bene-patak völgyében fekszik, Budapesttől 90, Gyöngyöstől 8 kilométerre északkeletre. Visontával a 24 145-ös út köti össze. A közúti tömegközlekedést a Volánbusz autóbuszai biztosítják. A környék már i. e. 2500 körül lakott volt.'),
    ('Abaújalpár', 'Az Északi-középhegységben, a Zempléni-hegység nyugati részén fekszik, Encstől 9 kilométerre délkeletre, Miskolctól, a megyeszékhelytől mintegy 50 kilométerre északkeletre. Területe 848 hektár, ebből 22 hektár belterület, 826 hektár pedig külterület, többnyire erdő. A közvetlen szomszédos települések: észak felől Boldogkőújfalu, kelet felől Sima, dél felől Abaújkér-Aranyospuszta, nyugat felől pedig Abaújkér.'),
    ('Abaújkér', 'Az Északi-középhegységben, a Cserehát és a Zempléni-hegység között, a Hernád folyó völgyében fekszik, a megye székhelyétől, Miskolctól mintegy 50 kilométerre északkeletre. Különálló településrésze Aranyospuszta, a központjától szűk 3 kilométerre keletre helyezkedik el. A közvetlen szomszédos települések: észak felől Boldogkőváralja, északkelet felől Boldogkőújfalu, kelet felől Abaújalpár, dél felől Abaújszántó, délnyugat felől Hernádbűd, nyugat felől Gibárt, északnyugat felől pedig Encs és Méra helyezkedik el.'),
    ('Abaújlak', 'Közigazgatásilag hozzá tartozik Szanticska is, az ország egyik legkisebb települése. Encstől légvonalban mintegy 15 kilométer-re északnyugatra, Miskolctól 40 kilométer-re északra fekszik, a Cserehát legmagasabb hegyének, a Kecske-padnak délkeleti lábánál. Dombvidéki sorfalu, a Cserehát legmagasabban lévő települése. Környező községek: Abaújszolnok (6 kilométer), Gadna (2 kilométer), Gagyvendégi (5 kilométer).'),
    ('Abaújszolnok', 'Az Északi-középhegységben, a Cserehát keleti oldalán fekszik, Miskolctól 35 kilométerre, északkeletre. A szomszédos települések: észak felől Abaújlak (Szanticska), kelet felől Baktakék, dél felől Selyeb, nyugat felől pedig Nyésta. [Határos még Gagyapátival is, de közúti kapcsolat nincs közöttük.] A legközelebbi város Encs (20 kilométer). Közúton a 3-as főútról Szikszón, a Miskolci úton a II.'),
    ('Abaújszántó', 'Szőlő- és borgazdasági szempontból a Tokaji borvidék egyik települése. Az Északi-középhegységben, a Zempléni-hegység nyugati lábánál, a Cserehát és a Zempléni-hegység között fekszik, a Hernád völgyében, a Szerencs-patak mellett. A megye székhelyétől, Miskolctól közúton mintegy 40 kilométer választja el. A szomszédos települések: észak felől Abaújkér, északkelet felől Abaújalpár, kelet felől Sima és Erdőbénye, délkelet felől Tállya, dél felől Golop, nyugat-délnyugat felől Felsődobsza, nyugat felől Pere, északnyugat felől pedig Hernádbűd.'),
    ('Abaújvár', 'Körjegyzőségi központ. A szlovák határ mellett fekszik, a Hernád folyó bal (keleti oldali) partjának lankás, legfeljebb 240 méteres magasságig emelkedő dombjain, a megyeszékhely Miskolctól 72 kilométerre északkeletre. Lakott területét a Hasdát-patak osztja ketté, mely a Zempléni-hegység felől, Pányok irányából nyugat felé tartva, a falu északnyugati részén ömlik a Hernádba.'),
    ('Abda', 'A Mosoni-sík és a Csornai-sík találkozásánál, a Rábca és a Mosoni-Duna által közrezárt, a régmúlt korokban vízjárta síksági területen fekszik. Az ember szórványos megtelepedésének nyomai az újkőkorszak óta ismertek. A mai település elődje a „bécsi nagyúton” a 11. században létesített és a 12. századtól vámszedő helyként ismert Rábca-híd mellett alakult ki az Árpád-korban.'),
    ('Abod', 'Edelénytől 14 kilométerre északkeletre helyezkedik el, a megyesszékhely Miskolctól mintegy 35 kilométerre északra. A közvetlenül határos települések: észak felől Galvács (6 kilométer), kelet felől Irota és Szakácsi (6 kilométer), délkelet felől Lak, dél felől Ládbesenyő (8 kilométer), délnyugat felől Szendrőlád, nyugat felől pedig Szendrő (11 kilométer).'),
    ('Abony', 'Területének egy része a Tisza egykori árterületére esik. Határa nagy kiterjedésű, csaknem 13 ezer hektár. Talaja egy kevés homok és szikes kivételével termékeny fekete föld. Tengerszint feletti magassága: 90–100 méter.'),
    ('Abádszalók', 'Ma a Tisza-tó turisztikai régió jelentős városa és Tiszafüred után a Tisza-tó egyik legkiépítettebb idegenforgalmi központja. A Tiszafüred–Kunhegyesi-sík és a Nagykunság északnyugati részén fekszik, Szolnok és Tiszafüred között − bár ez utóbbihoz lényegesen közelebb −, a Tisza középső szakaszának bal partján, a Tisza-tó mellett.'),
    ('Acsa', 'Autóval a 2106-os úton közelíthető meg Vác irányából, illetve a 2108-as úton, Aszód vagy Balassagyarmat felől. A települést érintő helyközi autóbuszvonalak az alábbiakː 316, 338, 460. A község mai neve a jelenlegi ismeretek szerint az Acha személynévből származik, amely valószínűleg az ótörök aca (rokon) szóból ered. Már a honfoglalás idején is lakott hely volt, amit a határában előkerült leletek bizonyítanak.'),
    ('Acsalag', 'A Hanság délnyugati részén fekszik, Csornától 10 kilométerre északra. A település közúton a legegyszerúbben Csorna érintésével közelíthető meg: a város központjában a 86-os főútra kell ráfordulni északi irányban, majd Csatárimajornál nyugatnak letérni a 8513-as útra helyezkedik el. Neve régi adatok híján tudományosan nem etimologizálható megbízhatóan helyezkedik el.'),
    ('Acsád', 'Szombathelytől 14 kilométerre északkeletre fekszik, a Gyöngyös-sík északi részén, az Ablánc-patak mellett. A szomszédos települések: északkelet felől Gór, kelet felől Szeleste, dél felől Vasszilvágy, délnyugat felől Salköveskút, nyugat felől Meszlen, északnyugat felől pedig Csepreg. A főutaktól távol esik, közúton csak mellékutakon érhető el: Csepreg városa és Salköveskút felől a 8638-as, Vát felől Vasszilvágyon át a 8635-ös, Meszlen és azon keresztül Kőszeg felől pedig a 8636-os úton.'),
    ('Adony', 'Fontos Dunai kompátkelőhely. A környező települések Kulcs (7 kilométer), Pusztaszabolcs (8 kilométer), Perkáta és Rácalmás (egyaránt 12-12 kilométer). Pusztaszabolccsal és Velencével a 6207-es, Perkátával a 6208-as, Kálozzal pedig a 6209-es utak kötik össze. Autóbusszal az 1120-as, 1125-ös, 8185-ös, 8236-os, 8238-as és 8240-es járatokkal érhető el˛.'),
    ('Adorjánháza', 'A legközelebbi város Celldömölk (15 kilométer). Veszprém megye nyugati peremén, a Marcal völgyében, a folyó jobb parti oldalán fekszik. A szomszédos települések: észak felől Külsővat, északkelet felől Nemesszalók, dél felől Egeralja, nyugat felől pedig Celldömölk. Egeraljával mára gyakorlatilag teljesen összenőtt. Csak közúton közelíthető meg, a 8413-as úton, amely nagyjából dél-északi irányban húzódik végig a központján.'),
    ('Adorjás', 'Az Ormánság északkeleti vidékén fekszik, Siklóstól nyugatra, Harkány és Vajszló között. A szomszédos települések: észak felől Kórós, kelet felől Drávapiski, délkelet felől Kémes, dél felől Cún, nyugat felől Sámod, északnyugat felől pedig Páprád. Lakott területeit azonban az előbbi út nem érinti, oda csak az 58 128-as számú mellékúton lehet eljutni, amely Adorjás után még továbbvezet észak felé, Kórós központjáig.'),
    ('Adács', 'A Mátraalja déli részén fekszik, Gyöngyös központjától 11 kilométerre délre. Átlagos tengerszint feletti magassága nem éri el a 120 métert. Jelentősebb vízfolyása nincs, erdőterülete is csekély. Növény- és állatvilága alföldi jellegű. Belterülete 216, külterülete 3578 hektár. A közvetlenül szomszédos települések: északkelet felől Karácsond, kelet felől Nagyfüged, délkelet felől Visznek, dél felől Jászárokszállás, nyugat felől Vámosgyörk, északnyugat felől pedig Gyöngyöshalász.'),
    ('Adásztevel', 'A Bakony északi lábánál, Pápa városától 4 kilométerre délkeletre fekszik. Településszerkezetét tekintve dombvidéki sorfalu. A község csak közúton közelíthető meg, a Pápa-Béb között húzódó 8303-as úton. Nevét Árpád fejedelem egyik unokájáról, Tevelről kapta, aki ezen a területen foglalt szállást. A települést említő legrégibb, 1180 körül keletkezett oklevélben Tuel néven, egy 1373-ban keltben pedig Adastewyl néven szerepel.'),
    ('Aggtelek', 'Itt van az ország egyik leghíresebb cseppkőbarlangjának, a Baradla-barlangnak néhány bejárata. Miskolctól mintegy 50 kilométerre északnyugatra fekszik, a szlovák határhoz közel. A legközelebbi települések dél felől Trizs (6 kilométer), kelet felől Jósvafő (5 kilométer), északnyugat felől pedig a már Szlovákiához tartozó Kecső (Kečovo, 5 kilométer).'),
    ('Agyagosszergény', 'Ideiglenes neve 1928-ig Fertőszergényagyagos volt. A Hanság déli szélén fekszik, határában folyik nyugat felől az Ikva-patak, északon pedig a Répce. A határos települések: délkelet felől Vitnyéd, nyugat felől pedig Fertőendréd. Közigazgatási területe a fentieken túlmenően, északkelet felől kapuvári, északnyugati irányból pedig fertődi külterületekkel is érintkezik.'),
    ('Ajak', 'A Tiszántúlon, Szabolcs-Szatmár-Bereg megye északi részén fekszik. A település területének mintegy egyharmad része a Rétközhöz, kétharmad része a Nyírséghez tartozik. Szomszédai: észak felől Kisvárda, kelet felől Anarcs, délkelet felől Gyulaháza, délnyugat felől Nyírtass, nyugat felől Pátroha, északnyugat felől pedig Rétközberencs. A legközelebbi város a 6 kilométerre fekvő Kisvárda.'),
    ('Ajka', 'Északon Magyarpolány, délen Öcs és Halimba, nyugaton Kolontár és Devecser, míg keleten Kislőd és Úrkút a szomszédos települések. Több kis patak folyik át területén: a Torna- és a Csinger-patak a belterületen, a Széles-víz, a Csigere- és Polányi-patak pedig a település határában. Egy mesterségesen létrehozott csónakázótó is van a városban. A település környékén kőkorszaki leleteket is találtak, ami a kőkorszaki ember jelenlétét bizonyítja.'),
    ('Aka', 'A település a Bakonyalja keleti szélén, Kisbértől 15, Mórtól 18 kilométer-re, Bakonysárkány és Ácsteszér között fekszik. Tengerszint feletti magassága 250 méter körül van. A falu településszerkezete dombvidéki sorfalu. Hegedűs Pálnak, a kisbéri Helytörténeti Gyűjtemény vezetőjének kutatásai szerint a település nevét tartalmazó legrégibb oklevél 1274-ből maradt fenn, amikor Akai Ogmánd a király megbízásából a Szák nemzetségbeli Konrád fia Jánost beiktatta dinnyei (ma Alsó-vasdinnyepuszta) birtokába.'),
    ('Akasztó', 'A Duna–Tisza közén fekszik, Kiskőröstől 9 kilométerre északnyugatra. Külterületi határrészeiből északon közel 6 négyzetkilométernyi terület a Kiskunsági Nemzeti Park Felső-kiskunsági-tavak, nyugaton pedig csaknem 9 négyzetkilométer a nemzeti park Miklapuszta nevű részterületéhez tartozik. A helyi hagyomány szerint a község neve onnan ered, hogy a rossz utak miatt az átutazók a kerékakasztó sár miatt nem tudták útjukat folytatni, megakadtak.'),
    ('Alacska', 'A község zsákfalu a Bükk hegységtől északra, Sajószentpéter városától 4 kilométer-re nyugatra helyezkedik el. Közúton a 26-os főútból Sajószentpéteren délnyugatnak kiágazó 25 129-es számú mellékúton érhető el. A nevét tartalmazó legrégibb fennmaradt oklevelet 1280 körül készítették Alacskay Zadur leánya Haripáni Izóth özvegye perével kapcsolatban. Ötven évvel később, 1330-ban a pápai tizedjegyzékben szerepelt a falu neve.'),
    ('Alap', 'Településszerkezetét tekintve síkvidéki útifalu. A település a Mezőföldön terül el, Sárbogárd délkeleti szomszédságában, a város központjától mintegy 10 kilométerre délre. A további közvetlenül határos települések: északkelet felől Nagykarácsony, kelet felől Előszállás, délkelet felől Alsószentiván, délnyugat felől pedig Cece. Fentebb felsorolt szomszédai közül Nagykarácsonnyal és Előszállással nincs közvetlen közútkapcsolata.'),
    ('Alattyán', 'A Zagyva bal partján fekszik Szolnoktól 34 kilométer-re északnyugatra, Jászberénytől 13 kilométer-re délkeletre. Teljes területe sík, tengerszint feletti magassága 90-91 méter. Neve török személynévből ered (Alîp-Tîɣan), jelentése: "hős-sólyom". Etimológiailag előtagja összefügg a magyar Alap és Alpár helynevekkel, utótagja pedig a turul köznévvel.'),
    ('Albertirsa', 'A Duna–Tisza közi homokhátságon, a Gerje–Perje-sík és a Monor-Irsai dombság találkozásánál helyezkedik el, Ceglédtől 21 kilométerre északnyugatra. Határa bővelkedik védett természeti értékekben, itt található például Közép-Európa egyik legnagyobb egybefüggő gyurgyalagtelepe. Északi határszélén folyik a Gerje patak. Budapest, illetve a keletebbre fekvő nagyobb városok (Szolnok, Debrecen) felől is, hiszen az végighalad a teljes belterületén helyezkedik el.'),
    ('Alcsútdoboz', 'A szomszédos települések: Felcsút (6 kilométer), Etyek (14 kilométer), Tabajd (3 kilométer), Vértesacsa (9 kilométer). Baracskától és Vértesdoboz községek összevonásával. 1944-ben még egyik településen sem volt kultúrház, nyilvános községi könyvtár és mozi. A művelődési lehetőségeket a Gazdakör, a két egyházi dalárda, az 1882-ben alakult Tűzoltóegylet, a Levente egyesület és az Oltáregylet adták.'),
    ('Aldebrő', 'Az Alföld északi peremén, a Mátra délkeleti lábánál fekszik, az egri borvidéken, a Tarna völgyében. Településszerkezete szerint dombvidéki útifalu. Külterülete nyugat felé messzire elnyúlik a település központjától, így többek között nagyrészt hozzá tartozik a Mátrai Erőmű egyik lignitbányájának területe is. A közvetlen szomszédos települések észak felől Feldebrő, dél felől Tófalu, nyugat felől pedig Vécs, de kiterjedt külterületei révén határos még délnyugat felől Kápolnával, nyugat felől Detkkel, északnyugat felől pedig még Domoszlóval is.'),
    ('Algyő', 'A Tisza jobb partján fekszik, Szegedtől 10, Hódmezővásárhelytől 15 kilométerre. Szomszédai: északkelet és kelet felől Hódmezővásárhely, délkelet felől Maroslele, dél és délnyugat felől Szeged, nyugat felől pedig Sándorfalva. A bal parton fekvő két legfontosabb településrésze Nagyfa és Rákóczitelep, mindkettő a 4413-as útról érhető el, utóbbi főutcája 44 123-as útszámmal számozódik.'),
    ('Alibánfa', 'Zalaegerszegtől 11 kilométerre északkeletre, a Zala folyó mentén helyezkedik el. A települést keleten és nyugaton szőlőhegyek veszik körül. Első fennmaradt írásos említése 1414-ből való, „Possessio Olywanchfalwa” néven helyezkedik el. Az Alibán előtag az Olivant francia személynévből, a falu hajdani földbirtokosának nevéből ered. A 16. században a törökök többször pusztítottak a településen, amely a század végére teljesen lakatlanná vált. 1699. november 6.-án I.'),
    ('Almamellék', 'A Zselic dombvidékén, Szigetvártól 15 kilométerre északra fekszik. Almamellék központja a letéréstől körülbelül 4 kilométerre van. Almamellék mérsékelten meleg nyarú, enyhe telű dombsági terület. A csapadék egész évben kevés, de éghajlati viszonyai ennek ellenére megfelelő feltételeket biztosítanak a mezőgazdasági művelésnek. A község első írásos emléke 1344-ből maradt fenn.'),
    ('Almásfüzitő', 'A település gyökerei a római korba nyúlnak vissza, de sokkal korábbi, újkőkori leleteket is találtak a területen. Latin neve Azaum volt, így hívták a római korban a mostani falu területének környékén lévő katonai tábort. Az 1. századból való régészeti emlékeket is találtak itt, amelyek a Duna menti limes védműveiből származhatnak. A korai palánk (fa) tábort Marcus Aurelius császár idején…'),
    ('Almásháza', 'Egykor tipikus egyutcás törpefalu volt, de a közelmúltban elkezdett kelet felé terjeszkedni, és ma már kétutcás település. A település a Zalai-dombságban, a Zalaapáti-hát területén fekszik, a Principális-csatorna és a Zala folyó között, Zalaegerszegtől légvonalban 15, közúton körülbelül 20 kilométerre keletre. A közvetlenül határos települések: észak felől Kallósd, kelet felől Kehida (Kehidakustány része), délkelet felől Ligetfalva, dél felől Tilajújhegy (Tilaj része), délnyugat felől Nagykapornak, nyugat felől pedig Padár.'),
    ('Almáskamarás', 'A szomszédos települések: Nagykamarás, Kunágota és Dombiratos. A közúti tömegközlekedést a Volánbusz autóbuszai biztosítják. Az Almáskamaráshoz közel fekvő Nagykamarás, Bánkút és Kunágota települések legrégibb írásos emléke 1418-ből maradt fenn. A két Kamarás (a középkorban Maróti János macsói bán, a gyulai vár építtetője után Bánkamarás) együttes területén a régészek több Árpád-kori falu nyomaira bukkantak, de e falvak…'),
    ('Almáskeresztúr', 'Szigetvár északkeleti szomszédságában fekszik, a város központjától légvonalban 11, közúton 14 kilométerre. A további szomszédos települések: észak felől Ibafa, délkelet felől Nagyváty, dél felől Nyugotszenterzsébet és Botykapeterd, nyugat felől Mozsgó, északnyugat felől pedig Almamellék. Kelet felől a legközelebbi település Dinnyeberki, de a közigazgatási területeik nem érintkeznek.'),
    ('Alsóberecki', 'További szomszédai: észak felől Felsőberecki (3 kilométerre), kelet felől Karos (7 kilométerre), dél felől Bodroghalom (8 kilométerre), délnyugat felől pedig Vajdácska (6 kilométerre). A község neve személynévi eredetű lehet (Brictius, Bereck). A település valószínűleg a honfoglalás óta lakott. Első ismert írásos említése 1358-ból maradt fenn (Bereck).'),
    ('Alsóbogát', 'A település a Zselici-dombvidékben helyezkedik el, első írásos említése pedig 11. század végéből származik. A falu egyik legjelentősebb műemléke a Festetics-Inkey-kastély, mely a 19. században épült a Festetics család birtokán. Alsóbogát lakossága néhány száz fő, és a község gazdasága hagyományosan a mezőgazdaságra épül.'),
    ('Alsódobsza', 'A Hernád bal partján fekszik, a megyeszékhely Miskolctól közúton 22 kilométerre északkeletre, Szerencstől 17 kilométerre nyugatra. Nyugati határának lejtőit akácerdők uralják, amelyekbe csak néhány keskeny szőlősáv ékelődik. A külterület többi részét jól megművelt szántóföldek és gondozott gyümölcsösök foglalják el. A település fekvését szépen írja le Balogh József egykori tanító: „Alsódobsza község ott fekszik, ahol a Nagy Magyar Alföld északkeleti csücske és a Zempléni hegysor délnyugati nyúlványai találkoznak.'),
    ('Alsógagy', 'Háziorvosi ellátásra Felsőgagyon, fogorvosira Baktakéken, gyermek- és szakorvosi ellátásra Encsen van lehetőség. A legközelebbi kórház Szikszón található. A gyerekek óvodába Baktakékre, általános iskolába Encsre járnak. A Gagy szó ismeretlen eredetű, talán személynévre vezethető vissza, azaz a környék egy korai birtokosára utal. A szó magyarázatának eddigi próbálkozásai mind sikertelenek voltak.'),
    ('Alsómocsolád', 'Keleten erdős dombok határolják, nyugaton pedig messze nyúló síkság. Tengerszint feletti magassága 200-220 méter között változik. Fekvése vízrajzi szempontból igen kedvező, éghajlati szempontból mérsékelten meleg vidék, ahol az óceáni hatások vannak túlsúlyban helyezkedik el. A nyár hűvös, a tél enyhe, a csapadék mérsékelten kevés. A körzet éghajlati viszonyai a mezőgazdasági művelésnek kedvező feltételeket biztosítanak.'),
    ('Alsónemesapáti', 'A Zalai-dombságban, ezen belül az Egerszeg–Letenyei-dombság nevű kistáj területén fekszik, a Szévíz patak völgyében hosszan elterülve, a megyeszékhely Zalaegerszeg keleti szomszédságában, a város központjától 10 kilométerre keletre. Mindössze négy települési szomszédja van: észak felől Nemesapáti (kelet felől is az előbbihez tartozó külterületek határolják), dél felől Kisbucsa, nyugat felől Zalaegerszeg, északnyugat felől pedig Pethőhenye.'),
    ('Alsónyék', 'A Sárközben fekszik, Bátaszék közvetlen közelében, a város központjától 2 kilométerre északkeletre. Közúton az 55-ös és az 56-os főútról is elérhető. Központján az 5115-ös út halad át, belterületének déli szélén az 5513-as út halad végig helyezkedik el. Telepítéskori népesítése honnan eszközöltetett a községnek okmányok hiányában meg nem mondható…'),
    ('Alsónána', 'A szomszédos települések: észak felől Szekszárd, északkelet felől Decs, kelet felől Várdomb (3 kilométer), délkelet felől Bátaszék, dél felől Mórágy (5 kilométer), északnyugat felől pedig Szálka (légvonalban mintegy 3 kilométer, de közúton 13 kilométer). Nyugat felől a legközelebbi település Mőcsény, mely légvonalban alig 4 kilométerre fekszik, közúton azonban csak nagy, mintegy 15 kilométeres kerülővel érhető el, s a közigazgatási területeik nem is szomszédosak.'),
    ('Alsónémedi', 'A települést nyugat-délnyugatról a Duna–Tisza-csatorna határolja, határában tanyák vannak. A község környékén rézkori (kb. Kr. e. 2200) sírleleteket tártak fel (némedi kultúra). Pest megye egyik legrégibb települése, első fennmaradt írásos említése 1067-ből való (Nywyg).'),
    ('Alsópetény', 'A Cserhát dombjai között, a Nyugat-Cserhát völgyében, a 423 méter magas Kő-hegy, és a 446 méter magas Dél-hegy lábánál fekszik a legközelebbi várostól, Rétságtól közúton 15 kilométerre délkeletre. A szomszédos települések: Felsőpetény (4 kilométer), Nézsa (6 kilométer) és Keszeg (6 kilométer). A település határában fellelt földvár-maradványok bizonyítják, hogy a terület már évszázadokkal ezelőtt is lakott volt.'),
    ('Alsópáhok', 'Hévíz déli-délnyugati határán, a 75-ös főúttól északra, közel 4 kilométer hosszan elnyúló település. Az Alsópáhok elnevezés első fennmaradt írásos említése 1622-ből való, a korábbi írásos emlékekben „Hosszúpáh” szerepel. Szórványos régészeti leletek bizonyítják, hogy a terület már az őskorban is lakott volt. Régészeti leletekből ismeretes a falu középkori, Szent Margit tiszteletére szentelt román templomának helye is, amelyet a fennmaradt források 1369-ben említenek először, de valószínűleg…'),
    ('Alsórajk', 'A Zalai-dombságban, a Zalaapáti-háton, a Principális-csatorna völgyében fekszik a 75-ös főúton lévő Pacsa kisvárostól 8 kilométer-re délre. Alsórajk a 9. század környékén jöhetett létre. Régészeti leletekből arra lehet következtetni, hogy a mosaburgi fejedelemség idején egy kisebb szláv település állhatott a mai falu helyén, amelyen 1239-ben premontrei kolostor is létesült, de ennek a településnek első fennmaradt írásos említése későbbről, 1247-ből való.'),
    ('Alsóregmec', 'A szlovák határ mellett fekszik, Sátoraljaújhelytől 10 kilométerre észak-északnyugati irányban. A közvetlen szomszédos települések: észak felől Felsőregmec (4 kilométerre), nyugat felől Mikóháza (2 kilométerre), dél felől pedig Széphalom (közigazgatásilag Sátoraljaújhely városrésze, 5 kilométerre). Külterületei délnyugat felé csaknem 10 kilométerre elnyúlnak a település lakott területétől, így abból az irányból még határos Sárospatakkal is.'),
    ('Alsószenterzsébet', 'Göcsejnek ez az apró, elzárt falva az erdőkkel övezett magyar-szlovén határ közelében, a Kerka folyó mellett fekszik, két kilométerre a Csesztreg és Bajánsenye között húzódó 7416-os úttól, a 74 133-as út mentén. Gépjárművel csak ebből az irányból, illetve az út végén elhelyezkedő Felsőszenterzsébet felől közelíthető meg. A szomszédos települések: Felsőszenterzsébet (2 kilométer), Kerkakutas (4 kilométer), Kerkafalva (4 kilométer) és Csesztreg (6 kilométer).'),
    ('Alsószentiván', 'Alsószentiván pusztákból kialakult, villásan elágazó alaprajzú útifalu. A szomszédos települések: Alap (3 kilométer) és Előszállás (8 kilométer). A nagyobb városok közül Dunaújváros 30, Székesfehérvár pedig 55 kilométerre van a falutól. Alsószentiván átlagosan 130 méter tengerszint feletti magasságban lévő, erősen tagolt löszhátas dombvidékre települt.'),
    ('Alsószentmárton', 'A Dráva-síkon fekszik, a horvát határtól 3,5 kilométer-re (közigazgatási határának déli szakasza egybeesik az országhatárral). Szomszédos települések: nyugaton Matty, északkeleten Egyházasharaszti, keleten Old (mindegyiktől 3–3,5 kilométer-re). Az északabbra fekvő két közeli kisváros: Siklós és Harkány 12 ill. 17 kilométer-es kerülővel érhető el. Alsószentmártontól délre több egykori Dráva-kanyarulatból lefűződött holtág maradványa található.'),
    ('Alsószuha', 'A Szuha-patak két partján, a szlovák határ közelében fekszik, Putnoktól közúton 16 kilométer-re északra, Aggtelektől szintén 16 kilométer-re délre. A környező települések: északra Zádorfalva (1 kilométer) és Ragály (8 kilométer), délkeletre Dövény (5 kilométer), nyugatra Kelemér (6 kilométer). Közeli városok Putnokon kívül Rudabánya (17 kilométer) és Kazincbarcika (21 kilométer).'),
    ('Alsószölnök', 'A Vasi-Hegyhát részét képező Vendvidéken, a Rába és a Szölnöki-patak völgyében fekszik, közvetlenül az osztrák határ mellett,a felsőszölnöki hármashatárhoz közel, Szentgotthárdtól, a legközelebbi várostól 6 kilométerre délnyugatra. Településszerkezetét tekintve dombvidéki többutcás sorfalu. A szomszédos települések Szakonyfalu (3 kilométer), Rábatótfalu (Szentgotthárd része, 4 kilométer), Felsőszölnök (7 kilométer).'),
    ('Alsótelekes', 'Kazincbarcikától 21 kilométerre, Miskolctól körülbelül 40 kilométerre északra, a Sajó és a Bódva által határolt területen fekszik, közel az Aggteleki Nemzeti Parkhoz. Környező települések: Felsőtelekes (3 kilométer), Szuhogy (4 kilométer). A legközelebbi városok: Rudabánya (9 kilométer), Szendrő (9 kilométer) és Kazincbarcika (25 kilométer). A falu határában emelkedő Dolinka-dombon vaskori temetőt tárt fel az 1959–1964 között itt ásató Patay Pál.'),
    ('Alsótold', 'A Novohrad-Nógrád UNESCO Globális Geopark települése. A Cserhát dombság szívében, Pásztótól 12 kilométer-re nyugatra fekszik, a 2122-es és a 2123-as utak találkozásánál. A szomszédos települések: Felsőtold 2 kilométer-re északra és Cserhátszentiván 3 kilométer-re délnyugatra helyezkedik el. Vasútállomása nincs. Az első fennmaradt oklevél, amely a település nevét említi, 1265-ből való, s ezt az időpontot tekintik a falu keletkezési idejének.'),
    ('Alsóvadász', 'A Cserehát dombvidék déli részén, a Vadász-patak mellett fekszik, Szikszó városától 5 kilométer-re északra, Miskolctól 22 kilométer-re északkeletre. A terület az őskor óta lakott. Ezt bizonyítja a 70-es években megtalált kőbalta, amely jelenleg a miskolci Herman Ottó Múzeumban tekinthető meg. A honfoglalás után, a 11. században az Aba nemzetség alapította itt Alsóvadászt, az 1906-ban vele egyesített Jánosdot és egy harmadik falut, Vízvölgyet (Wyzwelg) is.'),
    ('Alsózsolca', 'A Sajó bal partján, Miskolctól 10 kilométerre kelet-délkeletre fekszik. Gyakorlatilag már egybeépült a tőle északra elterülő Felsőzsolca várossal, ahova Miskolcról helyi autóbusszal is el lehet jutni. Szomszédos település még Sajólád 4 kilométerre dél-délkeletre helyezkedik el. A terület az őskor óta lakott. A község helyén már a 10–11. századtól kezdve éltek magyarok.'),
    ('Alsóörs', 'További szomszédos települései Lovas, Paloznak és Felsőörs. Szőlővel beültetett lankáin kezdődik a csopaki borvidék. Alsóörs történelmi településközpontja a Balaton partjától bő egy kilométerre, a tavat kísérő hegyek lábánál húzódó „Római út” mellett jött létre. Belterületi szakasza nagy részén Endrődi Sándor nevét viseli. Vasúton a település a Börgönd–Szabadbattyán–Tapolca-vasútvonalonérhető el.'),
    ('Alsóújlak', 'Vasvártól 5 kilométerre északkeletre fekszik. A közvetlenül határos települések: észak felől Rum, kelet felől Kám, dél felől Oszkó, nyugat felől pedig Vasvár. Korábban valószínűleg a központján is keresztülhaladt, de a régi nyomvonal ma már csak alsóbbrendű mellékútnak minősül, 87 101-es számozással. A vonalnak egykor egy megállója is volt a község határai között, a szomszéd falu nevét viselő Oszkó megállóhely, de az az 1970-es években, nyomvonal-korrekció miatt megszűnt.'),
    ('Ambrózfalva', 'Szomszédos települések: észak felől Nagyér (2 kilométerre), délkelet felől Mezőhegyes (9 kilométerre), dél felől Pitvaros (3 kilométerre), délnyugat felől Csanádalberti (6 kilométerre). Északnyugat felől Tótkomlóshoz tartozó külterületek határolják, illetve egy ponton északkelet felől is határos a várossal, annak központja azonban közel 10 kilométer távolságban helyezkedik el.'),
    ('Anarcs', 'A környező más települések: Pap 9, Nyírlövő 14 kilométerre északkeletre, Lövőpetri 10 kilométerre keletre, Szabolcsbáka 5 kilométerre délkeletre, Gyulaháza 6 kilométerre délre és Ajak légvonalban alig 4 kilométerre (közúton azonban 12 kilométerre) nyugatra. A Kisvárdát Vásárosnaménnyal összekötő 4108-as út mentén fekszik, ezen érhető el mindkét végponti város felől.'),
    ('Andocs', 'A Dunántúl egyik legfontosabb zarándokhelye, és része a Balatonboglári borvidéknek is. A település gazdag történelmi múlttal rendelkezik, amely az Árpád-korig nyúlik vissza. Nevezetességei közé tartozik a híres andocsi kegyhely, amely a római katolikus zarándokok számára fontos búcsújáró hely. A falu évszázadokon át megőrizte hagyományait és vallási szerepét, emellett jelentős kulturális és építészeti értékeket is magában rejt, mint például a ferencesek által emelt barokk templom.'),
    ('Andornaktálya', 'A Bükk-vidék Alföldbe simuló legdélibb nyúlványai között, az Egri-Bükkalja délnyugati szélén, az Eger-patak völgyében fekszik, a megyeszékhely Eger déli szomszédjában, azzal szinte teljesen egybeépülve. Településszerkezete szerint dombvidéki sorfalu. Csaknem 5 kilométer hosszú. A további szomszédos települések: északkelet felől Ostoros, dél felől Nagytálya, nyugat felől Demjén, északnyugat felől pedig Egerszalók.'),
    ('Andrásfa', 'Településszerkezete szerint dombvidéki sorfalu. A szomszédos települések: Petőmihályfa 3 kilométerre északra, Hegyhátszentpéter 5 kilométerre északra és Telekes 4 kilométerre délnyugatra helyezkedik el. Az említett városokkal és szomszédos településekkel menetrend szerinti autóbuszok kötik össze. Határában őskori régészeti leleteket találtak. Első fennmaradt írásos említése 1404-ből való (Andreasfalua), de valószínűleg már az Árpád-korban létezett. 1450-ben Poss.'),
    ('Annavölgy', 'Csak 1997-ban vált önálló településsé, addig Sárisáp része volt. Területén a középkorban egy Ugan (Vgan, Ogan) nevű falu állt. A legrégibb írás 1181-ből maradt fenn róla. Ebben az esztergom-szentkirályi keresztesek birtokaként, Tokod és Munkád szomszédaként szerepel. Egy másik, 1193-ből való oklevélben Hugan alakban tűnik fel, s megtudhatjuk, hogy ide Ebszőny-ből út vezetett. 1269-ben Ogan, 1284-ben Vgan alakban írták a nevét.'),
    ('Apagy', 'A közvetlenül határos települések: észak felől Nyírtét, északkelet felől Nyíribrony, kelet felől Levelek, délkelet felől Magy, dél felől Kállósemjén, nyugat felől Napkor, északnyugat felől pedig Sényő. Nyírtéttel, és azon keresztül Székellyel a 4103-as út köti össze. A 13. században keletkezett falut a legrégebbi fennmaradt írások Opag néven említik.'),
    ('Apaj', 'A Kiskunsági Nemzeti Park nyugati határán fekszik, Budapesttől 50 kilométerre délre, Dömsödtől és a Ráckevei-Dunától 8 kilométerre keletre. A szomszédos települések: északkelet és kelet felől Bugyi, dél felől Kunszentmiklós, nyugat felől Dömsöd, északnyugat felől pedig Kiskunlacháza. Kevés híja van annak, hogy nem határos délnyugat felől még Tass községgel is.'),
    ('Aparhant', 'A falu Bonyhádtól 8 kilométer-re északnyugatra, Szekszárdtól 28 kilométer-re nyugatra, a Völgység szívében fekszik, melyet északról a Tolnai-Hegyhát, délről a Mecsek és keletről a Szekszárdi-dombság vesz körül. A település legmagasabb pontjának, az Apari-szőlőhegynek tengerszint feletti magassága 226 méter, a legmélyebbé, az Apari 5-ös halastó vízszintjéé pedig 118 méter.'),
    ('Apc', 'A Zagyva folyó völgyében, annak bal partján fekszik. Településszerkezete szerint többutcás sorfalu. A közvetlenül határos települések: észak felől Jobbágyi, északkelet felől Szűcsi, kelet felől Rózsaszentmárton, dél felől Petőfibánya, délnyugat felől Zagyvaszántó, nyugat felől Palotás, északnyugat felől pedig Szarvasgede. A legközelebbi város a tőle délre, 9 kilométer-re lévő Lőrinci.'),
    ('Apostag', 'A Duna bal partján, Budapesttől délre 76, a dunaföldvári Beszédes József hídtól északra 13 kilométerre található. A szomszédos települések: észak felől Dunavecse, délkelet felől Solt, dél felől Dunaegyháza, nyugat felől Baracs és Kisapostag, északnyugat felől pedig Dunaújváros. E három utóbbi a folyó túlsó partján fekszik. Déli szomszédjával, Dunaegyházával az 5105-ös út köti össze.'),
    ('Apácatorna', 'Devecsertől 12 kilométerre nyugatra fekszik, a Torna patak völgyében. A szomszédos települések: észak felől Karakószörcsök (2 kilométerre), északkelet felől Tüskevár (2 kilométerre) és Somlójenő (5 kilométerre), dél felől Szentimrefalva (5 kilométerre), délnyugat felől Veszprémgalsa (2 kilométerre), nyugat felől pedig Kisberzseny (2 kilométerre). Központján azonban, annak főutcájaként csak a 7326-os út húzódik végig, ez kapcsolja össze Veszprémgalsával is.'),
    ('Apátfalva', 'Makótól 10 kilométerre délkeletre, a magyar–román határ közvetlen közelében fekszik, a Maros jobb partján, a Körös–Maros Nemzeti Park határán. A kelet felől szomszédos településsel, Magyarcsanáddal teljesen egybeépült. További szomszédjai: észak felől Királyhegyes, dél felől Nagycsanád (Cenad), nyugat és északnyugat felől pedig Makó.'),
    ('Apátistvánfalva', 'Önálló önkormányzata van, mely társközségeivel (Kétvölgy és Orfalu) közösen működteti hivatalát, a körjegyzőséget és alapellátást nyújtó intézményeit. A település az Őrségi Nemzeti Park területén, az osztrák-magyar-szlovén hármas határnál, az osztrák határátkelőtől 10, a szlovén határátkelőtől 3 kilométerre található. Területét a 7456-os, a 7457-es és a 7458-as út érinti.'),
    ('Apátvarasd', 'Pécsváradtól 9 kilométerre északkeletre fekszik. A környező települések: észak felé Mecseknádasd, kelet felé Erdősmecske, dél felé Lovászhetény, nyugat felé pedig Zengővárkony. Zsáktelepülés, közúton csak egy irányból közelíthető meg, a 6-os főútról Mecseknádasd és Zengővárkony közt nagyjából félúton kelet felé letérve, az 56 128-as számú mellékúton helyezkedik el.'),
    ('Aranyosapáti', 'A szomszédos települések: észak felől Újkenéz, északkelet felől Tiszaadony, délkelet felől Tiszavid, dél felől Gyüre, délnyugat felől Lövőpetri, nyugat felől Nyírlövő, északnyugat felől pedig Tornyospálca. Aranyosapáti 1950-ben keletkezett két falu, Kopócsapáti és Révaranyos egyesüléséből. Révaranyos maga is két középkori falu, Aranyos és Bács összeolvadásából jött létre a 17. század végén.'),
    ('Aranyosgadány', 'A Baranyai-dombságban fekszik, Pécstől mintegy 15 kilométerre délnyugatra. Két különálló településrésze Aranyos és Keménygadány vagy Gadány. Előbbi a közigazgatási terület nyugati széle közelében terül el, míg utóbbi, jóval kisebb kiterjedésű községrész Aranyostól jó másfél kilométerre délkeletre esik. A szomszédos települések: északkelet felől Pellérd, délkelet felől Görcsöny, nyugat felől Zók, északnyugat felől pedig Bicsérd.'),
    ('Arka', 'A megyeszékhely Miskolctól közúton 55 kilométerre északkeletre fekszik, a Zempléni-hegységnek a Hernád völgye felé lefutó nyugati lábainál. A legközelebbi szomszéd település a falu központjától 3 kilométerre délnyugatra fekvő Boldogkőváralja. További határos települések: észak felől Korlát, északkelet felől Fony, kelet-délkelet felől Baskó, nyugat felől Hernádcéce, északnyugat felől pedig Vizsoly.'),
    ('Arló', 'Szomszédos települések Ózdon kívül: délre Járdánháza 3 kilométer-re, északnyugatra Borsodszentgyörgy 6 kilométer-re. Az Arlói-tó a 20. század elején keletkezett: a bányászati tevékenység következtében a Csahó-hegy homokkőrétegei elmozdultak, és a suvadás elzárta a patak útját, 8,5 hektáros tavat hozva létre. Neve feltehetően a sast jelentő ószláv orlov szóból származik.'),
    ('Arnót', 'A Sajó völgyében fekszik, a megyeszékhely Miskolctól 6 kilométerre keletre. A környező települések: észak felől Sajópálfala (6 kilométer), északkelet felől Szikszó, kelet felől Onga (6 kilométer), dél felől Felsőzsolca (2 kilométer), nyugat felől pedig Miskolc (6 kilométer). Neve német személynévből származik. Valószínűleg az Árpád-kori Arnold nevű birtokosáról kapta.'),
    ('Aszaló', 'Aszaló határos Szikszó várossal (5 kilométer), valamint Kázsmárk (6 kilométer), Halmaj (7 kilométer), Szentistvánbaksa (12 kilométer), Alsóvadász, Megyaszó és Alsódobsza községekkel. A település a Hernád-völgy alsó részén található, jó termőföldekkel rendelkezik. A község délkeleti oldalát a Hernád folyó, míg északnyugati oldalát szőlőművelésre alkalmas hegyek határolják.'),
    ('Aszód', 'Neve a középkorban Aza, Aszó, Azow, Azzow, a török időkben Azzoo, Aszód alakban fordul elő. A településnév etimológiája a ''száraz völgy'', ''időszakos vízfolyás'' jelentésű ''aszó'' főnévre vezethető vissza, melyhez a -d helynévképző járult. Aszód a Galga-patak völgyében, Gödöllőtől 14, Hatvantól 16 kilométer-re fekszik. Tengerszint feletti magassága: 120–250 méter.'),
    ('Aszófő', 'A Tihanyi-félsziget tövében fekszik, a Balaton északi partján, a tó nyugati medencéjének északkeleti szélén. Keresztül folyik rajta a Tavi-séd, vagy más néven Vékény-patak. Itt kezdődik és Zánkáig tart a balatoni karsztos vidék. A sovány legelőkön csoportosan álló kökény-, vadrózsa-, galagonya- és borókabokrok, valamint a mindenfelé előforduló fehér sziklák egyedi hangulatot kölcsönöznek a tájnak.'),
    ('Attala', 'A település két kistáj – Észak-Zselic és Dél-Külső-Somogy – találkozásánál helyezkedik el. A két kistájat a Kapos választja el egymástól, mely a község déli határán folyik. A szomszédos települések Csoma, Kapospula, Nagyberki és Szabadi. Szentivánpuszta nevű külterületi településrésze, amely a központtól mintegy öt kilométerre északnyugatra fekszik, a 6521-esből nyugat felé kiágazó 65 161-es számú mellékúton érhető el.'),
    ('Babarc', 'Legmagasabb pontja a 224 méteres Salamon-hegy. A szomszédos települések: észak felől Kisnyárád, kelet felől Lánycsók, dél felől Nagynyárád, délnyugat felől Szajk, északnyugat felől pedig Liptód. Belterülete az 57-esről észak felé letérve, a Liptód központjáig vezető 56 113-as számú mellékúton érhető el. Az első emberi tevékenységre a területen kora őskori leletek utalnak, de jelentős újkőkorszaki kerámialeletekre, valamint avar és római sírokra is bukkantak a környéken.'),
    ('Babarcszőlős', 'A Villányi-hegység nyugati részének északi lábánál helyezkedik el, a megyeszékhely Pécstől 25 kilométerre délre. A szomszédos települések: észak felől Ócsárd, kelet felől Szava, délkelet felől Diósviszló, délnyugat felől Hegyszentmárton, nyugat felől Siklósbodony, északnyugat felől pedig Kisdér. Nevének első írásos említése az 1332-es pápai tizedlajstromban maradt fenn, Popruzeuleuse formában helyezkedik el.'),
    ('Babosdöbréte', 'A Zalai-dombság területén, a Göcsejben, a Pálosfai-patak völgyében fekszik Zalaegerszeg határától két kilométerre nyugatra. A község különálló részei Kökényesmindszent és Rám. A falu korábban is szeres település volt, több részből állt. Valaha még két - ma már eltűnt - falurésze is volt: Ákosházapuszta ésSárkányrét. Babosdöbréte első írásos említése 1128-ból maradt fenn, amikor is Zalavár várszolgái éltek itt.'),
    ('Babócsa', 'Már a római korban is lakott terület volt, az Árpád-korban pedig fontos központként szerepelt. A település egyik legjelentősebb nevezetessége a babócsai földvár, amely a középkorban védelmi szerepet töltött be. A község híres továbbá a minden év tavaszán megrendezett nárciszünnepéről, amely a környező erdőkben nyíló vadnárciszok virágzását ünnepli.'),
    ('Babót', 'Kapuvártól délkeletre 4, a megyeszékhely Győrtől nyugatra 53 kilométerre található. A környező települések: észak felől Veszkény, északkelet felől Szárföld, dél felől Kisfalud, nyugat felől pedig Kapuvár. Közigazgatási területe délkeleti irányból még az amúgy kissé távolabb fekvő Bogyoszló külterületeivel is érintkezik.'),
    ('Badacsonytomaj', 'Népessége alapján a megye és a Közép-Dunántúl legkisebb városa. A település területéhez tartozik a Badacsony hegy nagyobbik része, az ősi tomaji faluközpont, Badacsonyörs, valamint a nagy idegenforgalmú, nagyrészt szőlőterületekből, borházakból, vendéglőkből, üdülőépületekből álló Badacsony településrész. Szomszédos települések: Ábrahámhegy, Badacsonytördemic, Káptalantóti, Nemesgulács és Salföld.'),
    ('Badacsonytördemic', 'A Badacsony északnyugati oldalán fekszik. Hozzá tartozik a központjától délkeletre fekvő Badacsonylábdihegy üdülőterület. Külterületeinek jelentős hányada a Balaton-felvidéki Nemzeti Park részét képezi. A közvetlenül határos települések: észak felől Nemesgulács, kelet felől Badacsonytomaj, nyugat felől Szigliget, északnyugat felől pedig Kisapáti. Balatoni vízterületei révén dél felől határos még a tó déli partján fekvő Balatonfenyvessel is.'),
    ('Bag', 'A Gödöllői-dombság északkeleti oldalán, a Galga-patak jobb partján fekszik, Budapesttől 39, Gödöllőtől 13 kilométerre kelet-északkeletre. A közvetlenül határos települések: észak felől Aszód, kelet felől Hévízgyörk, délkelet felől Galgahévíz, dél felől Vácszentlászló, délnyugat felől Gödöllő (Máriabesnyő), északnyugat felől pedig Domony.'),
    ('Bagamér', 'A szomszédos települések a határ magyar oldalán: észak felől Nyírábrány, északnyugat felől Vámospércs, nyugat felől Újléta, dél felől pedig Álmosd. Határszéle keleten több mint 14 kilométer hosszan egybeesik az országhatárral. A legközelebbi települések abban az irányban Érsemjén (Șimian), Érkenéz (Voivozi) és Érselénd (Șilindru). Központja azonban csak egy mellékúton érhető el, a Vámospércs-Álmosd-Létavértes közti 4806-os úton.'),
    ('Baglad', 'Közigazgatásilag a rédicsi körjegyzőséghez tartozik.Magyarország harmincnegyedik legkisebb települése, lakosainak száma 50-nél is kevesebb. Munkanapokon viszonylag sűrűn közlekednek az autóbuszok a település és Lenti között, hétvégén azonban csak egy járat érinti. A településre utaló első fennmaradt említés 1715-ből való. A Baglad név 1773 óta használatos.'),
    ('Bagod', 'Az itt nagyjából nyugat-keleti irányt követő Zala bal (északi) parti oldalán fekszik, a megyeszékhely Zalaegerszeg nyugati szomszédságában, a város központjátől 5 kilométerre. A Zala völgye ezen a szakaszán viszonylag keskeny, alig egy kilométer széles. Területén korábban több önálló település osztozott, amik ma mind – részben még különálló, részben már többé-kevésbé összenőtt – településrészei.'),
    ('Baj', 'Baj a Gerecse nyugati lábánál, Tata tóvárosi városrészétől keletre, közvetlen közelében fekszik. A szomszédos várossal a Baji út köti össze, mely a Petőfi Sándor utcában folytatódik. Hossza a község központjáig 2,7 kilométer. Baj közúton csupán Tatán keresztül közelíthető meg, az említett 11 135-ös számú mellékúton, de határszélét északon érinti az 1128-as út is.'),
    ('Baja', 'Baja Magyarország déli részén, a Duna bal partján helyezkedik el. Jelentős kikötőváros és közlekedési csomópont. Fontos regionális szerepet tölt be gazdasági, kulturális és idegenforgalmi és oktatási szempontból helyezkedik el. A Sugovica (a Duna egyik mellékága) partján fekszik, mely meghatározza a település arculatát és hangulatát is. Gyakran emlegetett beceneve "A halászlé fővárosa".'),
    ('Bajna', 'A település a Gerecse keleti részén, a Zsámbék-Bajnai-dombvidéken fekszik Budapesttől nyugati irányban körülbelül 45 kilométerre, az Esztergomot és Tatabányát összekötő képzeletbeli vonalnak majdnem pontosan a közepénél. Szintén a község területén ér véget a Nyergesújfalutól idáig vezető 1125-ös út, és itt indul az Epölön és Máriahalomon át Únyig tartó 1122-es.'),
    ('Bajánsenye', 'A tájegység második legjelentősebb települése, gazdasági és kulturális központ. Lenti felől a 7416-os út vezet a faluba, melynek nyugati szélén határátkelőhely van Szlovéniába. Infrastruktúrája jó: telefon, földgáz, vezetékes víz és csatorna az egész faluban van. A szomszédos települések: Őriszentpéter, Kercaszomor, Kerkáskápolna és Magyarföld, valamint a határ túloldalán Őrihodos.'),
    ('Bajót', 'A Közép-Dunántúlon, a Gerecse északi részén fekszik, a hozzá legközelebbi várostól, Nyergesújfalutól mintegy 5 kilométerre. Bajót és környéke az őskortól lakott helynek számít, az itt talált régészeti leletek erről tanúskodnak. A település határában az Öreg-kő keleti, hatalmas sziklafalában található a Jankovich-barlang bejárata. A barlangban őskori leleteket, köztük az ősember solutréi és magdaléni kultúrájának számos ritka és érdekes emlékét, finoman kidolgozott kőeszközöket és csonteszközöket találtak.'),
    ('Bak', 'A Zalai-dombság területén, a Göcsejben, a Felső-Válicka patak völgyében fekszik a megyeszékhely Zalaegerszegtől körülbelül 12 kilométerre délre. Az Észak-Zalai Térségi Társulás tagja. Letenye térségétől a Becsehelyről induló 7536-os út vezet idáig, délnyugati szomszédaival pedig a Pákáig húzódó 7543-as út köti össze.'),
    ('Bakháza', 'Első írásos említése 1453-ból származik, később pusztaként Rinyaújnéphez került. Az 1913-as évtől ismét önálló község lett, majd a 20. század során számos gazdasági és közösségi fejlődésen ment keresztül, de 1963-ban közös tanácsot alakítottak Háromfával.'),
    ('Bakonszeg', 'A Berettyó–Kálló közén, a Berettyó jobb partján fekszik. A legközelebbi város a tőle kelet-északkeleti irányban 7 kilométerre fekvő Berettyóújfalu. További szomszédai: dél felől Zsáka, nyugat felől Nagyrábé, északnyugat felől pedig Bihartorda. A település központján nyugat-keleti irányban végighúzódik a Biharnagybajom-Berettyóújfalu közti 4213-as út, ezen érhető el a 4-es és a 47-es főutak felől is.'),
    ('Bakonya', 'A Nyugati-Mecsekben fekszik, Pécstől mintegy 15 kilométerre. Közigazgatási területe kelet felől Kővágótöttössel, dél felől Bicsérddel, nyugat felől Bodával, északnyugat felől pedig Hetvehellyel szomszédos, és észak-északnyugat felől csúcspontosan határos Bükkösddel is. Később, a Krisztus előtti 3–4. században a feltárt leletek szerint kelták lakták.'),
    ('Bakonybánk', 'A Bakony keleti lábánál, a Bakonyalja és a Kisalföld határán fekszik. Mellette folyik a cuhai Bakony-ér. Első írásos említése 1340-ből mardt fenn. A neve a középkori személy- és méltóságnévből, a Bán-ból származik. A török hódoltság idején elpusztult. A 18. század középétől kezdett újra benépesülni. Ekkortól az Esterházy, a Hunkár, a Stróbel, a Potyondi és a Dombay családoknak voltak itt birtokai.'),
    ('Bakonybél', 'Az Öreg-Bakony közepén, a Bakony legmagasabb hegye, a 709 méter magas Kőris-hegy közelében, a Gerence-patak völgyében fekszik. A legközelebbi város a 16 kilométerre lévő Zirc. Első fennmaradt írásos említése 1083-ból való (Beli). A település története mindvégig összefonódott a bencés monostoréval, melyet I. Az Árpád-korban jelentős szellemi központ volt. 1023–1030 között itt remetéskedett Szent Gellért, előtte pedig Szent Günter.'),
    ('Bakonycsernye', 'Nyugatról a Tési-fennsík karsztja emelkedik, a Gaja patakot löszdombság keretezi. Nevét a fekete jelentésű szláv cserny szóból vezetik le. A 81-es számú Székesfehérvár-Győr főútról Mórnál lekanyarodva, illetve a 82-es számú Veszprém-Győr főútról Zircnél letérve közelíthető meg, mindkét irányból a 8216-os számú úton helyezkedik el. Vasútállomása nincs.'),
    ('Bakonygyirót', 'Első fennmaradt írásos említése 1237-ből való, Gyrolt formában helyezkedik el. Neve a Gerald személynév német alakjából származik. A 13. századtól a 18. századig a cseszneki várhoz tartozott. A török hódoltság idején elnéptelenedett. A 18. századtól új birtokosai, az Esterházy család tagjai kezdték újból benépesíteni, elsősorban német telepesekkel.'),
    ('Bakonyjákó', 'Az Öreg-Bakony nyugati szélén helyezkedik el, a legközelebbi várostól, Pápától 15 kilométerre délkeletre. A közvetlenül határos települések: észak felől Nagytevel és Homokbödöge, északkelet felől Ugod, kelet felől Bakonybél, délkelet felől Szentgál, Csehbánya és Németbánya, dél felől Farkasgyepű, délnyugat felől Magyarpolány, nyugat felől Ganna, északnyugat felől pedig Döbrönte.'),
    ('Bakonykoppány', 'A Bakonyalján, a legközelebbi várostól, Pápától mintegy 16 kilométerre fekszik. Árpád-kori település. Első fennmaradt írásos említése 1086-ből való Cupan alakban helyezkedik el. Nevét a Koppán nemzetségtől vette, melynek nyári szállásterületén feküdt. A 16. századig a Szent Mauríciusz Monostor birtoka volt. A 16. században többször feldúlta a török, s elnéptelenedett.'),
    ('Bakonykúti', 'Bakonykúti a Kelet-Bakony lábánál, a Burok-völgy természetvédelmi terület határán, nagyon szép természeti környezetben fekszik. A településen áthalad az Országos Kéktúra útvonala. A legközelebbi város, Bodajk körülbelül 13 kilométerre van, a megyeszékhely, Székesfehérvár pedig 18 kilométerre. A fennmaradt oklevelekben először 1424-ben jelenik meg a neve (Kwthy).'),
    ('Bakonynána', 'Az Északi-Bakonyban, a Gaja-patak mellett fekszik, Zirctől mintegy 14 kilométerre. Zsáktelepülés, amely Dudaron át érhető el, a 8216-os útból dél felé leágazó, 82 112-es számú mellékúton. Közvetlen szomszédai közül Jásddal és Nagyesztergárral csak mezőgazdasági, illetve erdei utak kötik össze. Tengerszint feletti magassága 360-380 méter. A Nána név minden bizonnyal személynévi eredetű elnevezés, de pontos adat nincs arról, hogy kinek a nevét őrizheti a település.'),
    ('Bakonyoszlop', 'A hegyektől övezett település az Északi-Bakonyban, a Dudari-patak völgyében fekszik Zirctől mintegy 10 kilométerre északra. A közvetlenül határos települések: északkelet felől Csatka, kelet felől Súr, dél felől Dudar, délnyugat felől Nagyesztergár, nyugat felől Csesznek, északnyugat felől pedig Bakonyszentkirály. Csak nagyon kevés híja van annak, hogy nem határos délkelet felől még Cseténnyel is.'),
    ('Bakonypéterd', 'A három utcás falu a Bakony északi szélén, a Bakonyalján, a Sokorói-dombság délkeleti részén fekszik. A legközelebbi város a tőle 10 kilométerre északra lévő Pannonhalma. A megyeszékhelytől, Győrtől 26 kilométer választja el. A közlekedés java része azonban autóbusszal, a Volánbusz járataival bonyolódik le. A település határában forgalomszámláló hely is van.'),
    ('Bakonyszentiván', 'A településnek két lakott külterülete is van: Hangyálostanya és Szakácsmalom. A település kialakulása a falu honlapján szereplő adatok szerint a 13. század közepére tehető, s nevét Keresztelő Szent Jánosról kapta. A 16. században, Magyarország török hódoltsága idején ez a környék is elnéptelenedett, majd később az Esterházy család birtokába került, amely német nemzetiségű családokat telepített be.'),
    ('Bakonyszentkirály', 'A Bakony északi részén, Zirctől 12 kilométerre északra, a Dudar- és az Aranyos-patak mentén fekszik nagy vegyes erdők koszorújában. A környék már az őskorban is lakott volt. A rómaiak és az avarok is lakták a területet. Fontos hadiutak keresztezték itt egymást: egy É-D és egy Ny-K irányú. A közelben találtak is római útmaradványokat. Bakonyszentkirály két község egyesítéséből keletkezett 1926-ban.'),
    ('Bakonyszentlászló', 'A község a Bakonyalja tájegység pápai és súri részegységei találkozásánál fekszik, Pápától, Győrtől és Veszprémtől egyaránt 40-40 kilométerre. Korábban Veszprém megye Zirci kistérségéhez tartozott, de 2002. október 20-án Győr-Moson-Sopron megyébe, ezen belül a Pannonhalmai kistérségbe sorolták át. Természeti környezete átmenetet képez a Kisalföld és a Bakony között.'),
    ('Bakonyszombathely', 'Főutcája a Bakonycsernye és Mezőörs között húzódó 8208-as út, melynek mentén a település több mint 10 kilométer hosszban nyúlik el. Alacsony domblábi lejtőkre és síkságra települt. Magassága 190 és 200 méter között váltakozik. Forrásaiból a Feketevíz-ér kivételével a Cuhai-Bakony-érbe folyik a víz. Megfelelő helyi vízbázis hiánya miatt vezetékes vizét a tatabányai (táv)vezetékes karszt ivóvízhálózatból…'),
    ('Bakonyszücs', 'A Bakonyalján, a Magas-Bakony lábánál fekszik Bakonybéltől 7 kilométerre északra.. A legközelebbi város Pápa mintegy 18 kilométerre nyugatra helyezkedik el. Szücs – 1954-től: Bakonyszücs – nevének első írásos említése 1249-ből maradt fenn (Schelch), ekkor az ugodi uradalom része volt. A fennmaradt oklevelek szerint a honfoglalás idejében került a Koppán nemzetség birtokába.'),
    ('Bakonyság', 'A legközelebbi szomszéd település Bakonyszentiván helyezkedik el. Legrégibb írásos említése 1332-ból maradt fenn. Ekkor nemesek lakták. A 18. században a Meszlényi család birtoka volt. 2001-ben a lakosok csaknem 100%-a magyarnak vallotta magát. 1990: 114 fő 2001: 92 fő 2009: 50 fő A 2011-es népszámlálás idején…'),
    ('Bakonytamási', 'Határát délkelet-északnyugati irányú, 150–200 méter magas homokos, helyenként kavicsos, hosszan elhúzódó dombok alkotják. Tengerszint feletti magassága 163 méter. A földrajzi szakirodalom a Kisalföld délkelet-keleti határvonalának egyik sarokpontjaként említi, de a kistáji besorolás szerint a Pápai-Bakonyaljához tartozik. A településről dél-délkeletre tekintve az Öreg-Bakony legmagasabb pontjai, a Kék- és Kőris-hegy (csúcsán polgári légiforgalmi radar), észak-északnyugatra pedig a Pannonhalmi-dombság Szemere és Csanak nevű vonulatai láthatóak.'),
    ('Baks', 'A Tisza jobb partján, a Pusztaszeri Tájvédelmi Körzetben fekszik Szegedtől mintegy 35 kilométerre északra. Szomszédai észak felől Csanytelek, északkelet felől Szegvár, kelet felől Mindszent, dél felől Dóc, délnyugat felől Ópusztaszer, északnyugat felől pedig Tömörkény. Nyugati irányból a legközelebbi település Pusztaszer, de közigazgatási határaik nem találkoznak.'),
    ('Baksa', 'A szomszédos települések: észak felől Pécsbagota és Zók, északkelet felől Görcsöny, délkelet felől Kisdér és Hegyszentmárton, dél felől Tengeri, nyugat felől Téseny, északnyugat felől pedig Velény. A legközelebbi városok: Pécs, Szentlőrinc, Harkány és Siklós. Első írásos említése 1247-ből maradt fenn, ez Baxa, Boxa néven említi a települést. A Baksa helynév személynévi eredetű, a Boksa, Bogsa régi szláv névből ered.'),
    ('Baktakék', 'A település a Cserehát központi községe. Miskolctól 40 kilométerre északkeletre fekszik a Száraz-völgy középső részén. Egy része dombos területre épült. A csereháti dombvidék az Északi-középhegység tájai közé tartozik. Beékelődik az Észak-borsodi-karszthegység és a Hernád folyó völgye közé. A faluval közvetlenül határos települések: észak felől Alsógagy, északkelet felől Fáj, kelet felől Fancsal, dél felől Beret, délnyugat felől Selyeb, nyugat felől Abaújszolnok, északnyugat felől pedig Gagyapáti.'),
    ('Baktalórántháza', 'A Nyírség középső részén, a megyeszékhely Nyíregyházától keletre fekszik, Besenyődtől 6,5, Vajától 8, Apagytól 11, Székelytől 15, Vásárosnaménytól pedig 18 kilométerre. A közvetlen szomszédos települések: észak felől Nyírjákó, északkelet felől Rohod, kelet felől Vaja, délkelet felől Kántorjánosi, dél felől Ófehértó, délnyugat felől Besenyőd, nyugat felől Levelek, északnyugat felől pedig Nyírkércs.'),
    ('Baktüttös', 'A Zalai-dombság területén, a Göcsejben fekszik. A közvetlenül határos települések: észak felől Bak, kelet felől Söjtör, dél felől Tófej, nyugat felől pedig Zalatárnok. Főutcája a Bak-Páka között húzódó 7543-as út. Tüttös („Teu Teus”) első írásos említése Bakkal együtt 1239-ből maradt fenn. Középkori története nem ismeretes, de feltételezhető, hogy Bakkal együtt cserélt gazdát.'),
    ('Bakóca', 'Komlótól mintegy 20 kilométerre nyugatra, Kisbeszterce mellett fekszik. Zsáktelepülés, közúton csak egy útvonalon érhető el. A község központja az oroszlói letéréstől mintegy 12 kilométerre található. Neve a szláv bukovica (= bükkös) főnévből ered. Fennmaradt írás 1332-ben említi először, Bakolcha néven helyezkedik el. Birtokosai a Zichyek, a Nádasdyak, a Meltzerek és a Mailáthok voltak.'),
    ('Balajt', 'A megyeszékhelytől, Miskolctól 25 kilométerre északra, Edelény kelet-északkeleti szomszédságában, a Bódva folyó közelében fekszik. A környező települések: észak felől Ládbesenyő (8 kilométer), északnyugat felől Szendrőlád (kb. 10 kilométer), délnyugat felől pedig Edelény (kb. 4 kilométer), amely egyben a legközelebbi város is. Északkelet felől határos még Lakkal, kelet felől pedig Damakkal is, de e településekkel nincs közvetlen közúti kapcsolata.'),
    ('Balassagyarmat', 'Balassagyarmat kedvező elhelyezkedése miatt a területe már a rézkorban is lakott. A honfoglalás során a későbbi település nevét adó Gyarmat törzs telepedett itt le, első ismert írásos említése 1244-ből származik. A török hódoltság idején várát lerombolták, a város elnéptelenedett. Több sikertelen kísérlet után 1690-ben telepítették újjá a települést.'),
    ('Balaton', 'A Balaton egy tó a Dunántúlon, Közép-Európa legnagyobb tava, Magyarország vízrajzának meghatározó eleme. Könnyen felmelegedő, sekély vize kiválóan alkalmassá teszi a fürdésre és sportolásra, élővilága rendkívül gazdag, a táj változatos vulkanikus kúpjaival sok tekintetben egyedi. Típusa geológiailag a Velencei-tóhoz hasonlóan tektonikus eredetű, sekély vizű ároktó.'),
    ('Balatonakali', 'A Balaton északi partján fekszik. A közvetlenül határos települések: észak felől Dörgicse, kelet felől Balatonudvari, nyugat felől Zánka, északnyugat felől pedig Tagyon és Szentantalfa. Nagyon kevés híja van annak, hogy nem határos még északon, külterületeik révén az amúgy távolabb fekvő Balatoncsicsóval is. Természeti adottsága a Balaton gazdag halállománya, a dús vízparti legelők, és a vadban gazdag part menti erdők.'),
    ('Balatonakarattya', 'A szomszédos települések Balatonkenese, Balatonfőkajár és Csajág. A Csittény-hegy oldalában bronzkori leletek kerültek elő, amelyek az őskor óta kedvelt lakott helynek mutatják e területet. Balatonakarattya több pontján római időkből származó sírokat, leleteket találtak, amelyek azt jelzik, hogy a honfoglalás előtt is lakott hely volt e vidék. 1000 környékén a veszprémvölgyi…'),
    ('Balatonalmádi', 'A Balaton keleti medencéjének északi partján helyezkedik el, a Fűzfői-öböl közelében, az Öreg-hegynek a tóra leereszkedő lejtőjén. Az északi part egyik legnépszerűbb turisztikai célpontja, fejlődésében nagy szerepe van a megyeszékhely, Veszprém közelségének is. Népessége főleg az utóbbi években indult erős növekedésnek, lakosságszáma 2021-re már átlépte a 10 000 főt.'),
    ('Balatonberény', 'A Balatonboglári borvidék részét képező település a Balaton déli partján, Balatonszentgyörgy és Balatonkeresztúr között található, alig 4 kilométerre a Zala torkolatától. Közúton mindkét déli parti szomszédja felől a 7119-es számú mellékúton érhető el, de vasútállomása is van a Székesfehérvár–Gyékényes-vasútvonalon. Déli külterületei között található a 7-es, a 68-as és a 76-os főutak csomópontja is.'),
    ('Balatonboglár', 'A Balaton déli partján, Balatonlelle és Fonyód között található. Mintegy 6000 lakossal, egy kis kikötővel és vasútállomással is rendelkezik. A strandröplabdapályákkal rendelkező réti strand és minigolfpálya mellett vízibicikli-kölcsönzésre is lehetőség van a nyaralók és vendégek számára. Itt van a Balatonboglári borvidék hivatalos központja, és gyakran "a szőlő és bor városának" is nevezik.'),
    ('Balatoncsicsó', 'A Balatontól 8 kilométerre, a Nivegy-völgyben fekszik. A völgy szerkezetileg a Balaton-felvidék Balatonfüred és Badacsony közti szakaszára jellemző, a tóparti hegysor mögött kialakult márgás kőzetű medencék egyike. Említik Csicsói-medence néven is. A szomszédos települések: Szentjakabfa (1,3 kilométerre), Szentantalfa (2 kilométerre), Óbudavár (3 kilométerre), Monoszló (4 kilométerre), Kapolcs (9 kilométerre).'),
    ('Balatonederics', 'A község nevének első említése 1214-ből maradt fenn. A török háborúk idején hol a törökök, hol Szigliget várának magyar katonasága fosztogatta. 1572-ben a törökök porig égették. A török hódoltság után a betelepülő lakosság megélhetésének forrása hosszú ideig a szőlő- és gyümölcstermesztés volt. A 19. században a szigligeti birtok és kastély báró Puteáni Gézára szállt, aki még 1893-ban is 2246 katasztrális holdnyi földbirtokkal rendelkezett.'),
    ('Balatonendréd', 'Balatonendréd a Balaton déli partjától 5 kilométerre fekszik, Siófok és Zamárdi közvetlen szomszédságában, Budapesttől mintegy 120 kilométerre. A Balatonboglári borvidék része. Keleti szomszédjával, Ságvárral csak egy földút köti össze. Vasútja nincs, a közösségi közlekedést autóbuszjáratok biztosítják. A település területén feltárt legrégibb lelet: a régészek a Karancsó-hegyen egy honfoglalás kori lovas sírjára bukkantak.'),
    ('Balatonfenyves', 'A Balaton déli partján helyezkedik el. Déli irányból a Nagy-Berek vidéke övezi. Fonyód közvetlen nyugati és Balatonmáriafürdő közvetlen keleti szomszédja. Balatonfenyves 1958-ban jött létre Balatonmáriafürdő, Balatonkeresztúr, Fonyód és Somogyszentpál egyes területeiből. (Például Balatonkeresztúr Józseftelep és Somogyszentpál Imremajor és Pálmajor nevű részéből.) Korábban e területen főleg tanyák és vadászházak voltak.'),
    ('Balatonföldvár', 'Gyakran látogatott turisztikai célpont a magyarok és a külföldi vendégek (főleg a németek és az osztrákok) körében. 1532 hektáros kiterjedésével a megye legkisebb közigazgatási területű városa. A földvára a késő vaskorban, a kelták idején épült. Ennek a szerkezetnek a jól megőrzött árkai és halmai jól láthatók a magasparton. A várost a helyiek általában Földvár néven emlegetik.'),
    ('Balatonfüred', 'Kereskedelmi szálláshelyeken eltöltött vendégéjszakák tekintetében Magyarország hatodik legnépszerűbb települése. Ismertségét a Balaton közelsége mellett elsősorban szénsavas forrásainak (mely szén hidrogén-karbonátot, kalciumot és magnéziumot tartalmaz, ami különösen a keringési rendellenességek és a szív-és érrendszeri megbetegedések kezelésére jótékonyak) és mediterrán jellegű klímájának köszönheti.'),
    ('Balatonfőkajár', 'Pannóniában római provinciában hadi út haladt rajta keresztül, amelyen később III. Henrik német császár is hadba indult I. Endre ellen, és 1050-ben már pontosan meghatározták a település helyét az akkori térképeken helyezkedik el. A települést a tatárok és a törökök is feldúlták és megsemmisítették. Első ismert írásos emléke 1086-ból származik, amikor is Villa Quiar néven említették.'),
    ('Balatonfűzfő', 'A Balaton északkeleti csücskén, a Fűzfői-öböl partján terül el. A településhez tartozó lakott településrészek eltérő időben és különböző funkcióval jöttek létre, részben az itt létesített ipari üzemek tevékenységéhez kapcsolódva, esetenként kifejezetten azok lakótelepeként. A közvetlenül határos települések: észak felől Királyszentistván, kelet felől Papkeszi, délkelet felől Balatonkenese, délnyugat felől Balatonalmádi, északnyugat felől pedig Litér.'),
    ('Balatongyörök', 'A Balaton északi partján, a Keszthelyi-fennsík déli szélén, Keszthely és Szigliget között fekszik. Nyári időszakban rendszeres hajójárat indul Keszthelyre, valamint Balatonmáriafürdő, Szigliget és Badacsony érintésével Fonyódra helyezkedik el. A település helyén már az újkőkorszakban laktak. A rézkorból fejsze maradt fenn. A római korban kisebb telep működött a mai Szépkilátó környékén, ahol egy fürdő maradványai is láthatóak.'),
    ('Balatonhenye', 'A Henyei-hegy keleti lábánál, a Balaton északi partjától 8 kilométerre fekszik. Délről Köveskál, nyugatról Monostorapáti, északról Kapolcs, délkeletről Monoszló határolja. Balatonhenye természetföldrajzilag a Balaton-felvidék e szakaszára jellemző, a tóparti hegysor mögött megbújó medencék egyikében fekszik, a mindössze két község területét magában foglaló Monoszlói-medencében.'),
    ('Balatonkenese', 'Népszerű üdülőhely, amely a Balaton-felvidék különleges panorámáját kínálja. Vitorláskikötője és strandjai a vízi sportok kedvelőinek nyújtanak élményeket. A balatoni települések között különleges fekvésű, hiszen Balatonakarattyán kívül az egyetlen olyan Balaton parti település, amely igazából sem nem déli, sem nem északi parti.'),
    ('Balatonkeresztúr', 'A Dél-Dunántúlon, a Balaton déli partján fekszik, a Szigliget és Balatonederics közti öböllel átellenben. Közigazgatási területének kelet-nyugati irányú kiterjedése eléri a 8 kilométert, de ennek ellenére csak alig 1 kilométernyi partszakasszal rendelkezik, mert Balatonkeresztúr és a tó közé mintegy 6 kilométernyi hosszban beékelődik Balatonmáriafürdő 6-700 méter széles belterületi sávja.'),
    ('Balatonlelle', 'A Balaton déli partjának nagyjából a középső szakaszán fekszik, Siófoktól 25 kilométerre nyugatra, Budapesttől mintegy 140 kilométerre délnyugatra. A közvetlenül határos települések a tó déli parti oldalán: kelet felől Balatonszemes, délkelet felől Nagycsepely és Visz, dél felől Látrány, délnyugat felől Szőlőskislak, nyugat felől pedig Balatonboglár.'),
    ('Balatonmagyaród', 'A település területének jelentős része a Balaton-felvidéki Nemzeti Park védettsége alatt áll. A település első ismert említése 1308-ból való Magyarad formában helyezkedik el. A 14. században sűrűn cserélt gazdát, majd 1470 körül a Báthoryak tulajdonába került. A törökök már az 1530-as években jártak a településen, ám ekkor még csak az átkelőt használták.'),
    ('Balatonmáriafürdő', 'A község a Balaton délnyugati partján, Balatonfenyves és Balatonkeresztúr között fekszik a Szigliget és Balatonederics közti öböllel átellenben. Közigazgatási területe a két fenti település között elterülő 6-700 méter széles és mintegy 6 kilométer hosszú tóparti sávból áll, amely csaknem teljes egészéban belterület. A tó vízterületén határos Szigligettel és Balatongyörökkel is.'),
    ('Balatonrendes', 'Badacsony és Révfülöp között, a Balaton partjához közel fekszik. A terület már a római kortól lakott volt, ezt római villák maradványai is bizonyítják. A honfoglalás után fejedelmi szálláshely lett, melynek lakói halászattal, állattartással, nádvágással foglalkoztak. A község nevének első írásos említése 1328-ből maradt fenn. A törökök kiűzése után gyors fejlődésnek indult, 1755-től már iskolája is volt.'),
    ('Balatonszabadi', 'A település a Balatonboglári borvidék része. Nevének legrégibb ismert említése az 1332-1337. évi pápai tizedjegyzékben maradt fenn. 1660-ban Csobáncvár tartozéka volt. 1715-től a gróf Batthyány család birtokai közé tartozott. 1835-től a gróf Schmiedegg és a gróf…'),
    ('Balatonszemes', 'A Balaton déli partján fekszik, Budapesttől mintegy 130 kilométerre. A Külső-Somogyi dombvidék északi, Balatonra néző lejtőire települt, amelyek a község területén majdnem mindenütt meredek letöréssel mennek át a part menti fél-egy kilométer széles síkságba. A közvetlenül határos települések: kelet felől Balatonőszöd, délkelet felől Teleki és Nagycsepely, dél felől Rádpuszta (Balatonlelle része), nyugat felől pedig Balatonlelle.'),
    ('Balatonszepezd', 'A Balaton északi partján fekszik, a tó nyugati medencéjének a középső részén, Zánka nyugati és Révfülöp keleti szomszédságában, Balatonfüredtől 24 kilométerre nyugatra. „Szárazföldön” csak egy további szomszédja van, északnyugati irányban Kővágóörs, vízterületei révén viszont három déli parti településsel is határos: délkelet felől Balatonszemessel, dél felől Balatonlellével, dél-délnyugat felől pedig Balatonboglárral.'),
    ('Balatonszárszó', 'Egy elmélet szerint Szárszó neve feltételezhetően az 1082-ből ismert szárazaszó (száraz völgy) szóból ered, amelyet akkor Zarrosozow alakban írtak. Ez a név az idők folyamán egyszerűsödött. Ezen elmélet tarthatatlanságára Bakay Kornél mutatott rá. „Szár-aszó”-t (Balatonszárszó nevét) például kiszáradt völgyként magyarázzák, holott az aszó (Ozofeu, 1055) nemcsak kiszáradó völgyet, hanem patakot is jelent, mégpedig olyan völgyben folyó patakot, amely esős időben és olvadáskor keletkezik.'),
    ('Balatonszőlős', 'A kistelepülés a Balaton északi partján, a Balaton-felvidéken, a Pécsely–Szőlős-medence keleti részén fekszik Balatonfüredtől és a Tihanyi-félszigettől északra, a tótól 5-6 kilométerre. Északról a Nagy-Gella, keletről a Száka és a Torma-hegy határolja. A festői szépségű dombokat szőlőültetvények és pincék szegélyezte erdők veszik körül. A település szomszédai északról Tótvázsony és Hidegkút, délkeletről Balatonfüred, délről Aszófő, nyugatról Pécsely, északnyugatról pedig Barnag.'),
    ('Balatonudvari', 'A Balaton északi partján, a Balaton-felvidék középső részén helyezkedik el, a térség legnagyobb városának számító Balatonfüredtől 10 kilométerre nyugatra, a Tihanyi-félsziget szomszédságában. Különálló településrésze a központtól nyugati irányban fekvő Fövenyes üdülőterület. A közvetlenül határos települések: észak felől Pécsely, északkelet felől Örvényes, délnyugat felől Balatonakali, nyugat felől Dörgicse, északnyugat felől pedig Vászoly.'),
    ('Balatonvilágos', 'Budapest felől érkezve 90 kilométer megtétele után az első település a tó partján helyezkedik el. A tó medre itt is, mint a déli part túlnyomó részén homokos, a part közelében sokáig sekély, lassan mélyül, így az úszni nem tudók is akár több száz méterre bemerészkedhetnek a vízbe. A településen mintegy 400 család él, de a nyári szezon idején a lakók száma természetesen megnövekszik.'),
    ('Balatonújlak', 'A Balaton déli partjától mintegy 3 kilométerre, Balatonkeresztúr és Kéthely között fekszik, e községektől is 3-3 kilométerre. A Balatontól ma mintegy 3 kilométer-re található falu egykor vízparti település volt, a tó a község határáig ért. Zákonyi Ferenc, „a Balaton krónikása” egyik monográfiájában említi, hogy a község keleti határában római kori sírokat tártak fel.'),
    ('Balatonőszöd', 'A szomszédos települések: keletről Balatonszárszó, nyugatról Balatonszemes, délkeletről Szólád, délnyugatról pedig Teleki. Parti sávja körülbelül 2 kilométer hosszú, ebből azonban csak alig több, mint 500 méter a szabad partrész.…'),
    ('Balinka', 'A település három falurészből áll, melyek 2-2 kilométer távolságra esnek egymástól. Határa hullámos dombvidék. Északon a Vértes, keleten és délen a Bakony mellári fennsíkjának mészkő- és dolomitgerincei határolják. A környék legmagasabb pontja a Hársas-hegy. A községen két patak is átfolyik, a Bakonycsernyéről Balinkán át Fehérvárcsurgóig folyó Gaja-patak és egy Mór-Bodajk irányú kisebb vízfolyás.'),
    ('Balkány', 'Első írásos említése 1214-ből származik a Váradi regestrumban helyezkedik el. A település később a Gutkeled nemzetség birtoka lett, a középkori történetének legjelentősebb emléke a mai református templom. A török hódítások során a környék jelentős pusztítást szenvedett, de a törökök kiűzése után a falu gyorsan újjáépült. A Rákóczi-szabadságharc idején a helyiek aktívan részt vettek a küzdelmekben, majd a 18. és 19. század folyamán a falu fokozatosan fejlődött.'),
    ('Ballószög', 'A Kiskunsági-homokhátságon fekszik Kecskeméttől 10 kilométerre délnyugatra. A szomszédos települések: észak felől Hetényegyháza, északkelet felől Kadafalva (mindkettő Kecskemét külterületi városrésze), délkelet felől Helvécia, délnyugat felől Ágasegyháza, nyugat felől Fülöpháza, északnyugat felől pedig Kerekegyháza. Legrégibb írásos említése a 14. századból maradt fenn Ballóság néven helyezkedik el.'),
    ('Balmazújváros', 'A nagy kiterjedésű város két jellegzetes alföldi táj, a Hortobágy és a Hajdúság határán fekszik. A környező nagyobb városok közül Debrecentől 23, Hajdúböszörménytől 14, Hajdúszoboszlótól 21 kilométerre található. A város közigazgatási területét két természetes élővíz szeli át, a Hortobágy folyó és a belterületi főgyűjtő vizét befogadó Kadarcs-Karácsonyfok-csatorna.'),
    ('Balogunyom', 'A Gyöngyös-sík déli részén fekszik, a Sorok-patak mellett, a megyeszékhely,Szombathely déli szomszédságában, a város központjától 8 kilométerre. A további, közvetlenül határos települések: északkelet felől Táplánszentkereszt, kelet felől Sorkikápolna, délkelet felől Sorokpolány, dél felől Kisunyom, nyugat felől pedig Ják. Különálló településrészei: Balogfa a belterület nyugati, Nagyunyom a délkeleti és Héraháza az észak-északkeleti részén helyezkedik el.'),
    ('Balotaszállás', 'A szomszédos települések: észak felől Kiskunhalas, északkelet felől Zsana, kelet felől Pusztamérges, délkelet felől Ruzsa és Öttömös, dél felől Kelebia, délnyugat felől Kisszállás, nyugat felől pedig Kunfehértó. A régészeti leletek tanúsága szerint szarmaták…'),
    ('Balástya', 'Szomszédai még: kelet felől 10 kilométerre Dóc, délkelet felől 10 kilométerre Sándorfalva, dél felől 10 kilométerre Szatymaz és 19 kilométerre Zsombó, délnyugat felől 10 kilométerre Forráskút, nyugat felől 19 kilométerre Csólyospálos, északnyugat felől 10 kilométerre Kömpöc, 16 kilométerre pedig Csengele.'),
    ('Bana', 'A Duna teraszvidékétől egy kavicsos dombvonulat választja el. A szomszédos települések: Ács, Bábolna, Tárkány, Rétalap, Bőny és Nagyszentjános. A falura jellemző a rajta átmenő kerékpáros turizmus. A község a Cuhai-Bakony-ér és mellékerei által tagolt, 135 méteres átlagmagasságú, hullámos síkságon terül el.'),
    ('Barabás', 'A közvetlen szomszédos települések, a határ magyar oldalán: délkelet felől Beregdaróc, dél felől Gelénes, délnyugat felől Vámosatya és Tiszavid, nyugat felől pedig Tiszaadony és Tiszakerecseny. Közigazgatási határa északon több mint 17 kilométer hosszban egybeesik az államhatárral, a legközelebbi település abban az irányban Mezőkaszony (Косонь). Barabás az Árpád-kor óta lakott település.'),
    ('Baracs', 'Határszélét nyugaton a 6228-as út is érinti, de a lakott területeit elkerüli. A település két részből áll: a kisebb lélekszámú Templomosból és a falu központi részét képező, sűrűbben lakott Apátszállásból. Apátszállásnak és Templomosnak külön-külön postai irányítószáma van: Templomosé 2426, Apátszállásé 2427. A település Apátszállás nevű részén Árpád-kori temetőt és mellette templomromokat tártak fel.'),
    ('Baracska', 'Baracska és környéke a falu északi részén előkerült római kori leletek tanúsága szerint már az ókorban is lakott hely volt. Később a Bojta kun (kabar) vezértől származtatott Baracska nemzetség fészke lett. Neve már 1212-ben felbukkant fennmaradt oklevélben, akkor Boroksa alakban írták, és már templomos hely volt. Itt épült fel a Baracska nemzetség monostora Mindenszentek tiszteletére. 1212-ben Baran fia Ipolit itteni saját egyházának (eccl-e sue, quam in pr-o nomine Boroksa construxit in honore…) adta baracskai birtokát a hozzá tartozó…'),
    ('Baranyahídvég', 'Az Ormánság északi részén, a Fekete-víz mellett fekszik Harkánytól nyugatra, Vajszló és Kémes között. Pécsről Vajszlón át közelíthető meg a legegyszerűbben helyezkedik el. Baranyahídvég (Hídvég) neve először középkori forrásokban maradt fenn, Hydwegh néven helyezkedik el. Később Kishídvég alakban tűnt fel, akkor a nyúlszigeti apácák birtokolták. A török hódoltság alatt is lakott hely maradt, de a török felszabadító háborúk alatt az itt folyó hadmozdulatok miatt lakosai elmenekültek, a település elnéptelenedett.'),
    ('Baranyajenő', 'Baranyajenő és környéke már az ókorban lakott hely volt, a falu határában római korból származó leletanyag került felszínre. A település egykor a Jenő törzsbeliek lakhelye volt. Fennmaradt oklevelek 1283-ban említették először Jenew írásmóddal. Baranyajenő (Jenő) birtokosai a nyúlszigeti (Margit-sziget) apácák voltak, akiknek kolostoruk is állt itt egykor.'),
    ('Baranyaszentgyörgy', 'A közvetlenül határos települések: északkelet felől Baranyajenő, délkelet felől Mindszentgodisa, délnyugat felől Tormás, északnyugat felől pedig Gödre helyezkedik el. Kis híján határos még dél felől Bakócával is. Utóbbi a belterület déli szélén húzódik, s onnét még továbbhalad Tormáson át Szágyig.'),
    ('Barbacs', 'Barbacs a Hanság egyik legdélebbi települése, az egykori Tóköz egyik nyugati falva Csornától 5 kilométerre északkeletre helyezkedik el. Határában van a 26,4 hektár területű Barbacsi-tó, amely a Hanság maradványaként természetvédelmi oltalom alatt áll a hozzá tartozó 280 hektár területtel együtt. Sekély vizében halat tenyésztenek és nádat termelnek.'),
    ('Barcs', 'A város gazdag történelemmel rendelkezik, amely egészen a római korig nyúlik vissza. A középkorban jelentős birtokos családok, például a Marczali család birtokolták a települést. A 19. században Barcs fejlődése felgyorsult, különösen a közlekedési útvonalak kiépítésének köszönhetően helyezkedik el. A város ipari és kereskedelmi központtá vált, és 1979-ben városi rangot kapott.'),
    ('Barlahida', 'A Zalai-dombság területén, a Göcsej domboldalain fekszik. Szeres település, egy domb tetejére épült. Lentivel és Zalaegerszeggel autóbuszjáratok kötik össze. Barlahida első fennmaradt írásos említése 1394-ből való. A 15. század során sokszor cserélt gazdát, illetve sokat vitázott a környező településekkel. Számottevő fejlődést ebben az időszakban nem tudott elérni.'),
    ('Barnag', 'A település a Veszprémi-fennsík és a Balaton-felvidék találkozásánál fekszik Veszprémtől 18, Nagyvázsonytól mintegy 5 kilométerre. A falu nevét említő legrégibb, 1284-ből fennmaradt okirat szerint Barnagon egymás mellett álltak a Gatal nemzetségbeli Péter fia III. Gatal és Gatalon fiainak házai. A vár fel is épült, romjait, melyek ma is láthatók a falutól délkeleti irányban, Zádor-vár (Pusztavár) néven ismerik, de nem a Barnag határában fekvő Szabadhegyre épült, hanem…'),
    ('Basal', 'Szigetvár északi szomszédságában fekszik, attól 6, Pécstől 40 kilométerre. Nevét fennmaradt oklevelek 1217-ben említetik először. Basal akkor a Győr nemzetség ősi birtoka volt, melyet Endes fia Péter szerzett meg, de birtokrésze volt a településen Endes Péter nevű testvére leányának, Jechának is, aki a maga részét 1231 előtt sógorának, Monoszlai Makár fiának eladta.'),
    ('Baskó', 'A Zempléni-hegység középső részén fekszik, a megyeszékhely Miskolctól bő 60 kilométerre északkeletre, a legközelebbi várostól, Abaújszántótól pedig mintegy 16 kilométerre szintén északkeletre. Erdőkkel borított külterületén hegyek magasodnak, határszéle közelében négy hegycsúcs a 650-700 méter magasságot is eléri. A szomszéd települések: észak felől Mogyoróska, kelet felől Erdőhorváti, dél felől Erdőbénye és Sima, délnyugat felől Boldogkőújfalu, nyugat felől Boldogkőváralja, északnyugat felől pedig Arka és Fony.'),
    ('Battonya', 'Első említése 1340-ból Both Anya, amely egy Anya nevű, nagy határral bíró egykori település Both nevű személy által birtokolt részére utal. Egy másik magyarázat szerint a pelikán régi magyar nevéről (patonya) kapta a nevét. Népetimológiaként Batu tanya is ismert, ami szerint a tatár kán harcosainak szálláshelye lett volna itt. Nevének ejtése különleges: aki valaha is élt Battonyán, az rövid t-vel, Batonyaként mondja.'),
    ('Batyk', 'A legészakibb Zala menti település. A Sümeg és Zalaegerszeg között húzódó 7328-as út mellett fekszik, a két várostól közel azonos távolságra, 20-22 kilométerre. A falu határában lévő ősgyep természetvédelmi terület. Batyk első fennmaradt említése 1251-ből való Bogk néven, amely a szomszédos Türje prépostságának tulajdonát képezte. A 14. és 15. században számtalanszor cserélt tulajdonost elsősorban nagy értéke miatt.'),
    ('Baté', 'Kaposvártól 15 kilométerre keletre, a Kapos-völgy szívében fekszik. A közvetlenül határos települések: észak felől Fonó, kelet felől Mosdós, dél felől Kaposkeresztúr, délnyugat felől Kaposhomok, nyugat felől pedig Taszár. Megállási pontja van a (Budapest-)Dombóvár–Gyékényes-vasútvonalnak is, melynek jelentős a személy- és teherforgalma. A falu délnyugati szélén lévő Baté vasútállomáshoz négy sínpáros rakodó-pályaudvar is tartozik.'),
    ('Bazsi', 'Nyugaton Sümegcsehi, délen Zalaszántó, keleten Sümegprága, északkeleten Sümeg határos vele. A község területe természetföldrajzilag a Bakony délnyugati részéhez tartozik, melybe észak-északkelet felől benyúlik a Marcal-medence lapálya. Délről, délnyugatról 200–250 méter tengerszint feletti magasságú dombok, a Keszthelyi-fennsík bazalthegyeinek erdős nyúlványai koszorúzzák (Kovácsi-hegy, Tátika-hegyvonulat).'),
    ('Becsehely', 'A település az ország délnyugati részén, a Zalai-dombságban, az Egerszeg–Letenyei-dombság területén fekszik, a térség legnagyobb városától, Nagykanizsától 16 kilométerre délnyugatra, Letenyétől 5, a horvát határtól pedig nagyjából 8 kilométerre északkeletre. Zalaegerszeg térségével a 7536-os út, déli szomszédaival – Tótszentmártonnal és Tótszerdahellyel – a 6836-os út kapcsolja össze.'),
    ('Becske', 'A település a Cserhát hegységben, a Galga-patak völgyében, a Szanda-hegy lábánál fekszik. A legközelebbi város Balassagyarmat (20 kilométer). Föutcája a 2108-as út, ezen érhető el Aszód és Balassagyarmat irányából is. Bercellel a 2138-as út köti össze. A település első írásos említése 1272-ből maradt fenn (Bechke). Neve feltehetően a Benedek személynévből származik.'),
    ('Becskeháza', 'A kis zsáktelepülés Miskolctól északra, közúton 80 kilométerre fekszik Tornaszentjakab és Hidvégardó között, a Bódvától keletre. Autóbusszal a Volánbusz 4136-os járatával érhető el. Hidvégardó 5 kilométer-re, Tornaszentjakab 5 kilométer-re, Bódvalenke 6 kilométer-re, Tornanádaska 7 kilométer-re, a legközelebbi város, Szendrő pedig kb. 30 kilométer-re van a törpefalutól.'),
    ('Becsvölgye', 'Göcsejben, a Zalai-dombság területén fekszik. Nyugati határánál a Salomfai-patak, keleti határánál a Kislengyeli-patak fut. Mindkettő a Csertába folyik. A két patak völgyében és a köztük lévő magasabb területen épült a falut alkotó hét kisebb településrész (szer, göcseji elnevezéssel szeg): Barabásszeg, Kereseszeg, Kislengyel, Pajzsszeg, Salomfa, Vargaszeg és Vörösszeg.'),
    ('Bedegkér', 'Az út előbb Kér településrészre érkezik – ott ágazik ki belőle nyugat felé, Somogyegres irányában a 65 125-ös út –, majd dél felé továbbhaladva érhetjük el a község központi településrészét, Bedeget. A dombok övezte községnek három "külső" része északi oldalról Kér, déli oldalról Mecsek, melynek saját kis kápolnája is van, keleti oldalról pedig Rózsás.'),
    ('Bedő', 'A Kis-Körös bal partján, a Bihari-sík északkeleti peremén fekszik, a román határhoz közel. A szomszédos települések: északkelet felől Nagykereki, dél felől Biharkeresztes és Ártánd, északnyugat felől pedig Bojt. Csak közúton érhető el, a Debrecentől Biharkeresztesig húzódó 4808-as úton. A közelben húzódik a szarmaták 1260 kilométer hosszú sáncának, a Csörsz árkának egyik szakasza.'),
    ('Bejcgyertyános', 'A Kemenesháton fekszik Sárvártól 17 kilométer-re délre, a Csörnöc-Herpenyő patak partján, a Rábától mintegy 3 kilométer-re. Ezen érhető el a legközelebbi város, Sárvár felől és déli szomszédja, Kám felől is. A hegyközségre a 18. századtól számos forrás utal. A mai település két falu: Bejc és Hegyhátgyertyános egyesüléséből keletkezett.'),
    ('Bekecs', 'A Zempléni-hegység és az Alföld találkozásánál fekszik, a megyeszékhely Miskolctól 32 kilométerre keletre, a Tokaji borvidéken. A falu legdélibb része sík vidéken terül el, északi része viszont a Zempléni-hegység egyik legnyugatibb fekvésű hegye, a Nagy-hegy lábaira épült. A közvetlenül határos települések: észak felől Monok (5 kilométerre), kelet felől Szerencs városa, mellyel mára teljesen összeépült.'),
    ('Belecska', 'A Kapos folyó völgyében, a folyó jobb oldalán fekszik. Szerkezetileg dombvidéki útifalu. A vele közvetlenül határos települések: észak felől Pincehely, kelet felől Miszla, dél felől Keszőhidegkút, délnyugat felől pedig Regöly. A legközelebbi városok Gyönk (délkelet felé 12 kilométerre), Simontornya (északkelet felé 17 kilométerre) és Tamási (nyugat felé 19 kilométerre).'),
    ('Beled', 'Közigazgatásilag hozzátartozik Vica község is. Bár a Dél-Rábaköz központi településének számít, 2647 hektáros kiterjedésével a megye legkisebb közigazgatási területű városa, illetve egy 2018-as adat szerint abban az évben a lakónépesség és a lakások száma tekintetében is a legkisebb volt.'),
    ('Beleg', 'Beleg határában, a pusztaréti-dűlőben egy ősi földvár nyomai még a 20. század elején is láthatóak voltak. Ezt a várat „török várnak” nevezték, bár a vidék már az őskorban is lakott volt, majd később a római korban itt vezetett el a római hadiút. 1855-ben egy bronztáblát is találtak a környéken, amelyre Vespasianus császárnak egy hadirendelete volt vésve.'),
    ('Belezna', 'Határa nyugatról a Principális-csatorna és a Mura, amely 1 kilométerrel lejjebb ömlik a Drávába. Határában, a lakott településtől 6 kilométer-re folyik a Visszafolyó-patak a Principális-csatornába, annak torkolatában. A község alapvetően észak-déli elrendeződésű. A szomszédos települések: északnyugatra Murakeresztúr (közúton 7 kilométer-re), keletre Surd (közúton 6 kilométer-re).'),
    ('Beloiannisz', 'Beloiannisz vasúton és közúton egyaránt könnyen elérhető. Közúton az Iváncsa–Pusztaszabolcs közti 6205-ös útból kiágazó, egy kilométer hosszú, 62 108-as számú bekötőúton érhető el. Az 1950-es évekig a szomszédos Iváncsa szántóföldjei voltak a helyén. 1950. május 6-án indult meg a település tervezése és építése a görög polgárháborúból Magyarországra menekülők számára helyezkedik el.'),
    ('Belsősárd', 'Közigazgatásilag a rédicsi körjegyzőséghez tartozik. A Zalai-dombságban, a Kerka-vidéken, a Hetés tájegységben fekszik. A közvetlenül határos települések: észak felől Resznek, északkelet felől Lentikápolna (Lenti része), kelet és délkelet felől Lenti, dél felől Rédics és Külsősárd, nyugat felől pedig Zalaszombatfa. A legközelebbi város a 6 kilométerre lévő Lenti.'),
    ('Belvárdgyula', 'Pécs és Mohács között, légvonalban mindkettőtől körülbelül 20 kilométerre fekszik. A szomszédos települések: észak felől Olasz, északkelet felől Szederkény, délkelet felől Borjád, dél felől Nagybudmér, délnyugat felől Kiskassa, északnyugat felől pedig Birján helyezkedik el. A Belvárd és Kisgyula települések egyesüléséből keletkezett falu területe már az ókorban lakott hely volt. 1056-ban a pécsi püspökség volt a birtokosa. 1285-ben említették először fennmaradt okiratban Jula néven.'),
    ('Benk', 'A szomszédos települések: észak felől Tiszamogyorós, északkelet felől Lónya, délkelet felől Mátyus, dél felől Mezőladány, nyugat felől pedig Mándok. A térség fontosabb települései és távolságuk Benktől: Záhony 22,5 kilométer, Vásárosnamény 22 kilométer, Aranyosapáti 10,5 kilométer, Mándok 5,5 kilométer, Mezőladány 5,5 kilométer, Eperjeske 10 kilométer, Tuzsér pedig 12,5 kilométer.'),
    ('Bercel', 'Önkormányzatához tartozik Ordaspuszta, Jákotpuszta, Cservölgypuszta és Csobánkapuszta is. A településhez legközelebb lévő városok: Balassagyarmat 27 kilométerre, Vác 32 kilométerre, Budapest 60 kilométerre, Salgótarján pedig 80 kilométerre helyezkedik el. Fennmaradt írott forrásban először 1271-ben találkozunk Bercel nevével egy, a váci káptalan által kiállított okiratban.'),
    ('Beregdaróc', 'A szomszédos települések a határ magyar oldalán: északnyugat felől Barabás, nyugat felől Gelénes, délnyugat felől Csaroda, dél felől Márokpapi, délkelet felől pedig Beregsurány. Határszéle északkeleten közel 10 kilométer hosszúságban egybeesik az államhatárral. Ukrán oldalon a legközelebbi település Beregdéda (Dijda). A szakirodalom az Árpád-kori darócokat királyi vadfogóknak tartja.'),
    ('Beregsurány', 'A szomszédos települések a határ magyar oldalán: észak felől Beregdaróc, dél felől Tarpa, nyugat felől pedig Márokpapi. Határszéle keleten bő 6 kilométer hosszúságban egybeesik az országhatárral. A legközelebbi település ukrán oldalon Asztély (Asztej). Az egykori Nagysurány és Kissurány egyesüléséből alakult települést 1911-ig Suránynak nevezték. István királytól kapta mint magvaszakadt birtokos faluját. 1280-tól Mihály fia, Aladár és Gábor fia, Tamás között erőszakos…'),
    ('Berekböszörmény', 'A Bihari-sík délkeleti peremén, a magyar-román határ mellett fekszik, a legnagyobb szomszédos településtől, Biharkeresztes városától 10 kilométerre délre. További szomszédai: délnyugat felől Körösszegapáti, nyugat felől az utóbbihoz tartozó Körmösdpuszta, északnyugat felől pedig Told. Keleti és déli irányból Romániához tartozó területek határolják, a legközelebbi szomszédos települések román oldalon dél-délkeleti irányban a Sebes-Körös (Crișul Repede) menti Körösszeg (Cheresig) és Vizesgyán (Toboliu).'),
    ('Berekfürdő', 'Az Alföld nagytájegységben, a Hortobágy és a Nagykunság középtáj határán, a Tiszafüred-Kunhegyesi-sík kistájban, a Hortobágy délnyugati szélén fekszik Karcag és Kunmadaras között. Vonattal a Karcag–Tiszafüred-vasútvonalon közelíthető meg. Berekfürdő létét nem övezik évszázados múltra visszatekintő történetek, az 1920-as években ezen a területen mindössze 5 tanya állt 35 lakossal. 1928–30-ban Pávai-Vajna Ferenc két kutat fúrt a tanyavilágban, egy 1186 és egy 801,7 méter mélyet.'),
    ('Beremend', 'A Nyárád-Harkányi-síkon, Villánytól délre, közvetlenül a horvát határ mentén (é. sz. 45° 44′ 13″, k. h. 18° 26′ 48″45.736944444444, 18.446666666667) fekszik, közel Magyarország legdélibb pontjához. Közúton Villány vagy Siklós felől érhető el: az előbbi város irányából Magyarbóly érintésével, az 5706-os úton, az utóbbi felől pedig Nagyharsányon keresztül, az 5708-ason.'),
    ('Berente', 'A Sajó völgyében fekszik Miskolctól 15 kilométer-re észak-északnyugatra, Kazincbarcika keleti szomszédságában. A közvetlenül határos települések: észak felől Múcsony, kelet felől Dusnokpuszta (Sajószentpéter része), délkelet felől Sajószentpéter, dél felől Alacska, nyugat felől pedig Kazincbarcika, a legközelebbi város. A 26-os összeköti mindkét városi rangú szomszédjával, Sajószentpéterrel és Kazincbarcikával is, a többi szomszédjával viszont nincs közvetlen közúti összeköttetése.'),
    ('Beret', 'A Cserehát keleti részén, a Vasonca patak völgyében fekszik, a megyeszékhely Miskolctól 35 kilométerre északkeletre. A közvetlenül határos települések: észak felől Baktakék, kelet felől Fancsal, délkelet felől Forró, dél felől Detek, nyugat felől pedig Selyeb. A legközelebbi város a mintegy 15 kilométerre fekvő Encs. Csak a 2624-es közúton érhető el, Baktakék vagy Detek érintésével.'),
    ('Berettyóújfalu', 'Az Alföld keleti részének közepén helyezkedik el, a Berettyó folyó partján, Debrecentől 40, Nagyváradtól mintegy 35 kilométerre. Szomszédai: észak felől Derecske és Tépe, kelet felől Szentpéterszeg és Váncsod, délkelet felől Mezőpeterd és Told, dél felől Mezősas, délnyugat felől Furta és Zsáka, nyugat felől Bakonszeg, Bihartorda és Sáp, északnyugat felől pedig Földes.'),
    ('Berhida', 'A város a Mezőföld és a Balaton-felvidék határán helyezkedik el, festői természeti környezetben, közel a Balatonhoz és Veszprém városához. Berhida fontos szerepet játszik a helyi gazdaságban és közösségi életben, melyet a mezőgazdaság, az ipar és a kulturális hagyományok határoznak meg. Hozzá tartozik a mára beolvadt Kiskovácsi (1929 óta) és Peremarton (1939 óta).'),
    ('Berkenye', 'A közvetlenül határos települések: kelet felől Nőtincs, délkelet felől Szendehely, dél felől Verőce, délnyugat felől Szokolya, északnyugat felől pedig Nógrád. A legrégibb, 1299-ből fennmaradt oklevélben, mely nevét említi, még puszta földterületként szerepel. 1460-ban a váci püspökség birtoka volt. A Nógrádi Főesperesség plébániái között 1629-ben szerepel először.'),
    ('Berkesd', 'Nevét a fennmaradt okiratok közül a pécsváradi bencés apátság 1015-ben kelt alapítólevele említi először Villa Berkus alakban. A török hódoltság alatt sem néptelenedett el, akkori írásokban a körzet magyarlakta plébániaközpontjaként szerepel. A 18. században Mária Terézia az Egyetemi Alaphoz csatolta, s még e század végén német jobbágyok telepedtek le a faluban helyezkedik el.'),
    ('Berkesz', 'A Nyírségben fekszik, Kisvárdától 20 kilométerre délre, a megyeszékhely Nyíregyházától 30 kilométerre északkeletre. Településszerkezete szerint síkvidéki útifalu. A közvetlen szomszédos települések: északkelet felől Nyírtass, dél felől Ramocsaháza, nyugat felől Demecser, északnyugat felől pedig Gégény. Észak felől a legközelebbi település Pátroha, délkelet felől Laskod, délnyugat felől pedig Székely, de közigazgatási területe – kis híján – egyikkel sem határos.'),
    ('Bernecebaráti', 'Bernece és Baráti ősi települések voltak a Börzsöny nyugati partfala mentén. 1928-ban egyesültek Bernecebaráti néven 1936 lakossal. A települést 2 patak osztja hármas tagozódásra, a nevében is megtalálható Bernece-patak ugyanis itt egyesül a szomszédos Kemence település nevét is adó nagyobb Kemence-patakkal, amely Szlovákiában torkollik az Ipolyba.'),
    ('Berzence', 'Horvátország felé határátkelőhellyel is rendelkezik. Közúton Nagyatád, Csurgó és Barcs felől közelíthető meg, vasúton pedig a Murakeresztúr–Szentlőrinc-vasútvonalon helyezkedik el. Berzence nevének első írásos említése az 1332-1337. évi pápai tizedjegyzékben maradt fenn. Ekkor már egyháza is volt tehát. 1377-ben Berzencét tartozékaival együtt a Pécz nemzetségbeli Lóránt szerezte meg, akinek utódai magukat ettől az időponttól kezdve Berzenczei Lorántfiaknak nevezték.'),
    ('Berzék', 'A Hernád bal partján fekszik, Miskolctól mintegy 20 kilométerre délkeletre. A két legközelebbi település Bőcs 3 kilométerre északra és Sajóhídvég 3 kilométerre délre helyezkedik el. A legközelebbi városok Miskolc északnyugatra és Tiszaújváros délkeletre, mindkettő kb. 20 kilométerre helyezkedik el. Csak közúton, a 3607-esen, Sajóhídvég vagy Bőcs érintésével érhető el.'),
    ('Besence', 'Közúton a Szentlőrinc városát Sellye térségével (Csányoszró és Nagycsány községekkel) összekötő 5805-ös úton s az erről kiágazó, mintegy egy kilométer hosszú 58 114-es számú mellékúton érhető el. Keleti szomszédjával, Pápráddal egy alsóbbrendű önkormányzati út köti össze. Besence és környéke már az ókorban is lakott hely volt. Területén a római korból származó telep nyomait tárták fel.'),
    ('Besenyszög', 'A Szolnoki-ártér kistájon, Szolnok északi szomszédságában helyezkedik el, attól 16,5 kilométerre, Jászladánytól 18, Tiszasülytől pedig 20 kilométer távolságra. A közvetlenül határos települések: észak felől Tiszasüly, északkelet felől Hunyadfalva és Kőtelek, kelet felől Csataszög, délkelet felől Törökszentmiklós és Tiszapüspöki, dél felől Szajol, délnyugat felől Szolnok, nyugat felől Zagyvarékas és Szászberek, északnyugat felől pedig Jászladány.'),
    ('Besenyőd', 'A környező települések: Levelek 3, Apagy 7,5, Baktalórántháza 6,5, Nyíribrony 7,5, Ramocsaháza 10,5, Székely 14,5 kilométerre helyezkedik el. Ófehértóval egy számozatlan önkormányzati út köti össze. A település belső területei közösségi közlekedéssel a Volánbusz 4215-ös járatával közelíthetők meg. Besenyőd neve már szerepel egy, a Kállay család levéltárában lévő 1448-as oklevélben is. 1444-ben a Kércsy család, 1457-ben pedig a Sennyei család volt a település földesura. 1618-ban Besenyődi Mihály birtokolta, akinek 20 jobbágycsaládja volt.'),
    ('Besenyőtelek', 'Az Alföld északi peremén, a Hevesi-síkon fekszik, Füzesabonytól 5 kilométerre délre, a Tiszától mintegy 17 kilométerre északnyugatra. A kistáj 86 és 202 méter közötti tengerszint fölötti magasságú, lényegében a Laskó-patak és az Eger-patak hordalékkúp-síksága. A falu határa a Mátra és a Bükk-vidék Alföldre nyúló pereméhez és a Tisza árterületének tájegységéhez tartozik.'),
    ('Besnyő', 'A közvetlenül határos települések: észak felől Baracska, északkelet felől Ercsi, kelet felől Beloiannisz, délkelet felől Iváncsa, délnyugat felől Pusztaszabolcs, nyugat felől Velence, északnyugat felől pedig Kápolnásnyék. A környező települések közül Iváncsával és Pusztaszabolccsal, illetve a 6-os főúttal a 6205-ös út köti össze, de központja csak az abból kiágazó 62 109-es számú mellékúton érhető el.'),
    ('Beszterec', 'A közvetlen szomszédos települések: északkelet felől Újdombrád, délkelet felől Kék, délnyugat felől Vasmegyer, északnyugat felől pedig Tiszatelek. Központjától kelet-északkeleti irányban a határszéle egy helyütt pontszerűen érintkezik még Demecser közigazgatási területével is. A környező fontosabb települések közül Kék, Tiszatelek és Vasmegyer egyaránt mintegy 5, Kemecse 10, Nyírbogdány pedig 11 kilométerre van Beszterectől.'),
    ('Bezedek', 'A szomszédos települések: északra Majs, délre Sárok, nyugatra pedig Lippó. Kelet felől a községhatár egybeesik az államhatárral, abban az irányban a falu a horvátországi Főherceglak (Kneževo) községgel határos. A falu már az Árpád-korban is létezett, a nevét Bezedegh formában említő legrégibb oklevél 1296-ból maradt fenn, amikor baranyai várjobbágyok, Iváni Jovanka fiai, János, Jakab és Demeter birtoka volt, akik elhatárolták Fülöpföldétől.'),
    ('Bezenye', 'A folyószabályozás előtt a Szigetközhöz tartozott. A település a római kor óta lakott. Közelében népvándorlás-kori germán sírokat tártak fel. A honfoglalás után a gyepű védelmére besenyőket telepítettek le. A 16. században a magyarok mellé sok, Dalmáciából a törökök által elűzött horvát is költözött a településre. Bezenye első okleveles említése1262-ből maradt fenn Bezene alakban helyezkedik el.'),
    ('Bezeréd', 'Bezeréd központjából aszfaltozott út vezet a település külterületére, a Szabad Nép-telepre, ahonnan földúton lehet továbbmenni Zalakoppány felé. A település első említése a 13. század elejéről maradt fenn. Akkor Zalavár és a pornói apátság volt a birtokosa. Későbbről fennmaradt oklevelekben egyre gyakrabban szerepel a területet 1359-től birtokló Bezerédj (Bezerédi, Bezerédy) család neve.'),
    ('Bezi', 'Magyarország északnyugati részén, a Tóköz Hanság felé eső peremvidékén fekszik, Enesétől 5 kilométerre északnyugatra, Győrtől pedig mintegy 20 kilométerre nyugatra. Bezi kétóránként közlekedő autóbuszjárattal Győr és Csorna felől is elérhető. Bezi első megszállóiról, a besenyőkről kapta nevét, amely…'),
    ('Biatorbágy', 'A Zsámbéki-medence legnépesebb települése. Északnyugati irányban a Budai-hegység, délkeletről a Tétényi-fennsíkhoz kapcsolódó Érd-Sóskúti-fennsík övezi, délnyugat felől pedig az Etyeki-dombság határolja. A város keleti, ipari negyede a Budaörsi-medencébe nyúlik át. Legmagasabb pontja a 334 méter magas Iharos-hegy.'),
    ('Bicske', 'A Zsámbéki-medence második legnépesebb települése a Szent László-patak jobb partján helyezkedik el. Elővárosi járatok kötik össze Budapesttel, Tatabányával, Komárommal és Győrrel. Gyorsvonatok indulnak innen Budapest, Győr, Hegyeshalom, Sopron, Szombathely és Pozsony irányába. Nagyegyházi településrészének külterületeit egy kisebb szakaszon érinti a 8113-as út is.'),
    ('Bicsérd', 'A község központját csak az 58 102-es és 58 103-as számú mellékutak érintik, ezeken érhető el a 6-os főútról letérve. A római korban már lakott település volt a Mursa/Eszék/-Sopianae/Pécs/-Savaria/Szombathely/ út mentén. Első írásos említése 1262-ből ismert. Nevének jelentése, eredete a Földrajzi nevek etimológiai szótára szerint bölcső, vagy bölcs.'),
    ('Bihardancsháza', 'Szomszédai északkelet felől Sáp, kelet felől Bihartorda. Minden más irányból közigazgatásilag Nagyrábéhoz tartozó területek határolják. Bihardancsháza közelében a Halomszer-dombon már a honfoglalás idején letelepedtek, de a nevét említő legrégibb írás csak jóval későbbről, 1384-ből maradt fenn, Donchhaza formában helyezkedik el. E nevet valószínűleg korabeli földesuráról, Rábéi Danosról kapta.'),
    ('Biharkeresztes', 'Földrajzi elhelyezkedése miatt jelentős szerepet tölt be a magyar–román kapcsolatokban, különösen a határ menti forgalomban és kereskedelemben. Csupán 20 kilométer-re fekszik nyugatra Nagyváradtól, Debrecentől pedig 45 kilométer-re keletre. Biharkeresztes nevének eredete a középkori birtokviszonyokra vezethető vissza. A település első ismert neve Fancsal volt, amelyet 1214-ben említettek először oklevélben.'),
    ('Biharnagybajom', 'A hajdani sárréti vízi világ jellegzetes falva. Településszerkezetén a mai napig látható nyomot hagytak a vízfolyások, a mocsár. A mocsárvilág meghatározó volt az itt élő emberek életében, de a természet sohasem adta könnyen egyébként bőven termő kincseit a sárréti pákászoknak, nádalóknak, szigetszántó ősöknek. Szomszédos települések: észak felől Báránd, kelet felől Nagyrábé, dél felől Füzesgyarmat, nyugat felől pedig Sárrétudvari.'),
    ('Bihartorda', 'Szomszédai: észak felől Sáp, kelet felől Bakonszeg, dél és délnyugat felől Nagyrábé, nyugat felől pedig Bihardancsháza. Északkeleti irányból a község határa berettyóújfalui külterületekkel is érintkezik. A településen, nagyjából nyugat-keleti irányban végighalad a Biharnagybajom-Berettyóújfalu közti 4213-as út, közúton ezen érhető el a legegyszerűbben a 4-es és a 47-es főutak felől is.'),
    ('Biharugra', 'Jelentős természeti értékét képezi a település és az országhatár között elterülő Biharugrai-halastavak tórendszere. Szomszédai: észak felől Körösszakál, északkelet felől Körösnagyharsány, dél felől Geszt, délnyugat felől Zsadány, nyugat felől Komádi, északnyugat felől pedig Magyarhomorog. Kelet és délkelet felől Romániához tartozó területek határolják.'),
    ('Bikal', 'Bikal nevét fennmaradt oklevél 1325-ben említi először Villa Bykol alakban írva. A település ekkor a Szente-Mágócs nemzetségből származó Chama testvére János birtoka volt. A török uralom alatt sem néptelenedett el. Az 1554-1556-os adóösszeíráskor 15, az 1586-os összeíráskor pedig 16 házat írtak össze a faluban helyezkedik el. A török felszabadító háborúk idején a lakosság a környéken zajló hadmozdulatok miatt menekülésre kényszerült. 1696-ban már csak 5 családot írtak össze Bikalon helyezkedik el.'),
    ('Bikács', 'Különálló településrésze a központjától másfél-két kilométerre keletre fekvő Kistápé . A közvetlenül határos települések: észak felől Vajta, északkelet felől Németkér, kelet felől Paks, délkelet felől Györköny, dél felől Nagydorog, délnyugat felől Sárszentlőrinc, északnyugat felől pedig Pálfa. Észak-északkeleti irányban egy rövid szakaszon Cecével is határos, de e település távolabb fekszik tőle észak felé.'),
    ('Biri', 'Nagykállótól 7 kilométerre délre, Balkánytól 5 kilométerre északra, Nagykálló Ludastó nevű különálló városrészétől 5 kilométerre keletre, Perkedpusztától pedig 4 kilométerre nyugatra fekszik. Különálló településrésze 58 lakossal Táncsicstelep Nagykállótól 4, Biri központjától pedig 3 kilométerre helyezkedik el. Ludastóval egy számozatlan, alsóbbrendű önkormányzati út köti össze.'),
    ('Birján', 'Pécstől mintegy 17 kilométerre délkeletre fekszik. A legközelebbi szomszédai: észak felől Hásságy, kelet felől Olasz, délről Pécsdevecser és Peterd, nyugatról pedig Lothárd. Közigazgatási területén ered a Birjáni-árok, amely Pécsdevecser északi részén torkollik a Szemelyi-patakba. Belterületei vonatkozásában azonban zsáktelepülésnek tekinthető, mert központja közúton csak a főútból délnek kiágazó 57 101-es számú mellékúton érhető el.'),
    ('Bisse', 'A Villányi-hegység északnyugati részén fekszik, Harkánytól közúton 10 kilométerre északkeletre. A szomszédos települések: északkelet felől Áta, kelet felől Kistótfalu, dél felől a ma már Siklóshoz tartozó Máriagyűd, délnyugat felől Harkány, nyugat felől Túrony, északnyugat felől pedig Szalánta. Zsáktelepülés, közúton a Pécset a déli országhatárral összekötő 58-as főútról Túronytól északra letérve érhető el, az 57 111-es mellékúton.'),
    ('Boba', 'Északi szomszédjával, Nemeskocs községgel közigazgatási egységet alkot. Az öntésiszappal fedett pannon kori rétegek nem rejtenek számottevő ásványkincset, a megyehatár túloldalán fekvő szomszédos községekben is csak kavicsot bányásznak. A Marcal folyó medencéjében elterülő kis falu éghajlatát nagymértékben meghatározza a víz és a hegyek közelsége: mérsékelten hűvös, mérsékelten nedves, a napsütéses órák száma évi 1950–2000 között mozog, az évi átlagos hőmérséklet pedig 10 °C.'),
    ('Bocfölde', 'A Zalai-dombságban, azon belül a Göcsejben, a Felső-Válicka patak völgyében és a tőle nyugatra fekvő dombokon fekszik – újabb része a térséget átszelő régi országút mellett, a régebbi házak a domboldalakon. A közvetlenül határos települések: észak felől Zalaegerszeg, a megyeszékhely, kelet felől Csatár, dél felől Sárhida, délnyugat felől Bak és Gellénháza, nyugat felől Nagylengyel, északnyugat felől pedig Bazita (Zalaegerszeg része).'),
    ('Boconád', 'A szomszédos települések: észak felől Tarnabod, északkelet felől Erdőtelek, kelet felől Alatka (Heves különálló településrésze), délkelet felől Heves, dél felől Jászszentandrás, északnyugat felől pedig Tarnaméra és Tarnazsadány. Vasúton nem érhető el.'),
    ('Bocska', 'A Zalai-dombságban, az Egerszeg–Letenyei-dombság területén fekszik, Nagykanizsától 14 kilométerre északra. A közvetlenül határos települések: észak felől Zalaszentbalázs, kelet felől Magyarszerdahely, dél felől Eszteregnye, délnyugat felől Oltárc, nyugat felől Bucsuta, északnyugat felől pedig Börzönce. A községben elsősorban a Zalaegerszeg és Nagykanizsa közötti helyközi autóbuszok állnak meg, de távolsági járatok is érintik, amelyekkel Sopronba és Szombathelyre is el lehet jutni.'),
    ('Bocskaikert', 'Településszerkezete sakktáblaszerű. Bocskaikertet mint hegyközséget 1899. február 21-én alapították. Ekkor szőlőt és gyümölcsöt termesztettek területén. Első tulajdonosai Poroszlay László debreceni bankigazgató, kormányfőtanácsos és néhány ismerőse voltak. Később sorra gyarapodott a tulajdonosok száma. Elsősorban Debrecen tehetősebb polgárai vették igénybe pihenés, nyaralás céljából helyezkedik el.'),
    ('Boda', 'A megyeszékhely Pécstől mintegy 18 kilométerre nyugatra fekszik, a Mecsek délnyugati lábánál. Északon erdővel csatlakozik a Nyugat-Mecsek vonulatához helyezkedik el. A szomszédos települések: kelet felől Bakonya, délkelet felől Bicsérd, délnyugat felől Szentlőrinc, északnyugat felől pedig Bükkösd. Szent-Lőrincz - Határa 2576 hold, melyből úrbéri szántó 960, rét 585, szőlőhegy 245, erdőbeli közös legelő 576, tiszta legelő 50, majorsági föld 90, hasznavehetetlen 70 hold.'),
    ('Bodajk', 'A Dunántúli-középhegység második fő vonulata, a Bakony aljában, a hegység keleti vége közelében, a Móri-árok peremén fekszik. Mór 8 kilométer, Balinka 2 kilométer, Fehérvárcsurgó 1,5 kilométer, Székesfehérvár 22 kilométer-re található. Utóbbi a központtól északra található, a 8209-es…'),
    ('Bodmér', 'A környező települések távolsága: Vértesboglár 2,5, Szár 5, Felcsút 5, Alcsútdoboz 7 kilométer. A település nevét fennmaradt oklevél 1131-ben említi először Budmer alakban helyezkedik el. László király (1272-1290) adományozhatta (?) a Bodmériaknak, akik közül István és György használatra tartozékaival, illetve pusztáival együtt (Lad, Vadpálülése, Maladnok, Szőcs, Petrestelke, Disznókút, Szemtelke, Pokoldrakottya, Németi, Csákány) átadta rokonának, Vasvári Péternek.'),
    ('Bodolyabér', 'Légvonalban Pécstől mintegy 15 kilométerre északnyugatra, Komlótól 12 kilométerre nyugatra, Sásdtól pedig 6 kilométerre délre fekszik. Vasúton a Godisa–Komló-vasútvonalon érhető el: Bodolyabér megállóhely mintegy 500 méterre keletre van a falu lakott részétől. Bodolyabér két település. Kisbodolya és Egyházasbér egyesülésével jött létre 1950-ben. Kisbodolya és Egyházasbér nevét egyaránt 1332-ben említették először fennmaradt oklevelek.'),
    ('Bodonhely', 'Híd köti össze a Rába túlsó partján lévő Kisbabottal. Lakóinak életét évszázadokon át meghatározta a folyó és az átkelőhely. Talajtakarója változatos, döntően réti öntés- és lápos réti talaj. 1446-ból maradt fenn a legrégibb oklevél, amely „Bodonhel” néven Kanizsai birtokként említi a községet. 1536-ban a Nádasdyak, 1558-ban gróf Cseszneky János, 1861-ben pedig az Esterházyak kezére került.'),
    ('Bodony', 'A Mátra északi lábánál, dombok között, Recsktől 9 kilométerre nyugatra, Parádtól pedig 3 kilométerre északra fekszik. Bodony Árpád-kori település. Egykor az Aba nemzetség birtoka volt. Neve legkorábbról az egri káptalan 1275. évi határjáró levelében maradt fenn. Az 1332–1337. évi pápai tizedjegyzékben a patai esperesi kerület plébániái között szerepelt.'),
    ('Bodorfa', 'A Devecsertől 10 kilométerre délnyugatra fekvő zsákfalu 222 hektáros kiterjedésével a megye legkisebb közigazgatási területű települése. Bodorfa eredetileg a környék árteres tájának dombhátain megtelepült, s a királyi várhoz tartozó Keszi törzs települése volt. Neve a fennmaradt írások közül legrégebben az 1336-os pápai tizedjegyzékben szerepelt Bodorfalva alakban helyezkedik el.'),
    ('Bodrog', 'Kaposvártól 20 kilométerre észak-északnyugatra fekszik. Szomszédos települések: keletre Somogyjád, délkelet-délre Csombárd, észak-északkeletre pedig Osztopán helyezkedik el. A név a lankás, bodros szóból alakulhatott ki. Csak a 19. század óta írják g-végződéssel. 1449-ben a Bő nemzetség birtokai közé tartozott.'),
    ('Bodroghalom', 'A Bodrogköz szívében, Sátoraljaújhelytől 15 kilométerre délkeletre,Sárospataktól 18 kilométerre keletre, Miskolctól pedig mintegy 93 kilométerre keletre fekszik. A szomszédos települések: észak felől Alsóberecki (7 kilométer), északkelet felől Karos (8 kilométer), dél felől Tiszakarád (10 kilométer), nyugat felől pedig Vajdácska (8 kilométer). A legközelebbi város Sátoraljaújhely (15 kilométer).'),
    ('Bodrogkeresztúr', 'A környező települések: Bodrogkisfalud, amellyel szinte teljesen összenőtt, 1,2 kilométeren át csak egy utca választja el a két települést, Tarcal 2 és Szegi 3 kilométerre, a legközelebbi városok: Tokaj 6, Rakamaz 10, Szerencs 14, Sárospatak pedig 25 kilométerre. Vasúton a Budapest–Sátoraljaújhely-vasútvonalon érhető el. A terület az őskor óta lakott, amiről…'),
    ('Bodrogkisfalud', 'A környező települések: Bodrogkeresztúr, déli szomszédja, amellyel szinte teljesen összenőtt, 1,2 kilométeren át csak egy utca választja el a két települést, Szegi 1, Szegilong 3 kilométerre, a legközelebbi városok: Tokaj 9, Rakamaz 13, Szerencs 12, Sárospatak pedig 25 kilométerre. Első írásos említése 1220-ból maradt fenn Kysfalud alakban. 1317-ben már egyházi tulajdon volt. 1459-ben Tokajhoz tartozott.…'),
    ('Bodrogolaszi', 'Sárospatakon kívül három települési szomszédja van: délnyugat felől Sárazsadány, északnyugat felől pedig Tolcsva és Komlóska. A települést legrégebben említő írás 1244-ből maradt fenn, amikor IV. Béla olasz vincelléreket telepített a faluba, de temploma már egy 1201-ből fennmaradt írásban is szerepelt. 1404-ben a Perényi család birtokai közé tartozott, de 1444-ben rajtuk kívül a Pálócziaknak is volt itt birtokuk. 1504-ben Perényi Imre a maga birtokrészét a terebesi pálosoknak adományozta.'),
    ('Bogdása', 'Szigetvártól 23 kilométerre délre fekszik Sellye nyugati szomszédságában. A megyeszékhely, Pécs felől Szigetváron vagy Sellyén át érhető el. A falu nevének legkorábbi ma ismert említése egy 1266-os okiratban maradt fenn, mely arról tanúskodik, hogy a Haraszt nemzetség-beli Miklós bán fiai megosztoztak egymással az országbíró előtt. Az írás szerint az öt fiú közül Sebestyén és Péter kapta Baranyában Bogdását és hozzá Kustánt.'),
    ('Bogyiszló', 'A Dél-Mezőföld és a Tolnai-Sárköz határán fekszik, a megyeszékhely Szekszárdtól 11 kilométerre kelet-északkeletre. A település valaha a Duna egy holtága mellett, annak bal partján és a több kilométerrel nyugatabbra húzódó Tolnai-Duna-ágnak is a bal partján jött létre, de a folyam természetes mederváltozásai és az 1855-ben befejeződött szabályozási munkálatok eredményeként ma mégis a Duna főágának jobb partján terül el, a Sió-csatorna keselyűsi betorkollásának északi oldalán.'),
    ('Bogyoszló', 'Határának talaja a mélyebben lévő kavicstakaró felett homokos, agyagos, öntésiszapos. A felszínen lévő finom üledék jelenkori képződmény. A térség városai közül Csornától 9, Kapuvártól 13 kilométer választja el. A szomszéd települések: észak felől Jobaháza, északkelet felől Csorna, délkelet felől Szilsárkány, dél felől Sopronnémeti és Potyond, délnyugat felől Magyarkeresztúr és Kisfalud, nyugat felől Babót, északnyugat felől pedig Szárföld és Rábatamási.'),
    ('Bogács', 'A közvetlenül határos települések: észak felől Cserépfalu, északkelet felől Cserépváralja, délkelet felől Tard, dél felől Mezőkövesd, délnyugat felől Szomolya, északnyugat felől pedig Noszvaj. Az ország távolabbi részei felől a legegyszerűbben az M3-as autópályáról, illetve a 3-as főútról mezőkövesdi letéréssel közelíthető meg. Tömegközlekedéssel Budapest és Miskolc irányából Mezőkövesdig vonattal, onnan autóbusszal, s Egerből is autóbusszal érhető el a település.'),
    ('Bogád', 'A történelem során Bogod, Bogáth, Bogad, illetve Püsköbogád és Püspökbogád nevet viselte a település. A "püspök" jelzőt a második világháborút követően hagyta el. Horvát hivatalos nevét, a Bogadint a nagykozáriak használták régen, a magyarsarlósiak Borovónak nevezték. Pécstől mintegy 7 kilométerre keletre, a Mecsek hegység lábánál fekszik. Két települési szomszédja: kelet felől Romonya, dél felől pedig Nagykozár.'),
    ('Bogádmindszent', 'Harkánytól északnyugatra fekszik. A szomszédos települések: észak felől Téseny, északkelet felől Tengeri, kelet felől Hegyszentmárton, dél felől Páprád, nyugat felől Gilvánfa, északnyugat felől pedig Ózdfalu. Bogádmindszent Czinderybogád és Mindszent egyesüléséből alakult 1935-ben helyezkedik el. A legkorábbi írás Bogádról 1276-ból, Mindszentről pedig 1332-ből maradt fenn, ezekben Bugad, illetve Mendschent alakban szerepelnek.'),
    ('Bojt', 'A Bihari-sík északi részén, a Kis-Körös bal partján fekszik, Biharkeresztestől 8 kilométerre északra. A közvetlen szomszédos települések: észak felől Hencida, északkelet felől Kismarja, kelet felől Nagykereki, délkelet felől Bedő, dél felől Biharkeresztes, nyugat felől Váncsod, északkelet felől pedig Gáborján helyezkedik el. A településhez tartozott…'),
    ('Bokod', 'A település a Vértesalja kistájon, a Vértes lábától nyugatra fekszik, Oroszlánytól közúton 8,5 kilométerre nyugatra. Autóbusszal az 1254-es, 1256-os, 1257-es, 1628-as, 1702-es, 1784-es, 1842-es, 1843-as, 1844-es, 1845-ös, 1846-os, 1854-es, 8444-es, 8560-as, 8562-es, 8570-es és 8457-es járatokkal érhető el. Egykor Bokod helyén is római telep volt, a honfoglalás idején pedig szlávok lakták a vidéket.'),
    ('Bokor', 'A Cserhát magaslatai közt fekszik, Pásztótól légvonalban mintegy 10 kilométerre nyugatra. A völgyben fekvő falut dombok és erdők övezik jó gyalogösvényekkel és kerékpárutakkal. Zsáktelepülés, közúton a Mohora-Alsótold közt húzódó 2123-as útból kiágazó 21 147-es számú mellékúton, Kutasón keresztül érhető el. Nevét egyes kutatók a középkorban használatos „Bukur” személynévből eredeztetik, de a bokor köznévből is származhat a táj bokros-cserjés jellege miatt.'),
    ('Boldog', 'Hatvanon kívül még két települési szomszédja van: délkelet felől Jászfényszaru, délnyugat felől pedig Tura. A település és határa régészeti leletekben gazdag. Boldogtól délre halad el a szarmaták által 324 és 337 között épített, a Dunát a Tiszával összekötő Csörsz árok nyomvonala. Első írásos említése 1395-ből maradt fenn. 1867 után Boldogon szőlőt telepítettek, s ekkor vált jelentőssé a faluban a fűszerpaprika termesztése is.'),
    ('Boldogasszonyfa', 'Különálló településrészei Antalszállás északi és Terecseny északkeleti határszéle közelében helyezkedik el. A közvetlenül határos települések: észak felől Bőszénfa (már Somogy megyében), kelet felől Almamellék, dél felől Szentlászló, nyugat felől pedig Somogyhárságy. Már az őskorban is lakott hely volt, a településen és környékén kőkorszaki emberek lakóhelyének nyomait találták.'),
    ('Boldogkőváralja', 'A Zempléni-hegység nyugati részén fekszik, a Hernád völgyének peremén, a megyeszékhely Miskolctól 52 kilométerre északkeletre. A szomszédos települések: észak felől Arka közúton 3, Vizsoly pedig 8 kilométerre, kelet felől Baskó légvonalban mintegy 8 kilométerre, dél felől Boldogkőújfalu 2 kilométerre, délnyugat felől Abaújkér 7 kilométerre, északnyugat felől pedig Hernádcéce 5 kilométerre helyezkedik el.'),
    ('Boldogkőújfalu', 'Miskolctól 58 kilométerre északkeletre fekszik. A szomszédos települések: Boldogkőváralja 2 kilométerre északra és Abaújalpár 4 kilométerre délre helyezkedik el. A legközelebbi város Abaújszántó 8 kilométerre délnyugatra helyezkedik el. Első írásos említése az 1200-as évek elejéről maradt fenn. Ekkor lakatlan terület volt. 1241-ben IV. Béla magyar király a Regéc és Tállya közötti területen próbálta megállítani a tatárokat.'),
    ('Boldva', 'Miskolctól, a megyeszékhelytől 15 kilométerre északra fekszik, a Bódva folyó völgyének déli részén, nem messze a folyónak a Sajóba való betorkollásától. A közvetlenül határos települések: észak felől Ziliz, északkelet felől Nyomár és Hangács, kelet felől Alsóvadász, délkelet felől Sajóvámos és Sajósenye, dél felől Sajóecseg, nyugat felől pedig Sajószentpéter.'),
    ('Bolhás', 'A település közúton zsákfalu. Autóbusszal Nagyatádról 13 perc, Marcaliból pedig másfél óra alatt érhető el. Bolhás már egy, a 14. századból fennmaradt írásban is szerepelt, nevét akkor Villa Bolhas alakban írták, és a segesdi királynéi birtokhoz tartozott, amire a címer alsó részén található liliomos aranykorona is utal. A 15. században Mátyás király birtokába került.'),
    ('Bolhó', 'A szomszéd települések: északon Rinyaújnép és Háromfa, keleten Babócsa, északnyugaton pedig Heresznye. Bolhó egykor a Tibold nemzetség ősi birtoka volt. 1231-ben a nemzetség tagjai felosztották egymás között: I. Bodor három idősebb fiáé, Jakabé, Kozmáé és Petkéé lett. Neve szerepel az 1332-1337. évi pápai tizedjegyzékben is: ekkor már plébániája is volt. 1434-ben a Marczali család birtokolta, majd 1495-ben, Marczali László halála után a Báthori család kapta adományként II.'),
    ('Boncodfölde', 'A szomszédos települések: észak felől Bagod, kelet felől Andráshida (Zalaegerszeg része), délkelet felől Teskánd, dél felől Hottó és Böde, délnyugat felől Kávás, nyugat felől pedig Zalaszentgyörgy. A megyeszékhelyről sűrűn közlekedő elővárosi autóbuszokkal könnyen elérhető a település. A megyeszékhelyről elsősorban…'),
    ('Bonnya', 'A kétutcás zsáktelepülés Külső-Somogy keleti részén fekszik. Határát átszeli a Koppány patak. Első írásos említése 1229-ből maradt fenn, Villa Budana néven, a székesfehérvári káptalan birtokaként. 1480-ban vásáros helység lett. 1563-ban az akkori adólajstrom szerint a fehérvári prépost birtoka volt. 1733-tól a Hunyady-család birtokába került. (A család csak az 1900-as évek elején adta el birtokait a helyi gazdáknak.) 1780-tól svábok is költöznek a településre.'),
    ('Bonyhád', 'Gyakran nevezik a Völgység fővárosának. Az ókorban sok népcsoport megfordult itt, de a letelepedés csak az államalapítás után kezdődött meg. Átmeneti időszakot az elnéptelenedéssel fenyegető török uralom jelentett. A város fejlődése a 18. században kezdődött meg, ekkoriban a magyarok és rácok (szerbek) mellé folyamatosan települtek be a németek. 1782-ben Bonyhád mezőváros lett, ezt a címet azonban a későbbi közigazgatási reformok során elveszítette.'),
    ('Bonyhádvarasd', 'Szomszédos települések Bonyhádon kívül: Aparhant, Mucsfa, Nagyvejke, Kisdorog és a Bonyhád városához tartozó Tabód. Közúton a 6-os és 65-ös főutakat összekötő, Bonyhádtól Tevel és Murga határáig húzódó 6535-ös úton érhető el. Ez utóbbi esetben a 65-ös főúton kell menni Zombáig, onnan a 6533-as, majd a 6536-os úton Kisdorogig, és onnan délnek kanyarodva a 6535-ösön.'),
    ('Bordány', 'Szegedtől 21 kilométerre északnyugatra fekszik. A Szegedet Kiskunhalassal összekötő 5408-as út, amely javasolt kerékpárút is, áthalad a településen helyezkedik el. A szomszédos települések: észak felől Forráskút, északkelet felől Zsombó, délkelet felől Domaszék és a Szeged részét képező Kiskundorozsma, dél felől Zákányszék, nyugat felől pedig Üllés.'),
    ('Borgáta', 'A település neve Kiss Lajos Földrajzi nevek etimológiai szótára szerint, melynek első kiadása 1978-ban jelent meg az Akadémiai Kiadónál, feltehetően szláv nyelvből átvett puszta személynévből keletkezhetett (szerb-horvát Blagota, cseh Blahota, lengyel Blogota). Borgáta a Kemenesalján, a Kodó-patak mentén fekszik, Sárvártól 15 kilométerre délkeletre.'),
    ('Borjád', 'Szomszédos települések: északkelet felől Bóly, délkelet felől Töttös, dél felől Pócsa és Villány, délnyugat felől Kisbudmér, nyugat felől Nagybudmér, északnyugat felől pedig Belvárdgyula. A település népességének változása: A 2011-es népszámlálás során a lakosok 95,3%-a magyarnak, 23,9% németnek, 1% horvátnak mondta magát (4,7% nem nyilatkozott. A kettős identitások miatt a végösszeg nagyobb lehet 100%-nál).'),
    ('Borota', 'A szomszédos települések: észak felől Kéleshalom, kelet felől Jánoshalma, dél felől Felsőszentiván, nyugat felől Rém, északnyugat felől pedig Érsekhalma és Hajós. Borota területe 60%-ának talaja homokos, de 40%-áé jó termőképességű középkötött talaj. 8180 hektár közigazgatási területéből 8034 hektár külterület, melynek mintegy 30%-a erdő, 35%-a jó minőségű szántó, a többi pedig rét, legelő, szőlő, gyümölcsös és kivett terület.'),
    ('Borsfa', 'Autóbusszal könnyen elérhető, Letenye, Nagykanizsa és Zalaegerszeg felől érkező járatok is megállnak a településen helyezkedik el. A település első említése 1392-ből maradt fenn. Ezt követően folyamatosan lakott, apró, templom nélküli település volt. A környék központjának szerepét abban az időben Bánokszentgyörgy töltötte be. Borsfa első iskolája 1889-ben nyitotta meg kapuit.'),
    ('Borsodbóta', 'A szomszédos települések: Sáta 3 kilométerre délre, Uppony 4 kilométerre keletre és Sajómercse 7 kilométerre északra helyezkedik el. Területe már az ókorban is lakott volt, amit a környéken talált bronzkori kardok is tanúsítanak. Írásos emlékek 1494-ben említették először, Bolcha néven. (A község neve1954-ig Bóta volt, ekkor vette fel a Borsodbóta nevet.) A 14. században a Bélháromkúti Apátság birtoka volt, később több birtokos követte egymást, köztük az egri püspökség.'),
    ('Borsodgeszt', 'Mezőkövesd és Miskolc között fekszik, a Bükk-vidék déli részén, a megyeszékhely Miskolctól mintegy 20 kilométerre délre. A szomszédos települések: Sály, Harsány és Vatta mintegy 6-6 kilométerre és Bükkábrány 10 kilométerre helyezkedik el. A legközelebbi város Emőd 12 kilométerre helyezkedik el. Zsáktelepülés, közúton csak a Miskolc-Vatta közt húzódó 2515-ös útból, annak vattai szakaszán kiágazó 25 116-os mellékúton érhető el.'),
    ('Borsodivánka', 'A szomszéd települések: észak felől Szentistván, amellyel nincs közvetlen közúti összeköttetése, kelet felől Négyes 4 kilométerre, dél felől Poroszló 7 kilométerre, északnyugat felől pedig Egerlövő 4 kilométerre helyezkedik el. A terület már a honfoglalás idején is lakott volt, a község határában földvár nyomaira is bukkantak. A község első írásos említése a Váradi regestrumban maradt fenn, Louan néven helyezkedik el.'),
    ('Borsodnádasd', 'Létrejöttéről nem áll rendelkezésre oklevél, vagy más irat. Az első okleveles említése 1327-ből való Nádasd néven helyezkedik el. Nevét a völgy kiszélesedésében található nádasról kapta. A középkorban többek között a Nádasdy család birtoka volt. A török többször felégeti, hódoltsági terület, lakossága jelentősen csökkent. Az 1700-as évektől kezdett újra benépesülni.'),
    ('Borsodszentgyörgy', 'Területe: 124 hektár belterület, 2028 hektár külterület. A szomszédos települések: Ózd 9 kilométerre északkeletre, Arló 6 kilométerre délkeletre, Domaháza és Kissikátor nyugatra és Hangony északra (utóbbi hárommal nincs közvetlen közúti összeköttetése). Ekkor még Disznós volt a neve, később pedig Alsódisznós és Felsődisznós. Eger ostromakor a török sereg feldúlta, s az egri vár eleste után török megszállás alá került.'),
    ('Borsodszirák', 'Edelénytől 5 kilométerre délre, a megyeszékhely Miskolctól 15 kilométerre északra fekszik. A kisebb szomszédos települések: Ziliz 2 kilométerre és Boldva 5 kilométerre, mindkettő délkeletre helyezkedik el. A település neve a 9. századi Vat székely-fehér hun (kony) uralkodó keresztény nevéből, a Sirák személynévből származik. Első írásos említése 1261-ből maradt fenn, Zyrakh alakban helyezkedik el.'),
    ('Borsosberény', 'A Börzsöny északkeleti lábánál, Balassagyarmattól mintegy 17 kilométerre délnyugatra, a parassapusztai határátkelőtől pedig 15 kilométerre délkeletre fekszik. A szomszédos települések: észak felől Nagyoroszi és Horpács, kelet felől Pusztaberki, délkelet felől Tereske, Bánk és Rétság, dél felől Tolmács, délnyugat felől pedig Diósjenő. Főutcája öt számjegyű útként a 12 126-os útszámozást viseli.'),
    ('Borszörcsök', 'A Somló hegy délkeleti oldalán, Devecsertől 5 kilométerre északnyugatra fekszik. Zsáktelepülés, közúton csak a 8-as főútról Devecser északnyugati határszéle közelében kiágazó 84 103-as mellékúton érhető el. Borszörcsök Árpád-kori település. Zurchuk néven már 1288-ban említették oklevelek. 1299-ben és 1317-ben királynői birtok volt, akkori írásokban Bors fibius Blasii de Zurchuk néven szerepel.'),
    ('Borzavár', 'A Bakony szívében, a Zircről Porvára vezető út mellett, Zirctől 4 kilométer-re, a Pálihálási-patak erdőtől övezett medencéjének lejtőjén fekszik. Nevét az egykor itt termesztett sok bodzáról, helyi nevén borzáról kapta. A tiszta levegő, a közeli Kőris-hegy és az Országos Kéktúrának a településen áthaladó útvonala sok kirándulót vonz. A falunak 1785-ben már 687 lakosa volt.A telepesek római katolikus vallásúak, nagyobbrészt magyarok, kisebbrészt szlovákok voltak.'),
    ('Bosta', 'Pécs déli agglomerációjában terül el, a város központjától mintegy 17 kilométerre délre, Harkánytól pedig körülbelül 15 kilométerre északra. A megye aprófalvai közül is a legkisebbek közé tartozik. Négy települési szomszédja van: kelet felől Szalánta, dél felől Garé, délnyugat felől Szőke, északnyugat felől pedig Szilvás. Szomszédai közül Szőkével és Szilvással is az 5828-as út kapcsolja össze, Garéval viszont csak változó minőségű erdei utak, köztük az az út, amely a déli határszéle közelében létesült veszélyeshulladék-lerakóhoz vezet.'),
    ('Botpalád', 'Szomszédai: észak felől Tiszabecs, észak-északkelet felől Uszka, északkelet felől Magosliget, kelet felől Kispalád, délkelet felől Kishódos, nyugat és északnyugat felől pedig Sonkád. A környező nagyobb települések Tiszabecs 12, Kölcse 10 és Sonkád 6 kilométerre helyezkedik el. Botpalád már az őskorban is lakott hely volt. Régen nagy erdőség vette…'),
    ('Botykapeterd', 'Botykapeterd 1931-ben alakult a korábban két önálló település, Botyka és Kispeterd egyesítéséből. Botyka Árpád-kori település, személynévi eredetű, nevét fennmaradt oklevelek 1258-ban említették először Boghka, Bathka vagy Bogyka alakban írva. A falut nemesek lakták, köztük a 13. században a Bece család, amelyikről a ma Becefa néven Szigetvár részét képező Beceszeg település a nevét kapta.'),
    ('Bozsok', 'Kőszegtől 9 kilométerre nyugatra, Szombathelytől 22 kilométerre északnyugatra fekszik a Kőszegi-hegység déli lábánál, az Arany-patak mentén, közvetlenül az osztrák határ mellett. Területének északnyugati részét erdővel borított hegyek alkotják. Határában emelkedik a Kőszegi-hegység legmagasabb csúcsa, az Írott-kő is. A hegyek lábánál szőlők és gyümölcsösök vannak, a határ délkeleti része pedig mezőgazdasági terület.'),
    ('Bozzai', 'Szombathelytől 10 kilométerre keletre, a Gyöngyös-sík délkeleti peremén, a Kozár-Borzó patak mellett fekszik. A határos települések: kelet felől Kenéz, dél felől Vasszécseny, délnyugat felől Tanakajd, északnyugat felől pedig Vép. Neve a régi magyar Boza személynévből ered, melynek előzménye a bodza főnév. Első írásos említése 1271-ből maradt fenn, Bozey alakban helyezkedik el.'),
    ('Bucsa', 'Szomszédai: északkelet felől Püspökladány, kelet felől Szerep, dél felől Kertészsziget, délnyugat felől Ecsegfalva, nyugat felől Kisújszállás, északnyugat felől pedig Karcag. A települést nagyjából északnyugat-délkeleti irányban átszeli a Karcagtól Füzesgyarmatig húzódó 4206-os út. Közúton ezen érhető el a két végponti település irányából. Bucsa és környéke már az újkőkorszak idején lakott hely volt, de megtalálták nyomát a rézkor, a bronzkor és a vaskor népeinek is.'),
    ('Bucsu', 'Szombathelytől mintegy 10 kilométerre nyugatra, az Arany-patak két oldalán, közvetlenül az osztrák határ mellett fekszik. A szomszédos települések a határ magyar oldalán: észak felől Bozsok, északkelet felől Perenye, kelet felől Gencsapáti, délkelet felől Torony, dél felől Dozmat, délnyugat felől pedig Narda. Közigazgatási területe kelet-délkeleti irányból egy rövid szakaszon Szombathely határszélével (Szünösemajor külterületi városrésszel) is érintkezik.'),
    ('Bucsuta', 'Fennmaradt írásos forrásokban 1289-ben szerepelt először, Bachita néven helyezkedik el. E név későbbi írásos változatai arról tanúskodnak, hogy a település folyamatosan lakott hely volt: 1320-ban Bazytha, 1360-ban Bachta, 1364-ben Bachytha, 1524-ben Bwchytha, 1542-ben Bochyta, 1576-ban Bacsita, 1696-ban Borcsita, 1720-ban Bocsuta, 1790-ben Butsota, 1796-ban pedig Bucsuta formában írták.'),
    ('Budajenő', 'A Zsámbéki-medence északkeleti peremén, a Budajenői-patak völgyében, az Óbudai-szigettel nagyjából azonos földrajzi szélességen helyezkedik el, Budapest központjától 22 kilométerre nyugat-északnyugatra, Budakeszitől pedig 10 kilométerre északnyugatra. A fővárostól a Budai-hegység koszorúja, a tőle északabbra fekvő Nagykovácsitól pedig e hegység legmagasabb része (a Nagy-Kopasszal) választja el.'),
    ('Budakalász', 'Budapesttel közvetlenül határos település a Duna jobb partján helyezkedik el. A folyam túloldalán elhelyezkedő Dunakeszivel megosztva a „Dunakanyar kapuja"-ként is emlegetik. Területét keleten a Szentendrei-Duna, északon Szentendre és Pomáz, nyugaton Csobánka, délnyugaton Pilisborosjenő és Üröm, délen pedig Budapest határolják. Közvetlenül házai mellett, a Vác–Pesti-Duna-völgyhöz tartozó Pomázi-síkon, a hajdani kavicsbányászat maradványaként nagy kiterjedésű bányatavak találhatók.'),
    ('Budakeszi', 'A Budai-hegység keleti peremén, nyugodt, dombos, kertvárosi területen fekszik, közvetlenül Budapest határán. Területe északon és keleten Budapest II. kerületével, délkeleten pedig a XII. kerülettel érintkezik, így földrajzilag és közlekedési szempontból szorosan kapcsolódik a fővároshoz. Német nevét annak köszönheti, hogy a közösség valójában sváb település volt.'),
    ('Budaörs', 'Német nevét annak köszönheti, hogy a közösség valójában sváb település volt. Ez látható például a település épületeiről és rendszeréről. A várost először 1236-ban említik IV. Béla király idején. 1921-ben, mikor IV. Károly magyar király másodszor is megpróbálta visszaszerezni a magyar trónt, csapatait Budaörsnél állították meg.'),
    ('Bugac', 'Az Alföldön, a Duna–Tisza közi homokhátságon, a Bugaci-homokháton, a Kiskunsági Nemzeti Park területén fekszik, a megyeszékhely Kecskeméttől mintegy 40 kilométerre délre. A belterületétől nyugatra elterülő külterületi részeinek nagy része a Kiskunsági Nemzeti Park Bócsa-Bugac buckavilága elnevezésű területrészéhez tartozik. Bugac a megye hatodik legnagyobb területű települése.'),
    ('Bugacpusztaháza', 'A megye legkisebb lakónépességű települése. A szomszédos települések: észak felől Jakabszállás, kelet felől Bugac, délnyugat felől Bócsa, északnyugat felől pedig Orgovány. Ugyanez az út köti össze Jászszentlászlóval. A közúti tömegközlekedést a Volánbusz autóbuszai biztosítják.'),
    ('Bugyi', 'A Pesti-síkságon fekszik, Budapesttől központjától mintegy 25 kilométerre délkeletre. Keleti része érinti a Csepeli-síkot, amely itt érintkezik a Pesti-hordalékkúpsíksággal, és a Kiskunsággal. A szomszédos települések: észak felől Alsónémedi, északkelet felől Ócsa (Felsőbabád), kelet felől Dabas, Sári városrésze, délkelet felől Dabas, dél felől Kunpeszér és Kunszentmiklós, délnyugat felől Apaj, nyugat felől Kiskunlacháza és Délegyháza, északnyugat felől pedig Dunavarsány és Taksony.'),
    ('Buj', 'A szomszédos települések, településrészek: észak felől Tiszabercel, északkelet felől Paszab, kelet-északkelet felől Ibrány, kelet felől Ibrány-Nagytanya, délkelet felől Kótaj, dél felől Nyírtelek, délnyugat felől Gávavencsellő-Paszabcsúcs, északnyugat felől pedig Gávavencsellő. Településrésze a belterületének északi szélén, központjától jó egy kilométerre lévő Herminatanya is.'),
    ('Buják', 'A Novohrad-Nógrád UNESCO Globális Geopark települése. A Cserhátban, Pásztótól légvonalban mintegy 13 kilométerre délnyugatra fekvőzsáktelepülés. Északi és nyugati szomszédjaira, Bokorra és Szandára csak aszfaltozott erdészeti úton lehet átjutni. Északkeleti szomszédjával, Ecseggel pedig még ilyen közúti kapcsolata sincs, azzal csak egy mezőgazdasági út köti össze.'),
    ('Buzsák', 'A Balaton melletti Nagy-Berek szélén, a Kaposvár–Fonyód-vasútvonaltól néhány kilométerre fekszik. Központján a Lengyeltóti-Nikla közti, a 6701-es és 6704-es utakat összekötő 6708-as út halad keresztül, ezen érhető el a Balaton (Fonyód) és Marcali irányából is. Buzsák helyén a középkorban Akts és Magyari falvak álltak. A terület eredetileg a Somogyi vár tartozéka volt.'),
    ('Bábolna', 'Bábolna Komárom-Esztergom vármegyében, a Komáromi járásban. Bábolna a Kisalföldön, a Igmánd–Kisbéri-medencében, Komárom-Esztergom vármegye nyugati szélén helyezkedik el Tatától 27, Nagyigmándtól 7, Kisbértől 18, Komáromtól 15, Győrtől 25 kilométerre. Magyarországon – Erdélyt kivéve – három Bábolna, illetve Babonya nevű hely létezett (Bihar, Borsod és Komárom vármegyében…'),
    ('Bábonymegyer', 'A Külső-Somogy keleti részén, a Kis-Koppány patak völgyében található, Tabtól 6 kilométerre. Megyert legkorábban 1193-ban, Bábonyt (Bábon) 1259-ben említik fennmaradt oklevelek. András király okiratában Baba néven kerül említésre helyezkedik el. Egy 1259-es birtoklevélben Babon alakban írták a nevét, ekkor Babonis Gergely ispán pereskedett a faluért.'),
    ('Bácsalmás', 'Határát átszeli a Kígyós-főcsatorna. A szomszédos települések: észak felől Tataháza és Mélykút, kelet felől Bácsszőlős, délkelet felől Kunbaja, délnyugat felől Madaras, nyugat felől Bácsbokod, északnyugat felől pedig Mátételke. Az ország egyik legmelegebb tájegysége, ahol igen magas a napsütéses órák száma (átlag 2098) és igen alacsony az évi csapadékmennyiség (átlag 565 mm).'),
    ('Bácsbokod', 'A Bácskai-síkvidéken, hullámos, enyhén dombos, észak felé fokozatosan emelkedő vidéken fekszik a Dunától 20 kilométer-re keletre. Tengerszint feletti magassága 110 és 125 méter között van. A szomszédos települések: észak felől Felsőszentiván, északkelet felől Mátételke, kelet felől Bácsalmás, dél felől Bácsborsód, délnyugat felől Vaskút, északnyugat felől pedig Baja.'),
    ('Bácsborsód', 'A szomszédos települések az országhatár magyar oldalán: észak felől Bácsbokod, északkelet felől Bácsalmás, délkelet felől Madaras és Katymár, délnyugat felől Gara, északnyugat felől pedig Vaskút. Közúton három irányból közelíthető meg: Bácsbokod vagy Gara érintésével az 5505-ös, Katymár felől pedig az 5508-as úton helyezkedik el. A község területén lelt szarmata és kelta tárgyak nagyon régi, több évezredes településre utalnak.'),
    ('Bácsszentgyörgy', 'Kistelepülés a Duna és a Kígyós-ér árterületén, közvetlenül a szerb határ mellett, Bajától 25 kilométerre. Délről a szerbiai Haraszti és Regőce, a magyar oldalon pedig északról Gara, északnyugatról Dávod, délnyugatról Hercegszántó veszi körül. A település határát átszeli a Kígyós-főcsatorna. Csak közúton érhető el, Gara érintésével (vagy az országhatár irányából, dél felől), az 5506-os úton.'),
    ('Bácsszőlős', 'A község a Bácskában, a szerb határ közelében, Bácsalmástól 8 kilométerre keletre fekszik. Belterülete 37 hektár. A szomszédos települések: észak felől Mélykút, északkelet felől Tompa, kelet felől Csikéria, dél felől Kunbaja, nyugat felől pedig Bácsalmás. A sínek ma is megvannak, de a pálya járhatatlan helyezkedik el. E határrészek a 19. század végétől váltak lakottá, amikor a felparcellázott területeken meghonosították az alföldi szőlőfajtákat, és állandó lakhelyű…'),
    ('Bágyogszovát', 'A település a Rábaközben fekszik 11 kilométerre Csornától délkeleti irányban. A mai község Bágyog és Rábaszovát egyesüléséből jött létre. Az északnyugatra fekvő bágyogi rész egyutcás, a délkelet felé eső szováti rész összetett település, de a temploma körül mindkét községrész úgynevezett orsós jellegű kiszélesedést mutat.'),
    ('Bálványos', 'A Külső-Somogyi dombság északi részén, a Balatontól körülbelül 10 kilométerre délre, a déli part legmagasabb és a megye harmadik legmagasabb pontjának számító 311 méteres Gyugy-háttól délre, két észak-déli irányú völgyben fekszik. A szomszédos községek: Kőröshegy, Zala, Lulla, Balatonendréd, Kereki és Pusztaszemes. Neve a "kőoszlop, határkő" jelentésű bálvány főnévből származik: "bálványos falu, vagyis olyan falu, amelynek nevezetessége valamely oszlop” – írja Várkonyi Imre Somogy megye helységneveinek rendszere című könyvében.'),
    ('Bánd', 'Központján a 8313-as út vezet végig helyezkedik el. Legközelebbi szomszédja a tőle 3 kilométerre lévő Márkó. Bánd és környéke az itt talált ókori leletek tanúsága szerint már a római korban is lakott hely volt. Nevét fennmaradt oklevelekben a 13. század elején említették először. 1233 előtt az Ajka nemzetség Bánd nevű tagjának birtoka volt. Bánd, illetve Seg helységet még 1233 előtt az Igmánd nemzetségből való I.'),
    ('Bánfa', 'Szigetvár délkeleti vonzáskörzetében fekszik. A szomszédos települések: észak felől Rózsafa, délkelet felől Sumony, dél felől Okorág, délnyugat felől Szentegát, nyugat felől pedig Katádfa. Kelet felől a legközelebbi település Szentdénes, de közigazgatási területeik nem határosak egymással.'),
    ('Bánhorváti', 'A Bán-patak völgyében fekszik a legközelebbi várostól, Kazincbarcikától 10 kilométerre dél-délnyugatra, a megyeszékhely Miskolctól 30 kilométerre északnyugatra, a Lázbérci Tájvédelmi Körzet közelében. A környező települések közül Nagybarca 3, Dédestapolcsány pedig 7 kilométerre található. A 26-os főutat a 25-össel összekötő 2506-os út mentén fekszik, közúton csak azon érhető el, Vadna-Nagybarca vagy Dédestapolcsány érintésével.'),
    ('Bánk', 'A táj jellegét a Nógrádi-medencét keleti irányból övező Cserhát dombvidéke határozza meg. A szomszédos települések Rétság, Felsőpetény és Romhány. Korábban vasúton is elérhető volt a Diósjenő–Romhány-vasútvonalon, de 2007. március 4. éjféltől ezen a vonalon megszüntették a személyforgalmat. A bánki megállóhely közúti elérését a 2115-ös útból kiágazó 21 325-ös út tette lehetővé.'),
    ('Bánokszentgyörgy', 'A község a Göcsejben, a Zalai-dombság egy kisebb völgyében fekszik. Északról Zalaegerszeg, délről Letenye felől közelíthető meg. Közigazgatási területén a Becsehely-Bak közt húzódó 7536-os út halad végig, amelyből itt ágaznak ki utak két zsátelepülésre, a 75 137-es kelet felé, Oltárcra, a 75 138-as pedig nyugat felé, Várföldére. A falut autóbuszjáratok kötik össze Zalaegerszeggel, Nagykanizsával, Lentivel és Letenyével is.'),
    ('Bánréve', 'A település a szlovák határ mentén, a Sajó völgyében, Ózdtól mintegy 15 kilométerre északkeletre, Miskolctól pedig körülbelül 40 kilométerre északnyugatra fekszik. Közigazgatási területét a Sajó csak kis szakaszon, a községhatár legdélebbi részén érinti. Utóbbi ettől a találkozási ponttól alig fél kilométerre éri el az országhatárt és lép át Szlovákiába.'),
    ('Bár', 'A Duna jobb partján fekszik, közvetlenül Mohács mellett, annak központjától északkeletre. Mohácson kívül csak két települési szomszédja van: északkelet felől Dunaszekcső, északnyugat felől pedig Somberek. A Bár területén fellelt vörös-betétű edénytöredék alapján a régészek arra következtettek, hogy a falu területe már az újabb kőkorban is lakott volt.'),
    ('Bárdudvarnok', 'Bárdudvarnok Kaposvártól alig tíz kilométerre délnyugatra a belső-somogyi dombok egyik legszebb részén, a Zselici Tájvédelmi Körzet határán terül el. A település és környéke Somogy egyik legnagyobb közigazgatási területe. Több négyzetkilométeren szétszóródó tizenhat településrész tartozik hozzá, ami egyedülálló az országban.'),
    ('Bárna', 'A Novohrad-Nógrád UNESCO Globális Geopark települése. Zsáktelepülés, csak közúton közelíthető meg, a Salgótarján-Mátraszele közti 2303-as útból kiágazó 23 106-os úton helyezkedik el. A helység néveredetének kutatói a "sötét" értelemben használt "barna" melléknév helynevesülését tartják a legvalószínűbbnek, de egyesek a Barna személynévből eredeztetik a falu nevét.'),
    ('Bársonyos', 'Főutcája a Bakonycsernye és Mezőörs külterülete között húzódó 8208-as út. Távolsága a 81-estől a 8208-ason 6 kilométer, a 8221-esen pedig 3 kilométer. Sűrűn érintik a Kisbér-Győr között közlekedő és más távolsági autóbuszjáratok is. Bársonyos környékén már az őskorban is laktak emberek. Ennek bizonyítékai azok a neolitikum idejéből származó kőszerszámok, amelyek Keréktelekin kerültek elő.'),
    ('Báta', 'Keletről a Duna és a Gemenci erdő határolja. Keleti része a Duna árterületéhez tartozik, a Gemenci erdő része, és a Duna–Dráva Nemzeti Park révén országos szintű természetvédelmi oltalom alatt áll. A község területén találkozik egymással az Alföldhöz tartozó síkság folytatását képező Tolnai Sárköz és a Dunántúli-dombsághoz csatlakozó Dél-Baranyai-dombság.'),
    ('Bátaapáti', 'A Geresdi-dombságban, több kisebb patak összefolyásánál fekszik. Hozzá tartozik a különálló, tréfás nevű Rozsdásserpenyő településrész is, mely központjától közel 2,5 kilométerre északra található. A szomszédos települések: észak felől Mőcsény, kelet felől Mórágy, délkelet felől Bátaszék, dél felől Véménd, nyugat felől Ófalu, északnyugat felől pedig az egykor önálló, ma Mőcsényhez tartozó Zsibrik.'),
    ('Bátaszék', 'A Sárköz déli részén, Szekszárdtól 18 kilométerre délre helyezkedik el, az 55-ös és 56-os főutak találkozásánál. A környező települések: észak felől Várdomb, Sárpilis és Decs, északkelet felől Alsónyék, kelet felől Pörböly, délkelet felől Báta, dél felől Dunaszekcső, délnyugat felől Palotabozsok és Véménd, nyugat felől Bátaapáti és Mórágy, északnyugat felől pedig Alsónána.'),
    ('Bátmonostor', 'Később a kalocsai érsek foglalta le magának a báthai bencések birtokát. 1321-ben a település birtokosa Johannes filius Petri de Monasterio Both volt. 1322-ben Károly Róbert király Becsei Imre lévai várnagynak adományozta előző tulajdonosa örökös nélküli halála miatt, s a birtok később Töttös és Vesszős nevű fiaié lett. 1323-ban a király a Becsei Imrétől elszakított birtokok visszaszerzésével (visszaadásával) a kalocsai káptalant bízta meg. 1337-ben a bátai apát a templomot filiális apátságra emelte és e ranghoz illő monostort is építtetett, amely a török időkig a Becseiek birtokában maradt.'),
    ('Bátonyterenye', 'A város térsége már a bronzkor második felében i. e. 1500 körül lakott volt, amelyet jelentős régészeti lelőhelyek bizonyítanak, első írásos emléke viszont csak 1216-ból származik. Bátonyterenye 1984. január 1-jén jött létre Nagybátony (az 1965-ben hozzácsatolt Maconkával), Kisterenye és Szúpatak egyesítésével, városi rangot 1989-ben kapott. A város (pontosabban Kisterenye) híres szülötte Abonyi Lajos író.'),
    ('Bátor', 'A településtől délre, az Egerbakta-Bátor útvonal jobb oldalán emelkedik a Bátori Nagyoldal, amelyet égerligetek és tölgyesek borítanak. A környéken védett növények s kis- és nagyvadak is élnek. Az erdővel borított hegyoldalak, az érintetlen természet nemcsak szép látványt, hanem egészséges levegőt is biztosítanak az itt lakóknak. A közvetlen szomszédos települések: észak felől Egerbocs, kelet felől Szarvaskő, délkelet felől az Egerhez tartozó Felnémet, dél felől Egerbakta, nyugat felől Bükkszék, északnyugat felől pedig Hevesaranyos.'),
    ('Bátorliget', 'Határszéle keleten és délen mintegy 7 kilométer hosszan egybeesik a magyar-román államhatárral. A közvetlenül szomszédos települések a határ magyar oldalán: észak felől Terem, északnyugat felől Nyírvasvári, nyugat felől Nyírpilis, délnyugat felől pedig Piricse és Ömböly a határ túlsó oldalán pedig: dél felől Ponyváspuszta (Viișoara) és kelet felől a Csanáloshoz (Urziceni) tartozó Csanáloserdő (Urziceni Pădure).'),
    ('Bátya', 'A szomszédos települések: észak felől Foktő és Kalocsa, délkelet felől Miske, dél felől Fajsz, nyugat felől pedig a Duna túlsó, jobb partján fekvő Fadd és Gerjen helyezkedik el. A terület már a 9. században is lakott volt, lakosságát avarok és szlávok alkották. Bátya első okleveles említése Bacha alakban I. Béla király 1061-ben kelt okleveléből ismert, amelyben a települést uradalmával együtt az általa alapított szekszárdi bencés apátságnak adományozta, s határait is leíratta.'),
    ('Bázakerettye', 'Az egységes Bázakerettye község csak 1937 óta létezik. Előtte két önálló faluból, Bázából és Kerettyéből állt. Báza – jelentése bodza (szláv) – első fennmaradt említése 1352-ből való, Kerettye – jelentése vakond (szintén szláv) – pedig 1353 óta szerepel fennmaradt iratokban. A 16. században a térség a Kerecseny család birtokához tartozott. A török időkben valószínűleg gyéren lakottá vált a település, és csak a 18. század elején vált ismét lakottá.'),
    ('Béb', 'A Bakony és a Kisalföld találkozásánál fekszik, Pápától 10 kilométerre keletre. A szomszéd települések: észak felől Csót, délkelet felől Ugod, dél felől Homokbödöge, nyugat felől pedig Nagygyimót. Déli szomszédjával, Ugoddal a 8303-as út, az északival, Csóttal pedig a 83 123-as út köti össze. A település első fennmaradt írásos említése a 13. század közepéről való…'),
    ('Békás', 'Pápa tágabb vonzáskörzetében, a várostól bő 10 kilométerre nyugatra fekszik. Békás Árpád-kori település. Nevét valószínűleg a település melletti kis Békás nevű érről kaphatta. Több Árpád-korból való lelet is napvilágra került, köztük pálcikás díszítésű fazéktöredékek is. A település birtokosai a középkortól kezdve a Békássy család tagjai voltak. A család e Békás nevű településtől kapta a nevét.'),
    ('Békés', 'Bár ma már nem a megye központja, egykor meghatározó szerepet játszott a térség életében. Történelme egészen az Árpád-korig nyúlik vissza, de a török hódoltság idején elnéptelenedett, majd a későbbi évszázadokban újra benépesült. A város leginkább mezőgazdasági hagyományairól ismert, de az ipar és a szolgáltatások is egyre fontosabb szerepet kapnak.'),
    ('Békéscsaba', 'A város híres gasztronómiai különlegességeiről és rendezvényeiről, például a hungarikumnak számító csabai kolbászról és az erre alapozott fesztiválról, emiatt gyakran emlegetik „A kolbász fővárosaként”. Ugyancsak itt rendezték meg Magyarország leglátogatottabb sörfesztiválját is, azonban ez később átkerült Gyulára helyezkedik el. A település története a középkorig nyúlik vissza, első írásos említése 1332-ből származik.'),
    ('Békésszentandrás', 'Területén van Magyarország 5. legnagyobb állóvize, a Hármas-Körös Kákafoki-holtága, s ezért is tartják sokan az Alföld legszebb fekvésű falujának. Határában – túlnyomórészt a holtág mentén – több mint 500 hétvégi ház található, ami komoly idegenforgalmi jelleget kölcsönöz a településnek. Szomszédai: északkelet felől Mezőtúr, kelet felől Szarvas, dél felől Szentes, illetve annak nagy kiterjedésű külterületi határrészei, nyugat felől Öcsöd, északnyugat felől pedig Mesterszállás.'),
    ('Békéssámson', 'A szomszédos települések: észak felől Kardoskút, kelet felől Tótkomlós, dél felől Makó, nyugat felől Hódmezővásárhely, északnyugat felől pedig Székkutas. Természetföldrajzilag az Alföld Körös–Maros köze középtájának Csongrádi-sík kistájához tartozik. 2017. július 3-án Békéssámsonon mérték minden idők magyarországi napi maximum hőmérsékleti rekordját, 40,1 Celsius-fokot.'),
    ('Bélapátfalva', 'A település az Eger-patak völgyében futó országút mentén található. Bélapátfalva az Eger-patak folyásának felső részén kialakult medence peremén helyezkedik el, az erdőhatár és a vízjárta patakvölgyek közötti sávban, 311 méter magasságban a tengerszint felett, a 816 méter magas Bél-kő nyugati lábánál. A város határában fut a Recska-patak.'),
    ('Bélavár', 'Bélavár nevét a fennmaradt okiratok közül az 1332-1337. évi pápai tizedjegyzék említi először egyházas helyként. A Dráva mellett egykor vár is állt ezen a helyen, melyet a Dráva három oldalról zárt körül. 1399-ben a székesfehérvári káptalan birtoka volt. Az 1469-ben és 1498-ban kelt oklevelek szerint már városi kiváltságokat élvezett. A 15. században is a székesfehérvári káptalané volt. 1531-ben az ország rendjei értekezletre gyűltek össze a településen…'),
    ('Bélmegyer', 'A szomszédos települések: északkelet felől Vésztő, dél-délkelet felől Tarhos, dél-délnyugat felől Békés, nyugat-délnyugat felől Mezőberény, nyugat felől Köröstarcsa, északnyugat felől pedig Körösladány. Békéssel egy számozatlan, alsóbbrendű önkormányzati út köti össze. A közúti tömegközlekedést a Volánbusz autóbuszai biztosítják.'),
    ('Bénye', 'A Tápió mente földrajzi kistáj területén, a Bényei-patak magas domboktól ölelt völgyében fekszik. Utcái ötújjas kesztyűt formálva benyúlnak a dombok között húzódó völgyekbe. Határszélét délkeleten a 3123-as út is érinti. Első okleveles említése 1368-ból maradt fenn, birtokosa akkor a Bényei család volt. A török uralom alatt kihalt. A törökök kiűzése után az elnéptelenedett falut felvidéki evangélikus szlovákokkal telepítette be a Fáy család.'),
    ('Bér', 'A Novohrad-Nógrád UNESCO Globális Geopark egyik települése. Szilárd burkolatú közúton csak Szirák felől érhető el a falu, a szomszédos Bercelre és Bujákra csak földutak vezetnek. Budapestről közvetlen autóbuszjárattal is el lehet jutni a településre. A környező települések: Bercel, Buják, Ordaspuszta, Szirák és Vanyarc. A település a Kökényes-Radnót nemzetség ősi birtoka volt, és Radnót halála (1322) után is a nemzetség tulajdonában maradt. 1439-ben a bujáki várbirtokhoz tartozott.'),
    ('Bérbaltavár', 'Távolsága Szombathelytől 40, Zalaegerszegtől 25, Vasvártól 15 kilométer. Mindhárom várossal közvetlen autóbuszjáratok kötik össze. A község Baltavár és Hegyhát-Kisbér egyesítésével jött létre 1935-ben. Baltavár a forgalmas középkori út, a ''Via-publica'' mentén, Hegyhát-Kisbér pedig egy patak partján alakult ki. Mindkét alkotó település Árpád-kori eredetű.'),
    ('Bócsa', 'Az levéltárakban fennmaradt első említések 1436-ból származnak. Ezek Boycha-szállásként említik a nevét, melyet egy Boycha nevű úrról kapott. Láttuk fentebb, hogy 1347-ben Budán a Cherthan nemzetségbeli kúnok kapitánya Kumcheg biró egy oklevelet állitott ki, melyben emliti fiát Chyrchy-t is. 1371-ből emlittetik Kuncheg nemzetségbeli Fekete László mint kún kapitány.'),
    ('Bódvalenke', 'A Bódva völgyében fekszik, Miskolctól 57 kilométerre északra. A szomszédos települések: Komjáti 3, Hidvégardó 5, Tornaszentandrás pedig 7 kilométerre helyezkedik el. A legközelebbi városok: az országhatár magyar oldalán Szendrő 24 kilométerre, szlovákiai oldalán pedig Torna 10 kilométerre helyezkedik el. Autóbusszal Bódvalenke a Volánbusz 4124-es és 4136-os járatával érhető el.'),
    ('Bódvarákó', 'A Bódva folyó völgyében, az Aggteleki-karszt és a Szalonnai-hegység között, az Esztramos-hegy lábánál, Miskolctól 52 kilométerre északra fekszik. A környező települések: Bódvaszilas 4, Tornaszentandrás, Perkupa, és Szögliget pedig közúton egyaránt 10-10 kilométerre helyezkedik el. A legközelebbi város: Szendrő 20 kilométerre helyezkedik el. Közösségi közlekedéssel a Volánbusz 4124-es járatával érhető el.'),
    ('Bódvaszilas', 'A Gömör–Tornai-karsztvidéken fekszik, az Alsó-hegy peremdombjai és a Bódva-völgy határvonalán, Miskolctól 52 kilométerrel északra. A községhatártól keletre az Alsó-hegy 500 méter átlagos magasságú karsztfennsíkja meredek lejtőkkel végződik a Bódva folyó 160 méter átlagos magasságú völgyében, nyugatra viszont rövid völgyek választanak le a fennsíkról két hátat: a Kerek-hegyet és a Kónyát.'),
    ('Bókaháza', 'A Zalai-dombság keleti szélén, a Zala völgyében fekszik. Bókaháza első írásos említése 1479-ből maradt fenn. Birtokosa akkor a Boka család volt. Később ez a család valószínűleg elszegényedett, mert neve későbbi írásokban már csak jobbágy- vagy zsellérnévként szerepel. A települést a 17. századi források nem említik. Feltételezhető, hogy a török hódoltság idején elnéptelenedett.'),
    ('Bóly', 'Bóly, régi nevén Németbóly Pécstől körülbelül 30 kilométerre kelet-délkeletre, Mohácstól mintegy 15 kilométerre nyugatra Nyárád–Harkányi-síkon helyezkedik el. A környék gazdasági központja. A szomszédos települések: észak felől Versend, északkelet felől Szajk, délkelet felől Nagynyárád, dél felől Töttös, délnyugat felől Borjád, északnyugat felől pedig Szederkény és Monyoród.'),
    ('Bózsva', 'A Zempléni-hegység északi részén fekszik, Sátoraljaújhelytől 20 kilométerre északnyugatra. Belterülete két, egymástól nem túl távol lévő, de markánsan elkülönülő településrészből, Nagy- és Kisbózsvából áll. A szomszédos települések: északkelet felől Filkeháza, kelet felől Pálháza, délkelet felől Kishuta, dél felől Nagyhuta, északnyugat felől pedig Nyíri.'),
    ('Böde', 'A Zalai-dombság területén, a Göcsejben fekszik Zalaegerszegtől mintegy 15 kilométerre nyugatra. Zsáktelepülés, közúton csak a 7405-ös útból Teskánd külterületének déli szélén kiágazó 74 113-as úton érhető el. A települést 1407-ben említik először fennmaradt írásos források, az ősi magyar Bed személynévre visszavezethető Bede néven helyezkedik el.'),
    ('Bödeháza', 'Területe a Hetés tájegység részét képezi. A falu 11 más településsel együtt működteti a Rédicsi Közös Önkormányzati Hivatalt. Területének vizeit a Határ-patak szállítja el. Lakossága kevesebb, mint 50 fő, lakónépesség tekintetében Magyarország huszonkilencedik legkisebb települése. Két falurészből áll: a névadó települést 1389-ben említi először írott forrás, Bedehaza névlakban.'),
    ('Bögöt', 'A Gyöngyös-sík keleti peremén fekszik, Sárvártól körülbelül 8 kilométerre nyugatra. Két legközelebbi szomszédja: nyugat felől Porpác mintegy 2,5 kilométerre, délkelet felől pedig Csénye 5 kilométerre helyezkedik el. Bögöt első okleveles említése 1325-ből maradt fenn, de a honfoglalókra jellemző török eredetű neve régebbi keletkezést feltételez. Az ásatások során előkerültek a Savariából Arrabonába vezető római hadiút maradványai is.'),
    ('Bögöte', 'Az 1300-as évekből fennmaradt oklevelek tanúsítják, hogy Bögöte már akkor lakott település volt. 1627-ben neve már megegyezett mai nevével, attól csak írásban tért el (Beögeöte). Német telepesek alapították, akik később teljesen elmagyarosodtak. A török hódoltság idején pusztává vált, és csak a 18. században népesült be újra. 1787-ben 433-an, 1917-ben 710-en, 1970-ben pedig 604-en éltek a faluban helyezkedik el.'),
    ('Böhönye', 'A közvetlenül határos települések: észak felől Szenyér, északkelet felől Mesztegnyő, kelet felől Nagybajom, délkelet felől Kutas, délnyugat felől Segesd, nyugat felől Vése, északnyugat felől pedig Tapsony és Nemeskisfalud. Szőlő- és borgazdasági szempontból a Balatonboglári borvidékhez tartozik. Három település körjegyzőségi székhelye.'),
    ('Bököny', 'A szomszéd települések: észak felől Érpatak, északkelet felől Geszteréd, dél felől Hajdúhadház, délnyugat felől Téglás, északnyugat felől pedig Újfehértó. A település nevének eredetéről a Földrajzi nevek etimológiai szótára ezt írja: „Bököny helység Szabolcs-Szatmár megyében Újfehértótól délkeletre. (Neve) puszta személynévből keletkezett magyar névadással." Szabolcs-Szatmár megye történeti-etimológiai helységnévtára szerint az ómagyar Bökény~Bököny személynévből keletkezett, melynek eredete tisztázatlan.'),
    ('Bölcske', 'Közigazgatási területét a Duna, Dunaföldvár, Németkér, Paks-Dunakömlőd és Madocsa fogja közre. Egyházi igazgatás szempontjából a Pécsi egyházmegyéhez, illetve a Dunamelléki Református Egyházkerülethez tartozik. Bár a Dunántúlon van, földrajzi szempontból talajszerkezete és tájának jellege miatt az Alföldhöz tartozó Mezőföldhöz lehet sorolni. Az itt élők körülményeit, létfeltételeit a mai napig nagy mértékben meghatározza a község keleti határában folyó Duna.'),
    ('Börcs', 'Az ország északnyugati részén, a Rábca folyó északi partján fekszik, Győrtől 13 kilométerre nyugatra. A Rábca menti áradásos területből egy nagyobb domb emelkedik ki, erre települt hajdan a község. A közvetlenül határos települések: észak felől Öttevény, kelet felől Abda, dél felől Ikrény, délnyugat felől Rábapatona, északnyugat felől pedig Mosonszentmiklós.'),
    ('Börzönce', 'A Zalai-dombságban, az Egerszeg–Letenyei-dombság területén, hatalmas erdőségek között fekszik, a megyeszékhely Zalaegerszegtől 35 kilométerre délre, Nagykanizsától pedig 21 kilométerre északra. Határa dombos, agyagos, árkokkal szabdalt. A Kürtös-patak (régebbi nevén Malomárok) átfolyik a falun. Ma már a Zalaszentbalázs-Szentliszló közti négy számjegyű 7534-es mellékúton is elérhető.'),
    ('Búcsúszentlászló', 'Főutcája a Pölöske-Alsónemesapáti között húzódó 7363-as út. A település 1270-ben szerepelt először fennmaradt írásos forrásokban, Scent Laduzlo néven helyezkedik el. Akkor a pölöskei vár tartozéka volt. Az 1333-as pápai tizedjegyzékben Szent László egyházként szereplő templomának plébánosa Pál volt. A hagyományok szerint maga Szent László király rendelte el egy…'),
    ('Bük', 'Hozzátartozik Bükfürdő. Kereskedelmi szálláshelyeken eltöltött vendégéjszakák tekintetében Magyarország negyedik legnépszerűbb települése. Szombathelytől 27 kilométerre északkeletre, az Alpokalja és a Kisalföld találkozásánál a Vas–Soproni-síkságon és a Répce-síkon helyezkedik el. Északi és déli irányból is a nyugati szomszédságában fekvő Csepreghez tartozó külterületek határolják.'),
    ('Bükkaranyos', 'A Miskolci-Bükkalja keleti részén, a Kulcsár-völgyi-patak mentén helyezkedik el, Miskolctól 13 kilométerre délre. A környező települések: Harsány 5, Kisgyőr 10 kilométerre, a legközelebbi város: Emőd 7 kilométerre helyezkedik el. A településnek Miskolc két városrészével – Diósgyőrrel és Görömböllyel –, valamint Nyékládházával, Emőddel, Harsánnyal és Kisgyőrrel van közös határa.'),
    ('Bükkmogyorósd', 'A Bükk-vidéken fekszik, Miskolctól közúton 60 kilométerre nyugatra, Ózdtól 15 kilométerre délre, Szilvásváradtól pedig 5 kilométerre északnyugatra, az Egert Ózddal összekötő főútvonal mentén. Területe dombos, völgyekkel tagolt. A két legközelebbi település Csernely és Lén helyezkedik el. Csak közúton érhető el, Szilvásvárad vagy Csernely érintésével, a 2508-as úton.'),
    ('Bükkszenterzsébet', 'Szomszédos települések: Pétervására, Váraszó, Tarnalelesz és Fedémes. Közúton a Kisterenye (Bátonyterenye) és Tarnalelesz között vezető 23-as főúton érhető el. (A megyeszékhely felől Tarnaleleszig a 25-ös főúton, onnan pedig a 23-as főúton közelíthető meg.) A közúti tömegközlekedést a Volánbusz autóbuszai biztosítják. A fennmaradt adatok szerint Bükkszenterzsébet II.'),
    ('Bükkszentkereszt', 'Hegyekkel körbezárt völgykatlanban épült, ahol a hóréteg vastagsága január–februárban rendszerint eléri a 30–40 centimétert. Hollóstető is Bükkszentkereszthez tartozik. Éghajlata 600 méteres tengerszint feletti magassága ellenére is kiegyensúlyozott, nincs érezhetően hidegebb, mint az alacsonyabban fekvő településeken. A falut körbezáró hegyek védik az erős szelektől, és a köd is ritkább, mint Miskolcon helyezkedik el.'),
    ('Bükkszentmárton', 'Egykorm a Bél nemzetség birtoka volt, sokáig Felbérnek hívták. Temploma védőszentjéről, Tours-i Szent Mártonról kapta a Szentmárton nevet. 1554-ben a törökök elpusztították. Újra benépesülése után 1596-tól hódoltsági falu lett.'),
    ('Bükkszék', 'A közvetlenül határos települések: észak felől Fedémes, északkelet felől Hevesaranyos, kelet felől Bátor, délkelet felől Sirok, dél felől Szajla, délnyugat felől Terpes, nyugat felől Kisfüzes, északnyugat felől pedig Tarnalelesz. A 2413-as út a falu központját elkerüli, az csak a 24 123-as mellékúton érhető el.'),
    ('Bükkzsérc', 'A Bükki Nemzeti Park déli határán fekszik, Miskolctól 30 kilométerre délnyugatra, Egertől 25 kilométerre északkeletre, a Bükk egyik déli irányú völgyében, a Cseresznyés-ér mentén. A legközelebbi települések: Bogács (7 kilométer) és Cserépfalu (2 kilométer). A legközelebbi város: Mezőkövesd (17 kilométer). Autóbusszal Egerből, Noszvajon át, illetve Mezőkövesd felől a Volánbusz üzemeltet járatot a faluba.'),
    ('Bükkábrány', 'A Bükk-vidék és az Alföld találkozásánál, a Borsodi-Mezőségen, a Kácsi-patak és a Sályi-patak között észak–déli irányban terül el, Miskolctól 33 kilométerre délre, Egertől pedig 28 kilométerre keletre. A környező települések: Mezőnyárád 2, Tibolddaróc 5, Vatta 6, Sály pedig 7 kilométerre helyezkedik el. A legközelebbi városok: Mezőkeresztes 8, Emőd 12 és Mezőkövesd 13 kilométerre helyezkedik el.'),
    ('Bükkösd', 'A szomszédos települések: észak és északkelet felől Hetvehely, délkelet felől Boda, dél felől Szentlőrinc és Cserdi, délnyugat felől Helesfa, északnyugat felől pedig Ibafa. Közigazgatási területe keleti irányból csúcspontosan határos még Bakonya, nyugati irányból pedig Dinnyeberki területével is. Megyefa településrészt csak önkormányzati utak érintik.'),
    ('Bürüs', 'Szigetvártól délre, Kétújfalutól keletre fekvő zsáktelepülés. Szomszédai: észak felől Várad és Hobol, kelet felől Szentegát, dél felől Endrőc, délnyugat felől Teklafalu, nyugat felől pedig Kétújfalu. Közúton csak Váradon keresztül érhető el, a Szigetvártól Drávafokig húzódó 5808-as útról Kétújfalutól körülbelül egy kilométerre északra keleti irányban letérve, az 58 147-es számú mellékúton.'),
    ('Büssü', 'Határos községek Kisgyalán, Gölle, Fonó és Zimány. Büssü és környéke már az őskorban is lakott hely lehetett, erről tanúskodnak a község határában, a Górdombon talált kőbalták és házieszközök. A mai Büssü területe az ókorban is lakott hely volt. Az itt talált római kori emlékek közül említést érdemel a páfrányosi mező római temetője, valamint az 1880-as években a paperdei mezőben talált római kori sír.'),
    ('Büttös', 'Miskolctól közúton körülbelül 70 kilométerre északra található, nem messze a szlovák határtól. A legközelebbi települések Krasznokvajda körülbelül 2 kilométerre, Kány 5 kilométerre, illetve Perecse, ugyancsak mintegy 5 kilométerre helyezkedik el. A legközelebbi város, Encs körülbelül 23 kilométerre található. Büttös területe – aránylag különleges módon – két különálló részből áll, a két rész egymáshoz legközelebb eső pontjait egy olyan, körülbelül 200 méteres sáv választja el, ahol Kány és Szemere határvonala húzódik.'),
    ('Bő', 'Büktől 3 kilométerre keletre, Sárvártól 21 kilométerre északnyugatra, Szombathelytől 31 kilométerre északkeletre fekszik, a Répce bal oldalán. A falu nyugati oldaláig terjeszkedik a Bük–Bő–Gór-víztározó. Szomszédai: észak felől Lócs, északkelet felől Simaság és Sajtoskál, kelet felől Chernelházadamonya, dél felől Gór, nyugat felől pedig Bük. A település Magyarország fő közúti közlekedési útvonalaitól viszonylag távol van, csak mellékutakon érhető el.'),
    ('Bőcs', 'Az Alföld és az Északi-középhegység határán, a Hernád folyó két oldalán fekszik, Miskolctól 14 kilométerre délkeletre. A környező települések: Berzék 2, Hernádnémeti 4, Sajólád pedig 5 kilométerre, a legközelebbi város: Alsózsolca 10 kilométerre helyezkedik el. Bőcs (Bölcs, Belcs) már a honfoglalás előtt lakott volt, térségében avar temetőt tártak fel.'),
    ('Bőny', 'A legközelebbi vasútállomások Nagyszentjánoson és Győrben vannak, előbbi 8, utóbbi 17 kilométerre a falutól helyezkedik el. Az éghajlata kontinentális jellegű. A falu mellett folyik a Bakony-ér, amely ma az év nagy részében csekély vízhozamú, de régen áradásai komoly károkat tudtak okozni.'),
    ('Bőszénfa', 'Belterületének nagy része egy észak-déli irányban elnyúló völgyben épült. Különálló településrésze Kisbőszénfa, a faluközponttól mintegy 1 kilométerre délnyugatra helyezkedik el. Kiterjedt közigazgatási területének köszönhetően számos települési szomszédja van. Legészakibb külterületei révén még Kaposvárral, a város Töröcske városrészével is közvetlenül határos.'),
    ('Bősárkány', 'Magyarország északnyugati részén fekszik, Csornától 9 kilométerre északra, Mosonmagyaróvártól pedig 28 kilométerre délre. A szomszédos települések: északkelet felől Rábcakapi, kelet felől Markotabödöge, délkelet felől Maglóca, dél felől Csorna, délnyugat felől Acsalag, északkelet felől pedig Jánossomorja (Hanságliget). A falu neve 1222-ben szerepelt először egy fennmaradt írásban, a szomszédos Maglócát eladományozó oklevélben, „villa Sarkan” alakban helyezkedik el.'),
    ('Cece', 'Közvetlenül határos települések Sárbogárdon kívül: északkelet felől Alap, kelet felől Alsószentiván, délkelet felől Németkér és Bikács, dél felől Vajta, délnyugat felől Pálfa, nyugat-északnyugat felől pedig Sáregres. Nyugat felől a legközelebbi település Simontornya, de közigazgatási területeik (nagyon kevés híján) nem érintkeznek. A község valószínűleg…'),
    ('Cegléd', 'A Duna-Tisza közében, a fővárostól 74 kilométerre fekszik délkeletre. A középkorban fontos kereskedelmi út egyik megállóhelye volt, mely összekötötte Budát Erdéllyel. Területe közel 245 km2, népessége pedig 35 ezer fő. A város a Ceglédi kistérség székhelye, amelybe beletartozik Abony, Dánszentmiklós, Nagykőrös, Albertirsa, Jászkarajenő, Nyársapát, Kocsér, Tápiószőlős, Ceglédbercel, Köröstetétlen, Törtel, Csemő, Mikebuda és Újszilvás.'),
    ('Ceglédbercel', 'A község Budapesttől mintegy 60 kilométerre délkeletre fekszik Albertirsa és Cegléd között. Déli határában folyik a Gerje-patak. A középkorban Ceglédbercel területe Alberti pusztája volt. A 18. században a klarissza apácák birtoka volt, majd 1785-ben, amikor ezt a rendet feloszlatták, a feloszlatott kolostorok…'),
    ('Celldömölk', 'A város történelme gazdag és több évszázadra nyúlik vissza, nevét a helyi bencés apátságról kapta, amelynek központi eleme a híres Mária-kegytemplom. A templom ma is fontos zarándokhely, amely évente sok látogatót vonz. Celldömölk földrajzi elhelyezkedése révén természetközelséget kínál helyezkedik el. A vulkanikus eredetű Ság-hegy nemcsak természeti látványosság, hanem geológiai különlegesség is, amely kedvelt célpontja a túrázóknak és a borászat iránt érdeklődőknek.'),
    ('Cered', 'A történelmi Medvesalja régió és a Novohrad-Nógrád UNESCO Globális Geopark része. Határátkelő Szlovákia felé. Közigazgatási határa több mint 15 kilométer hosszúságban egybeesik az államhatárral. A határ magyar oldalán csak négy települési szomszédja van: kelet felől Zabarral (7,5 kilométer), délkelet felől Szilaspogonnyal (6 kilométer), délnyugat felől Bárnával, nyugat felől pedig a Salgótarjánhoz tartozó Rónabányával (9 kilométer) határos.'),
    ('Chernelházadamonya', 'A Répce bal partján fekszik, Sárvártól 21 kilométerre északnyugatra, Szombathelytől 31 kilométerre északkeletre, Büktől 9 kilométerre délkeletre. Répceszentgyörggyel csak egy alsóbbrendű, számozatlan önkormányzati út köti össze. Két, Csernelháza és Damonya egyesítéséből jött létre 1925-ben. 1927-ig ideiglenesen Chernelháza…'),
    ('Cibakháza', 'A Tisza szabályozása óta az élő folyó távolabb került tőle, viszont határában található a magyarországi folyószakasz egyik leghosszabb Tisza-holtága, a Cibakházi Holt-Tisza. Miután a főutat másik, keletebbi nyomvonalra helyezték át, a településen áthaladó forgalom jelentősen csökkent. Első fennmaradt okleveles említése 1465-ből való, de egyes forrásokból arra lehet következtetni, hogy már az Árpád-korban lakott hely volt.'),
    ('Cigánd', 'Lendületes fejlődése az 1994-ben átadott II. Cigánd 2004 óta rendelkezik városi ranggal. Nevének eredete máig vitatott. A név hallatán sokan azt gondolják, hogy cigányok lakta település, és nevét is erre vezetik vissza. Így volt ez még a 19. század közepén is annak ellenére, hogy első okleveles említésekor a cigány törzseknek még hírük-hamvuk sem volt hazánkban, de még Európában sem.'),
    ('Cikó', 'A település Bonyhádtól délkeleti irányban hat kilométerre, a Széplaki-völgyben található. Zsáktelepülésnek tekinthető, mivel közúton csak egy útvonalon közelíthető meg, az 5603-as útból Bonyhád délkeleti részén kiágazó 56 102-es számú mellékúton helyezkedik el. Régészeti bizonyítékok alapján már az őskorban lakott hely volt. A település a török hódoltság korában teljesen elnéptelenedett, majd betelepített németek munkája nyomán indult újra fejlődésnek.'),
    ('Cirák', 'Mindössze három települési szomszédja van: észak felől Gyóró (amellyel a belterületeik mára szinte össze is nőttek), kelet felől Beled, dél felől pedig Dénesfa. Nyugati irányból ez utóbbihoz tartozó lakatlan külterületek határolják.'),
    ('Csabacsűd', 'Szomszédai észak és nyugat felől Szarvas, kelet felől Kardos, délről Nagyszénás, délnyugat felől pedig Eperjes. Az M44-es autóút is áthalad a területén, a gyorsforgalmi út legközelebbi lehajtója a községtől bő 2 kilométerre keletre található, Kardos területén.'),
    ('Csabaszabadi', 'Békéscsabától délnyugatra, 15 kilométer-re Békéscsaba és Csanádapáca között fekvő település. Szomszédai: észak felől Telekgerendás, északkelet felől Békéscsaba, kelet felől Újkígyós, délkelet felől Pusztaottlaka, dél felől Medgyesbodzás, délnyugat felől Csanádapáca, nyugat-északnyugat felől pedig Gerendás. Csabaszabadi a Békéscsaba környékén fekvő tanyavilágból alakult település.'),
    ('Csabdi', 'A Keleti-Gerecsében található, Bicskétől 4 kilométerre északnyugatra, a budapesti Margit-szigettel nagyjából megegyező földrajzi szélességen. A szomszédos települések: észak felől Gyermely, kelet felől Mány, dél felől Bicske, északnyugat felől pedig Tarján helyezkedik el. Viszonylag közel fekszik hozzá még délnyugati irányban Óbarok is. A település alsóbbrendű – részben burkolatlan – utakon Nagyegyháza és Gyermely felől is elérhető.'),
    ('Csabrendek', 'A Bakony utolsó nyúlványa, a sokak által csak Csúcsoshegynek nevezett, 374 méter magas Rendeki-hegy lábánál fekszik. A falu nagy része kisebb-nagyobb kiemelkedéseken terül el, így egyes utcáiban jelentős szintkülönbség-emelkedés figyelhető meg. A hegyről lenézve hosszan el lehet látni, mert észak-északnyugat irányban sík vidék fekszik.'),
    ('Csaholc', 'Szomszédai: észak felől Kölcse és Sonkád, kelet felől Túrricse, dél felől Kisnamény, nyugat felől pedig Vámosoroszi. Közigazgatási területe északkeleti irányból Tisztaberekhez tartozó határrészekkel érintkezik, maga Tisztaberek település azonban távolabb fekszik, még Túrricsétől is délkeletre. A térség fontosabb települései közül Fehérgyarmat 18, Császló 13,5, Gacsály 9, Kisnamény 6, Vámosoroszi pedig 5 kilométer távolságra található.'),
    ('Csajág', 'A Balaton keleti szélétől 4 kilométerre fekszik, Lepsény és Berhida között nagyjából félúton, előbbitől 8 kilométerre északra, utóbbitól hasonló távolságra dél-délkeletre. A környék más fontosabb települései közül a Polgárditól mért távolsága légvonalban 9 (közúton 13), Balatonkenesétől pedig légvonalban mindössze 5 (közúton azonban ugyancsak 12-13) kilométer.'),
    ('Csanytelek', 'Magyarország leghosszabb falujának tartják. A település a dél-alföldi régióban, a Tisza jobb partján fekszik. Távolsága Csongrádtól 14, Szegedtől 36 kilométer. Szomszédai: észak felől Felgyő, kelet felől Szegvár (a folyó túlpartján), dél felől Baks, nyugat felől pedig Tömörkény. Csanytelek Árpád-kori település. 1075-ben említették először Chonu néven helyezkedik el.'),
    ('Csanádalberti', 'Szomszédai: észak felől Ambrózfalva, kelet felől Pitvaros, dél felől Csanádpalota, délnyugat felől pedig Királyhegyes. Nyugat felől az amúgy csaknem 20 kilométerre fekvő Makó városának nagy kiterjedésű északi külterületei határolják. A település környékén terül el a védett természeti értékekkel rendelkező Csikóspuszta. A község határában folyik a Királyhegyesi-Szárazér.'),
    ('Csanádapáca', 'Belterületének alaprajza csaknem pontosan rombusz alakot formáz, észak-déli irányú széles főutcájára három sor utca van felfűzve. Békéscsabától 25 kilométerre, Orosházától pedig 20 kilométerre található. Belterülete 378 hektár, külterülete 4753 hektár. Szomszédai: észak felől Gerendás, északkelet felől Csabaszabadi, kelet felől Medgyesbodzás, délkelet felől Nagybánhegyes, dél felől Kaszaper, nyugat felől pedig Pusztaföldvár.'),
    ('Csanádpalota', 'Lakónépesség tekintetében megelőzte a megye összes (nyolc) nagyközsége is, továbbá a Dél-Alföldön is a legkevesebb lakosú város. Közvetlenül a román határ mellett fekszik, Makótól mintegy 20 kilométerre keletre. Szomszédai: észak felől Csanádalberti és Pitvaros, északkelet felől Mezőhegyes, dél felől Nagylak, délnyugat felől Kövegy és Magyarcsanád, északnyugat felől pedig Királyhegyes.'),
    ('Csapi', 'Csapi a Zalai-dombságban, a Zalaapáti-hát területén fekszik. Önkormányzata Nagyrécse községben működik. Autóbuszok sűrűn érintik a települést, és kötik össze Nagykanizsával, Zalakomárral és Zalakarossal. A település első említése 1302-ből való Chopiként. A Kanizsát 1600-ban elfoglaló törökök teljesen elpusztították a települést, amely csak a 18. században éledt újjá.'),
    ('Csapod', 'Magyarország északnyugati részén, a Kisalföld nagytáj nyugati részén helyezkedik el, a Rábaköz és a Répce-sík közelében, Kapuvártól 13 kilométerre délnyugatra. A községhez tartozik Göbösmajor, mint külterületi lakott hely. Szomszédai: észak felől Fertőendréd, északkelet felől Vitnyéd és Hövej, kelet felől Himod, délkelet felől Dénesfa, délnyugat felől Pusztacsalád, északnyugat felől pedig Fertőszentmiklós.'),
    ('Csarnóta', 'A Villányi-hegység egyik magaslata, a Kopasz-hegy mellett fekszik, a Külső-Drávaszögben. A szomszédos települések: északkelet felől Túrony, dél felől Harkány, nyugat felől Szava, északnyugat felől pedig Garé. Nevét az első írásos emlékek 1309-ből Chernete, később Crnota alakban említik, 1542-ben még Charnotha alakban is olvasható. Első birtokosai a Dorozsma nembéli Garaiak voltak, akik később (1378-ban), kényszerűségből a báthmonostori káptalan kezére adták a település nagyobb részét.'),
    ('Csaroda', 'A szomszédos települések: észak felől Gelénes, északkelet felől Beregdaróc, kelet felől Márokpapi, dél felől Hetefejércse, délnyugat felől Jánd, nyugat felől pedig Tákos. Gelénessel a 4124-es, Hetefejércsével és Tarpával a 4125-ös út köti össze.. Csaroda és környéke már a honfoglalás előtt is lakott hely volt. Nevét írásos formában 1299-ben említik először az oklevelek.'),
    ('Csataszög', 'A közvetlenül határos települések: észak felől Hunyadfalva, északkelet felől Kőtelek, kelet felől Nagykörű, dél felől a Törökszentmiklóshoz tartozó Óballa, nyugat felől pedig Besenyszög. A közúti tömegközlekedést a Volánbusz autóbuszai biztosítják. Először 1864-1865-ben szerepel Csataházpart, Csataszög néven, Pesty Frigyes helységnévtárában helyezkedik el.'),
    ('Csatka', 'Ácsteszér 5 kilométer, Súr 6 kilométer, Réde 9 kilométer, Csesznek 10 kilométer távolságra található. Közeli települések még: Bakonyoszlop, Csetény és Szápár. A környék városai közül Kisbér 17 kilométer, Zirc 19 kilométer, Mór pedig 21 kilométer távolságra fekszik. Csatka nevét írásos formában 1326-ban említik először, egy királyi oklevélben. 1357-körül Kont nádor építtetett itt kolostort, a pálos szerzeteseknek.'),
    ('Csatár', 'A Zalai-dombságban, ezen belül az Egerszeg–Letenyei-dombság területén fekszik, a Csengő-patak mellett. A megyeszékhely Zalaegerszeg déli szomszédságában található, a központtól 5 kilométerre délre. A várost leszámítva csak három másik települési szomszédja van: kelet felől Pölöske, délnyugat felől Sárhida, nyugat felől pedig Bocfölde. Csak kevés híja van annak, hogy nem határos északkelet felől még Nemeshetéssel is.'),
    ('Csebény', 'Az ismert történelmi forrásokban Csebényt legkorábban 1211-ből, majd 1466-ból említik, Chebe alakban helyezkedik el. A középkorban a szomszédos – tőle nem sokkal északra fekvő, ma pusztának számító – Szabás falu lehetett jelentősebb, ugyanis 1332-1335 között ez utóbbit templomos helyként írták össze. 1542-ben Szabás plébániája már nem létezett, meglévő lakói elszegényedtek, majd a falu csakhamar el is néptelenedett.'),
    ('Csegöld', 'Régi ruszin falu volt, hagyományosan a környék legnagyobb ruszin közössége élt itt. Lakói mára teljesen elmagyarosodtak. A környező települések közül Fehérgyarmat 22, Zsarolyán 18, Jánkmajtis 5,5, Császló 3,5, Csengersima pedig 4,5 kilométer távolságra található. A közvetlen szomszédos települések: észak felől Jánkmajtis, északkelet felől Császló, délkelet felől Csengersima, dél felől Szamosbecs, Szamostatárfalva és Szamosangyalos, nyugat felől pedig Szamossályi és Hermánszeg.'),
    ('Csehbánya', 'A Magas-Bakonyban fekszik, a legközelebbi nagyobb város, Ajka központjától légvonalban 13, közúton 16 kilométerre északkeletre, Herendtől légvonalban 7, közúton 11 kilométerre északnyugatra. Bükk- és tölgyerdők veszik körül, határában ered a Torna-patak. A közvetlenül szomszédos települések: délkelet felől Szentgál, dél felől Városlőd, délnyugat felől Kislőd, északnyugat felől pedig Németbánya.'),
    ('Csehi', 'A Kemeneshát délkeleti csücskében fekszik. Nevét már az Árpád-korból ismerjük. Nevét 1217-ben említették először Cheeh formában, a vasvári káptalan birtokainak összeírásával kapcsolatban, majd az 1600-as években neve Vasvár közelsége miatt Vasvárcsehiként is ismert volt. Valószínűleg cseh telepesek alapították a falut. A falunak régi kőfallal körülvett temploma volt.'),
    ('Csehimindszent', 'A falu lakott területe az egykori Katonák útjától délre fekszik a Széplaki-patak völgyében. A középkorban létrejött és egészen a 19. század végéig működő kapcsolatrendszerben a falu a Graz-Körmend-Rábahídvég–Vasvár–Sümeg történelmi országút közelében helyezkedett el. Csehimindszent út menti település, azaz útifalu. A belterülettől leszakadva, önállóan fejlődött Potypuszta és Potyrózsa major.'),
    ('Csempeszkopács', 'Csempeszháza és Kopács községek egyesítéséből keletkezett. A szomszédos települések: észak felől Pecöl, kelet felől Meggyeskovácsi, délkelet felől Rum, dél felől Rábatöttös, délnyugat felől Nemeskolta, északnyugat felől pedig Vasszécseny. A község területén már a római korban éltek emberek. Ezt bizonyítja a templom feltárásakor…'),
    ('Csemő', 'Budapesttől mintegy 70 kilométerre található. A szomszéd települések: észak felől Cegléd, kelet felől Nyársapát, délkelet felől Nagykőrös, délnyugat felől Lajosmizse, nyugat felől Pusztavacs, északnyugat felől pedig Mikebuda. Csemő 1952-ben Nagykőrös és Cegléd külterületéből alakult.'),
    ('Csengele', 'A szomszédos települések: észak felől Petőfiszállás, északkelet felől Pálmonostora, délkelet felől Kistelek és Balástya, dél felől Kömpöc, délnyugat felől Kiskunmajsa, északnyugat felől pedig Jászszentlászló.'),
    ('Csenger', 'A megyeszékhely Nyíregyházától 85, Mátészalkától 32 kilométerre, a határ túlsó oldalán fekvő Szatmárnémetitől 18 kilométerre található. A városba közúton pl. autóval, autóbusszal és vasúton is el lehet jutni.'),
    ('Csengersima', 'Közúti és teherforgalmi határátkelőhely található külterületén. 14 kilométer-re fekszik a romániai Szatmárnémeti. 1981-ben az 1970-es árvízben elpusztult Nagygéc községet a település közigazgatási területéhez csatolták. A település a Szatmári-sík kistáj területén található. Délkelet felől északnyugatnak lejtő síkság, melyet különböző mértékben feltöltött elhagyott folyómedrek sűrű hálózata borít.'),
    ('Csengerújfalu', 'A környező települések közül Fehérgyarmat 27, Csengersima 13, Cégénydányád 19, Komlódtótfalu 9, Csenger pedig 6 kilométer távolságra található. Csengerújfalu régi település, mely mindig Csengerhez tartozott és annak sorsában osztozott. A 16. század közepéig a Csaholyiaké volt, s az ág kihaltával fiúsítás által a Brebiri Melith család tagjai kapták.'),
    ('Csengőd', 'Csengőd a Kiskunsági-homokhátság egyik települése. Kiemelt tájvédelmi körzete a Turjános, mely a Kiskunsági Nemzeti Park kezelésében áll. Az izsáki Kolon-tó és az azt magában foglaló nemzeti parki védett területi egység délnyugati része is közigazgatásilag Csengődhöz tartozik. Fontosabb külterületi lakott helyek: Bucka, Kiscsengőd, Kullér és Tibold.'),
    ('Csenyéte', 'Encstől 20, Miskolctól közúton 57 kilométerre északra fekszik. Felsőgagy 3, Alsógagy 7, Gagyapáti 9 kilométerre van a falutól. A legközelebbi város, Encs mintegy 20 kilométerre fekszik. Neve valószínűleg magyar személynévi eredetű, amely név a szlávból került a magyarba. Első említése 1243-ból, Fáj adományleveléből származik, ahol Fáj déli határos falvaként említették.'),
    ('Csepreg', 'Csepreg német neve Tschapring. Horvát neve Čepreg, de régen az olmódi horvátok Čapriegnek, a peresznyei horvátok Čepriegnek nevezték a falut. A település az ország fő közúti közlekedési útvonalaitól távol esik, csak mellékutakon közelíthető meg.'),
    ('Cserdi', 'Vonattal elérhető a Budapest–Pécs-vasútvonalon, amelynek egy megállási pontja van itt, Cserdi-Helesfa megállóhely. Az Árpád-kori település, Cserdi nevét 1294-ben említették először az oklevelek Chergy módon írva, 1326-ban Chereg, 1450-ben Cherdy, 1884-ben Cserdi alakban írták és a szentlőrinci keresztesek birtoka volt. A falu neve Csergi Miklós nevében tűnt fel, ki 1294-ben Welk fia László szerviense volt. 1326-ban a falut az ispotályos keresztesek Szentlőrinccel együtt bérbe adták, majd később az Esterházy család lett birtokosa.'),
    ('Cserháthaláp', 'Balassagyarmattól 12 kilométerre délkeletre, Szécsénytől 15 kilométerre délnyugatra található. Csak közúton érhető el, keleti és északnyugati szomszédai felől egyaránt a 2123-as, Terény felől a 2124-es, Magyarnándor felől pedig a 2125-ös úton. Az ország távolabbi részei felől az Aszód és Balassagyarmat közt húzódó 2108-as útról közelíthető meg, a legegyszerűbben, mohorai vagy magyarnándori letéréssel.'),
    ('Cserhátsurány', 'A Novohrad-Nógrád UNESCO Globális Geopark települése. A Cserhát középső részén fekszik, a legközelebbi várostól, Balassagyarmattól mintegy 15 kilométerre dél-délkeleti irányban. A közvetlenül határos települések: észak felől Iliny, északkelet felől Varsány, kelet felől Herencsény, dél felől Terény, nyugat felől Cserháthaláp, északnyugat felől pedig Nógrádmarcal.'),
    ('Cserhátszentiván', 'A Novohrad-Nógrád UNESCO Globális Geopark települése. Szécsénytől délkeletre, Alsótold és Ecseg között fekszik. Nevét temploma és a falu védőszentjéről, keresztelő szent Jánosról kapta. Szomszédos települések még Herencsény és Kutasó. A honfoglalás előtti időkből szkíta és avar leletek kerültek elő. Itt haladt át a Szuha patak mentén a Hatvant Szécsénnyel összekötő kereskedelmi-hadi út, és innen ágazott el Balassagyarmat felé.'),
    ('Cserkeszőlő', 'Nyugati irányban Kecskemét, északra Tiszaföldvár, míg keleti irányban Kunszentmárton a legközelebbi városok. Budapesttől 127 kilométerre, Szolnoktól és Kecskeméttől 45-45 kilométerre található. Az autóútra a legközelebbi fel- és lehajtási lehetőség a községtől nyugatra épült ki, Tiszakürt és Cserkeszőlő között.'),
    ('Cserkút', 'Pécstől 9 kilométerre nyugat-északnyugatra, a Mecsekalján, a Jakab-hegy lábánál lábánál helyezkedik el. A Jakab-hegy a térség kedvelt kirándulóhelye, ahova a kék háromszög turistajelzés vezet fel. Cserkút és környéke ősidők óta lakott hely volt. A felszínre került régészeti leletek is bizonyítják, hogy már a kora vaskorban is éltek itt emberek, és a római korban számos villa épült itt.'),
    ('Csernely', 'Az Upponyi-hegységtől délnyugatra, a Csernely-patak völgyében, tagolt medencedombsági területen helyezkedik el, a megyeszékhely Miskolctól 60 kilométerre nyugatra, Ózdtól 11 kilométerre délkeletre. Környezetében az erdők aránya jelentős. A környező települések: északkelet felől Csokvaomány, kelet felől Lénárddaróc (3 kilométer), dél felől Bükkmogyorósdtól (2 kilométer), délnyugat felől Balaton és Járdánháza, nyugat felől Arló, északnyugat felől pedig Somsály (Ózd része) és Farkaslyuk.'),
    ('Cserszegtomaj', 'Keszthelytől északra a Keszthelyi-fennsík délnyugati lábánál helyezkedik el. Cserszeg település neve a magyar cser és szeg (szeglet) szavak összetételéből származik. Tomaj helységnév a Tomaj nemzetség nevéből származik. A község területén római és avar kori leletek találhatók, amelyek arra utalnak, hogy ezekben az időkben lakott volt ez a terület, és a mai Keszthely területén lévő központ felügyelete alatt volt.'),
    ('Csertalakos', 'Közigazgatási területét egy rövid, néhány tíz méteres szakaszon érinti az Ortaháza-Zebecke közt húzódó 7548-as út is. A középkori település első írásos említése 1353-ból származik, ekkor Possesio Lakus formában szerepelt, később Cheplakus alakban írták. Ekkori birtokosa a Rezneki család volt, később az Egerváriaké lett. 1426-ban Egyedlakos volt a neve, majd a török idők alatt elnéptelenedett és később újjátelepült falut 1773-ban már Cserta Lakosnak hívták.'),
    ('Csertő', 'A Zselic déli részén fekszik, az Almás-patak mellett, Szigetvár észak-északnyugati szomszédságában, a város központjától mintegy 7 kilométerre. A további határos települések: észak felől Szulimán, északkelet felől Mozsgó, délnyugat felől Basal, nyugat felől Somogyapáti, északnyugat felől pedig Somogyviszló. Belterületének keleti széle mellett terül el az Almás-patak felduzzasztásával létrehozott Csertői-halastó.'),
    ('Cserénfa', 'A település első írásos említése 1536-ból származik, nevét az ekkori adólajstromban Cyerefalva alakban írták. Ekkor Török Bálint birtoka volt, majd a törökök kiűzése után az Esterházy családé lett. 1715-ben mindössze 10 adózó jobbágy lakta, de 1720-ban már 22 család élt itt. 1870-re a lakosság száma elérte a 369-et. A falu első, római katolikus iskolája 1889-ben nyílt meg: az egyetlen tanító ekkor 47 gyermeket oktatott.'),
    ('Cserépfalu', 'A Bükk-vidék középső részén helyezkedik el, a megyeszékhely Miskolctól 57 kilométerrel délnyugatra, Egertől 20 kilométerrel északkeletre. Északnyugati szomszédja, Bükkzsérc zsáktelepülésnek tekinthető, mely csak innen érhető el, a 25 112-es számú mellékúton. A Hór-völgy kapujában épült falu története a 12. század elejéig követhető vissza. Írásban először 1196-ban említik Cheryp néven helyezkedik el.'),
    ('Cserépváralja', 'A Bükk-vidék középső-déli részén fekszik, a megyeszékhely Miskolctól körülbelül 50 kilométerre délnyugatra. A szomszédos települések: északkelet felől Kács, kelet felől Tibolddaróc, dél felől Tard, délnyugat felől Bogács, nyugat felől pedig Cserépfalu. A legközelebbi város a 18 kilométerre délre fekvő Mezőkövesd. A terület már az ókorban is lakott volt.'),
    ('Csesznek', 'A Bakonyban található, Zirctől 11 kilométerre északra. Gyakorlatilag teljesen összeépült északi szomszédjával, Bakonyszentkirály településsel. A települést a 13. századból ránk maradt források említik először, Cezneyc néven helyezkedik el. Később Csesztnök, Cseszneg(h) néven is ismert. Magyarország helységeinek 1773-ban készült hivatalos összeírása Cseszneg néven említi, Pesty Frigyes 1864. évi kéziratos helynévgyűjteménye a községet Cseszneknek, a mellette lévő várromot Csesznegnek nevezi.'),
    ('Csesztreg', 'A faluból indul ki még egy út Szentgyörgyvölgy és Magyarszombatfa felé, ez a 7423-as út, amely a településközpont déli részén ágazik ki a 7416-osból helyezkedik el. A község elnevezése - nagy valószínűséggel - a horvát Čisty štrug kifejezésből ered, amelynek jelentése "tiszta patak". A település első említése 1257-ből való Cheztregh néven helyezkedik el.'),
    ('Csesztve', 'Balassagyarmat déli szomszédságában helyezkedik el, a várostól mintegy 7 kilométerre délre. Különálló településrészei: Kincsempuszta, az északi határszéle közelében, Galibapuszta, a központjától mintegy 2 kilométerre északnyugatra, valamint Bakópuszta, a központtól bő 1 kilométerre keletre helyezkedik el. Időszámításunk előtt 3500 táján ezen a környéken már megtelepedett az ember.'),
    ('Csetény', 'Csetény a Bakony keleti lejtőjén terül el, a Zirc-Mór között húzódó 8216-os út mentén, Zirctől mintegy 13 kilométerre. A szócikk községtörténeti része a Csetény község története című könyv alapján íródott, a szerző hozzájárulásával. A község határa már a csiszolt kőkorban – a Kr. e. 3500 és 2500 közötti években – is lakott hely volt. Határában két telep maradványait is megtalálták a régészek.'),
    ('Csibrák', 'A Dunántúli-dombságban, a Tolnai-Hegyhát szélén, a Kapos mellett található, a völgységi dombok folyóra néző oldalán. A legközelebbi szomszédos települések Kurd 3 kilométerre délnyugatra, és Dúzs 4 kilométerre északkeletre helyezkedik el. A közúti tömegközlekedést a Volánbusz autóbuszai biztosítják. Első írásos említése 1280-ból származik. Ekkor a tolnai főesperességhez tartozó falu volt, a 16. század közepén Medvey Benedeké lett, de a török megszállás idején elpusztult.'),
    ('Csikvánd', 'Magyarország északnyugati részén, Téttől 9 kilométerre délre található. Határának jelentős részét szőlőskertek és erdők borítják, de mély fekvésű földek is tartoznak hozzá, ezekre utal a címerében látható víz és gyékény. A falut a törökök 1543-ban elfoglalták, de lakói csak akkor menekültek el, amikor 1594-ben Győr és Pápa is török kézre került. 1611-ben már ismét több magyar nemes: Cziráky Mózes, Kisfaludy Balázs, Újszászi Ferenc, Egerszegi István, Sziky Gergely és mások birtoka.'),
    ('Csikéria', 'Közvetlenül Szabadka városa mellett, annak nyugati szomszédságában fekszik. A szomszédos települések a határ magyar oldalán: észak felől Tompa, délkelet felől Kunbaja, nyugat felől Bácsszőlős, északnyugat felől pedig Mélykút. A mai magyar Csikéria nevű település…'),
    ('Csikóstőttős', 'A legközelebbi szomszédos települések Kaposszekcső és Mágocs. Első ismert írásos említése 1510-ből való (Tutus alakban), a 17. század végén Csikos Tótos módon írva szerepelt, ekkor Anyavárhoz tartozott. A török hódoltság idején lakossága megfogyatkozott, helyükre a 18. század elején német telepesek költöztek. A falunak ma is jelentős német kisebbsége van (kb. 12%, 2001).'),
    ('Csincse', 'A közigazgatási területével határos települések északnyugaton Vatta, északkeleten Emőd, délkeleten Mezőcsát, délen Gelej, délnyugaton pedig Mezőkeresztes, de ezek közül kiépített közúti kapcsolata csak Vattával és Mezőkeresztessel van, mindkettővel az őket összekötő 3306-os út kapcsolja össze. A terület a népvándorlás kora óta lakott, a térségben az ún. hatvani kultúrához tartozó leletanyag került elő.'),
    ('Csipkerek', 'A Kemeneshát középső részén helyezkedik el. Dombos vidéken fekszik, határában erdők és szőlőhegyek találhatók. A helységnév feltételezések szerint csipkebokrokkal benőtt, kerek erdőrészre utal, s az összetételi tagok megrövidült ejtéséből származik: csipke + kerek = csipkerek. Emellett ismert egy legenda is, amely más magyarázatot ad a névre: „Egykor, mikor a szekérkerék még nagy érték volt, egy kereskedőnek éjszakai pihenője folytán valamelyik kereskedőtársa ellopta a kocsikerekét.'),
    ('Csitár', 'Különálló településrésze Nógrádgárdony, mely a központjától dél-délnyugati irányban fekvő magaslaton alakult ki, a hajdani Majláth-kastélyt övező majorság helyén helyezkedik el. Éghajlata mérsékelten hűvös – mérsékelten száraz. Évi középhőmérséklete 9-9,2 ℃. A napsütéses órák száma évi 1900, csapadékból évente 610 mm hull. Megtalálható itt az erősen szabdalt dombvidék és a földművelésnek kedvező síkság is.'),
    ('Csobaj', 'Miskolctól körülbelül 50 kilométerre keletre, Tokajtól 15 kilométerre délre fekszik a Tisza mellett. A környező települések közül Taktabáj és Tiszatardos 3-3, Prügy 9 kilométerre található. A település tömegközlekedéssel a Volánbusz 3853-as járatával érhető el. Az 1981. évi ásatások során feltárt kelta eredetű sírokban talált temetkezési tárgyak, melyek a miskolci Herman Ottó Múzeumban találhatók, azt bizonyítják, hogy Csobaj község eredete az időszámításunk előtti időkre nyúlik vissza.'),
    ('Csobád', 'Miskolctól körülbelül 25 kilométerre északkeletre helyezkedik el, a Hernád völgyében, Szikszó és Encs között nagyjából félúton. A közvetlenül határos települések: északkelet felől Ináncs, kelet felől Hernádszentandrás, délkelet felől Felsődobsza, dél felől Hernádkércs (utóbbi kettő a Hernád túlpartján), délnyugat felől Kiskinizs, északnyugat felől pedig Léh.'),
    ('Csobánka', 'A település az Országos Kéktúra 15-ös számú szakaszának útvonalán fekszik. A település a 328 méteres Oszoly-csúcs, a 352 méteres Csúcs-hegy, a 488 méteres Kis-Kevély, a Csobánkai-nyereg és a 470 méteres Hosszú-hegy határolta medencében fekszik, mely észak-északnyugati irányból nyitott. Bár a hűvösebb levegő beáramlása miatt itt pár fokkal mindig alacsonyabb a hőmérséklet, mint a környező településeken, de épp ennek köszönhető különleges szubalpin klímája, mely a légzőszervi betegségben szenvedőknek gyógyírt jelenthet.'),
    ('Csokonyavisonta', 'Barcs északi szomszédságában helyezkedik el, a város központjától nagyjából 13 kilométerre. Belterülete ma mintegy 6 kilométer hosszan nyúlik el észak–déli irányban, északi felét az egykor önálló Somogyvisonta alkotja, déli településrésze önálló községként az Erdőcsokonya nevet viselte. A közvetlenül határos települések: észak felől Görgeteg, északkelet felől Homokszentgyörgy, kelet felől Szulok, dél felől Somogytarnóca (Barcs része), délnyugat felől Komlósd és Babócsa, nyugat felől pedig Somogyaracs és Rinyaújlak.'),
    ('Csokvaomány', 'Az Upponyi-hegységtől nyugatra, tagolt, medencedombsági területen fekszik, a Csernely-patak oldalvölgyében, Miskolctól közúton kb. 50 kilométerre nyugatra, Ózdtól 20 kilométerre délkeletre. A környező települések a mintegy 5 kilométerre fekvő Lénárddaróc, Nekézseny és Sáta. A legközelebbi város Ózd. Bár a területén áthalad a 2518-as út, belterülete vonatkozásában zsáktelepülésnek tekinthető, mert közúton csak az abból kiágazó 25 119-es számú mellékúton közelíthető meg.'),
    ('Csolnok', 'Festői fekvésű település, hegyekkel és erdőkkel körülvéve. Legmagasabb pontja a Nagy-Gete hegy, amelynek gerincén vezet át az Országos Kéktúra nyomvonala. Szomszédos települések: Dorog, Leányvár, Dág, Sárisáp és Tokod. A Római Birodalom idején Gardellacán (mai nevén Tokodon), a római limest védte az ide épített castrum (erődítmény) és a benne szolgáló légió.'),
    ('Csoma', 'A szomszédos települések: észak és kelet felől Attala, dél felől Kercseliget, nyugat felől pedig Szabadi. A legközelebbi város Dombóvár 7 kilométerre keletre helyezkedik el. Bár nincs túl közel a Balaton déli partjához, szőlő- és borgazdasági szempontból mégis a Balatonboglári borvidék részét képezi. Csoma és környéke már ősidők óta lakott hely, amit a határában feltárt rézkori település és temető is bizonyít.'),
    ('Csombárd', 'Kaposvár északnyugati előterében, Mezőcsokonya, Bodrog, Somogyjád és Hetes közt fekvő település, közúton a Hetes–Osztopán közti 6706-os úton érhető el. Földrajzilag Belső-Somogy északkeleti, Külső-Somoggyal határos peremén, a Fonyódnál a Kis-Balatont tápláló, hordalékkúpok közé szoruló Pogány-völgyi-víz bal partján fekszik. A település neve személynévi eredetű, de a som és bárd szavak összetételével kialakult, ’somfával vegyes erdőrész’ értelmezése is ismert.'),
    ('Csomád', 'A Pesti-hordalékkúpsíkság keskeny északi nyúlványa és a Gödöllői-dombság határán helyezkedik el. Településrészei: Régi Csomád, Akácos lakóliget, Napsugár utcai lakópark, Levente utcai lakópark. Közösségi közlekedéssel Újpest-Városkaputól a Volánbusz 313-as, 314-es, 315-ös, 316-os, 318-as és 319-es járataival közelíthető meg. Csomádnak a Budapest–Vácrátót–Vác-vasútvonalon egy vasútállomása is van, ám az valójában Fót külterületei között található, a községtől több mint 2 kilométer távolságban.'),
    ('Csongrád', 'Neve déli szláv nyelvből alakult ki, eredeti jelentése „fekete (földből való) vár”. Csongrád városa az Alföldön Tiszazugban, a Tisza jobb partján, a Hármas-Körös torkolata (Körös-torok) alatt fekszik, bár a határához tartoznak bal parti területrészek is. Szomszédai: észak felől Tiszasas, Csépa és Szelevény, kelet felől Szentes (az eddigiek mind a folyó túlpartján), dél felől Felgyő, délnyugat felől Gátér, nyugat felől Kiskunfélegyháza, északnyugat felől pedig Tiszaalpár.'),
    ('Csonkahegyhát', 'A Göcsej legmagasabban fekvő falva, 291 méterrel a tengerszint felett található. Csonkahegyhát közigazgatási határán belül emelkedik a Kandikó, ami 303 méteres magasságával a tájegység legmagasabb pontja. A település a Zalaegerszeget Becsvölgyén és Pórszombaton át Lenti északi agglomerációjával összekötő 7405-ös út mentén fekszik. A környező települések járatai mind érintik a falut.'),
    ('Csonkamindszent', 'Szigetvártól keletre fekszik, közvetlenül Szentlőrinc északnyugati szomszédságában. A további szomszédos települések: északkelet felől Helesfa, délnyugat felől Kacsóta, északnyugat felől pedig Dinnyeberki. Az Árpád-kori településnek már 1183-ban említették az oklevelek az Okor vize melletti, Mindenszentekről elnevezett monostorát, Okur alakban írva.'),
    ('Csopak', 'A Balaton keleti medencéjének északi partján fekszik, a Veszprémet a Balatonnal összekötő festői Nosztori-völgy szájánál, Balatonfüred (pontosabban az ahhoz csatolt Balatonarács) és Paloznak között. Vasúton a tó északi partján végigvezető Székesfehérvár–Tapolca-vasútvonalon közelíthető meg, ahol megállóhellyel rendelkezik. Áthalad a településen a balatoni „Római út” is, ami ezen a szakaszon a 7221-es számozást viseli.'),
    ('Csorna', 'A megye ötödik legnépesebb települése, „a Rábaköz fővárosa”. Területe a Fertő–Hanság Nemzeti Park része. Hozzá tartoznak Földsziget, illetve Csatárimajor külterületi városrészek is. Magyarország északnyugati részén, a Kisalföldön, a Győri-medence nyugati részén a Rábaközben fekszik. Külterülete északnyugati irányban mélyen (egyetlen helyen, pontszerűen még az országhatárral is érintkezően) benyúlik a Hanság déli medencéjébe.'),
    ('Csorvás', 'Szomszédai észak felől Kondoros, északkelet felől Kétsoprony, kelet felől Telekgerendás, dél felől Gerendás, délnyugat felől Orosháza, északnyugat felől pedig Nagyszénás, illetve Orosháza Kiscsákó nevű, exklávé jellegű külterületi városrésze.'),
    ('Csurgó', 'Három tájegység találkozásánál épült fel: az északnyugati Öreghegy és az Újhegy a Zalaapáti-hát legdélibb része, a Zákány-őrtilosi-dombság peremvidéke, északkeleten Belső-Somogy közel sík homokhátai határolják, míg délen a Dráva egykori medrének magaspartja. Bár meglehetősen távol fekszik a Balaton déli partjától, a település szőlő- és borgazdasági szempontból mégis a Balatonboglári borvidék…'),
    ('Csurgónagymarton', 'Csurgó várostól 4 kilométerre északra, erdővel borított dombok között fekszik. A további, közvetlenül határos települések: észak felől Iharos, délnyugat felől Porrogszentkirály, nyugat felől pedig Porrog. Nevével először 1367-ben keltezett okiratban találkozhatunk a vránai perjelség birtokai között. 1472-ben Kisfaludi János nyerte adományul, Kisújlak-pusztával együtt. 1536-ban Drághy Miklós, 1550-ben Török József, 1598-99-ben Zrinyi György és 1626-ban és 1660-ban is a Zrinyi család birtoka volt. 1715-ben 10…'),
    ('Csáfordjánosfa', 'A nyugat-magyarországi peremvidék nagytáj része. Éghajlata kiválóan alkalmas növénytermesztésre helyezkedik el. A Répce mellett nagy kiterjedésű rét található, amelynek termése az állattartás alapjául szolgál. A szántóföldeken búza, kukorica, árpa, zab, napraforgó, cukorrépa, burgonya jó minőségben és nagy mennyiségben termeszthető. A településnek két természetvédelmi területe van, az egyik a Répceszemere felé vezető út mellett elhelyezkedő magyar kőrisfák, életkoruk 140 év körüli, a másik ilyen terület a tőzikés erdő.'),
    ('Csákberény', 'Határa benyúlik a Vértes és a Velencei-hegység közötti Zámolyi-medencébe. Székesfehérvártól 25, Mórtól 15, Budapesttől 65 kilométerre található. Területe már a kőkorszakban is lakott terület volt. A Római Császárság idejében itt vezetett keresztül az Aquincumból Mogentiana (Óbuda – Keszthely) felé vezető jelentős hadiút, melynek mentén, Csákberény területén a Kr. utáni III. és IV. században már két római telep is állott.'),
    ('Csákvár', 'A környező jelentősebb települések közül Vértesboglár 6, Lovasberény 13, Bicske 19, Oroszlány pedig 24 kilométer távolságra található. Külterületi településrészei közé tartozik Móriczmajor, mely a központjától 5 kilométerre fekszik északkeleti irányban. Utóbbi településrészen a lakások száma 2001-ben 26, a lakónépesség pedig ugyanabban az évben 91 fő volt.'),
    ('Csákány', 'Csákány első említése 1389-ből származik, amikor Segesd vár javadalmaként tartották számon helyezkedik el. Öt évre rá a Marczali család adományként megkapta a települést Zsigmond királytól helyezkedik el. A 15. században a falu már rendelkezett plébániával, egy másik templommal és egy ferences kolostorral is. A portyázó törökök 1532-ben megtámadták a védtelen kolostort és legyilkoltak négy szerzetest.'),
    ('Csákánydoroszló', 'A mai településmag két, egykor különálló község egyesítésével jött létre: a hajdani Rábadoroszlóból a község keleti, Nagycsákányból a nyugati része alakult ki. Közigazgatási területének északi részé régen egy harmadik falu is feküdt, Magyarbüks, amely azonban az évszázadok során nagyrészt elpusztult. A közvetlenül határos települések: észak felől Kemestaródfa, északkelet felől Magyarnádalja és Körmend, kelet felől Halogy, délkelet felől Felsőmarác, dél felől Ivánc, délnyugat felől Hegyhátszentmárton, nyugat felől pedig Gasztony.'),
    ('Csánig', 'A Répce mellett fekszik, Répcelakkal majdnem egybeépülve, attól északra. Közúton a legegyszerűbben a 86-os főútról közelíthető meg, Répcelak központjában lekanyarodva a 8615-ös útra, majd a Répce hídját elhagyva rátérve az abból kiágazó 86 124-es számú mellékútra helyezkedik el. Csánig neve személynévi eredetű. A település és környéke már a honfoglalás előtt is lakott volt, amit az itt napvilágra került régészeti leletek is bizonyítanak.'),
    ('Csány', 'A közvetlen szomszédos települések: észak felől Hort, északkelet felől Atkár, kelet-délkelet felől Jászárokszállás, dél felől Jászágó, délnyugat felől Jászfényszaru, nyugat felől pedig Hatvan helyezkedik el. Kelet felől a legközelebbi település Vámosgyörk, de a közigazgatási területeik nem határosak. Éghajlata mérsékelten meleg, száraz, mikroklímáját a Mátra szélárnyékoló hatása határozza meg.'),
    ('Csányoszró', 'Az Ormánság középső-északi részén helyezkedik el, Sellyétől 4 kilométerrre keletre. A megyeszékhelyről, Pécsről Vajszlón vagy Szentlőrincen keresztül közelíthető meg, az 5801-es vagy az 5805-ös úton helyezkedik el. Csányoszró Árpád-kori eredetű település, területe a honfoglalás után a Kán nemzetség birtokai közé tartozott. Itt állt az oszrómindszenti apátság kolostora helyezkedik el.'),
    ('Csárdaszállás', 'Békéscsabától északnyugatra, Gyomaendrőd és Mezőberény között fekvő település. Szomszédai: északkelet felől Körösladány, kelet felől Köröstarcsa, délkelet felől Mezőberény, északnyugat felől pedig Gyomaendrőd. Déli, délnyugati és nyugati irányból a két utóbbi városhoz tartozó, jobbára lakatlan külterületek határolják, délnyugat felől a legközelebbi település Hunya, de a közigazgatási területeik nem érintkeznek egymással.'),
    ('Császló', 'Távolsága Budapesttől közúton 321, Nyíregyházától 93 kilométer. Szomszédai: északkelet felől Gacsály, dél felől Csengersima, délnyugat felől Csegöld, nyugat felől Jánkmajtis, észak-északnyugat felől pedig Kisnamény. Az Árpád-kori falvak szerkezetét, így Császlóét is alapvetően meghatározta természeti környezete. Általában állóvíz vagy vízfolyás közelében, de árvízmentes magaslaton létesültek.'),
    ('Császár', 'A környező települések közül Dad 6,5, Vérteskethely 7,5, Kisbér 10,5, Szákszend 11, Oroszlány pedig 19 kilométer távolságra található. Közösségi közlekedéssel ma csak autóbusszal érhető el a település: a 770-es, 1257-es, 1702-es, 1848-as, 1851-es, 8464-es, 8560-as, 8618-as, és 8736-os buszjáratokkal. A településen 3 buszmegálló található (Császár,posta, Császár, Márkustag bejárati u., Császár, Petőfi u.).'),
    ('Császártöltés', 'Határának legmagasabb pontja a 143 méter magas Boszorkányhegyen, legmélyebb a csatorna parton 93 méter magasságban található. Altalaja agyag, felszíni talaja nagyobb részben homok és tőzeg. A Kiskunság és a Sárköz határában változóan hullámos felszínre épült falu településszerkezetének különlegességét az árterület szélén magasodó löszpartba fúrt, présházas pinceutcák adják.'),
    ('Csátalja', 'Bajától mintegy 20 kilométerre délre fekszik, a Duna bal parti oldalán. A szomszédos települések: észak felől Bátmonostor, északkelet felől Vaskút, kelet felől Gara, dél felől Dávod, nyugat felől pedig Nagybaracska. Központján azonban csak az 5505-ös út halad végig, mely Bácsbokodon át Csávolytól húzódik idáig. Csátalja különböző neveken már a középkorban is lakott hely volt, de ezen a néven először egy 1543-as dézsmajegyzékben szerepel.'),
    ('Csávoly', 'Bajától mintegy 15 kilométerre keletre található. Környezetét nagyban az Alföldre jellemző tulajdonságok határozzák meg. A tájba változatosságot a Kígyós-főcsatorna egy mellékágának a falut kettészelő völgye, illetve az abban kialakított két mesterséges tó hoz. A szomszédos települések: észak felől Rém, kelet felől Felsőszentiván, nyugat felől Baja, északnyugat felől pedig Érsekcsanád és Sükösd.'),
    ('Csécse', 'Pásztó délnyugati szomszédságában fekszik, a Zagyva völgyének nyugati oldalán. A további szomszédos települések: észak felől Ecseg, kelet felől Szurdokpüspöki, délkelet felől Jobbágyi, dél felől Szarvasgede, délnyugat felől Kisbágyon, nyugat felől pedig Buják. Csak közúton érhető el, Pásztó, Ecseg vagy Szarvasgede felől. Előbbivel a 2127-es, utóbbiakkal a 2128-as út köti össze.'),
    ('Csém', 'A község területének nagy része 120-130 méter magasságú síkság. Gyengén tagolt, a Duna teraszos hordalékkúpja. A mélyebben fekvő kavicsrétegek víztartalmát fúrt kúttal kihasználva a település saját vízellátó rendszerrel rendelkezik. A felszínen laza kőzetek találhatók: folyóvízi homok, kavics és iszap, bemosódott lösszel keverve. A közepes termékenységű mészlepedékes…'),
    ('Csénye', 'A Gyöngyös és a Hosszúvíz-patak találkozásánál található. Sárvártól 5 kilométerre nyugatra fekszik. Porpác, Bögöt, Ikervár és Megyehíd települések veszik körül. Része még Füztű is, amely Csénye és Megyehíd között fekszik. Csénye első írásos említése 1221-ből származik, még Chence alakban írva. A község neve régi okiratokban többféleképpen szerepel: Cheyne (1283), Chene (1390, 1424, 1492).'),
    ('Csép', 'Nyugati szomszédjával, Tárkány községgel a 8148-as út kapcsolja össze, a tőle keletre fekvő településekkel nincs közvetlen közúti összeköttetése. Az Igmándi-Kisbéri-medence kistáj közepén helyezkedik el. A táj itt már délről északra haladva hullámos síksággá szelídül. A felszínt több vízfolyás, köztük a Concó-patak, Császár-ér és a Vékony-ér patakvölgyei tagolják. [A lakosság (táv)vezetékes ívóvízrendszerében ennek ellenére tatabányai víz folyik.] A felszínt lösszel átitatott ártéri homok, kavics és iszap alkotja.'),
    ('Csépa', 'A község a Tiszazugban helyezkedik el, a Tisza bal partján. Szomszédai: észak felől Tiszakürt, északkelet felől Cserkeszőlő, kelet felől Szelevény, dél felől Csongrád (a folyó túlpartján), nyugat felől Tiszasas, északnyugat felől pedig Tiszaug. Csépa éghajlata száraz, mérsékelten meleg. Az északi, északnyugati szélirány az uralkodó. A csapadék rendkívül egyenlőtlen eloszlása rányomja bélyegét az adott év termésre, vagyis a betakarított gabona és leszüretelt szőlő mennyisége és minősége nagyban függ a csapadék eloszlásától…'),
    ('Csér', 'A szomszédos települések: észak felől Iván, kelet felől Csáfordjánosfa, dél felől Nagygeresd, délnyugat felől pedig Nemesládony. Éghajlati viszonyai a mezőgazdasági termeléshez kedvező feltételeket biztosítanak. Autóbuszjáratok Sopronnal és Kapuvárral kötik össze. Az ismert oklevelekben először 1313-ban jelent meg a neve (Cher) formában…'),
    ('Csévharaszt', 'A község földrajzi elhelyezkedéséből adódóan nagy Budapest vonzereje a munkalehetőségek, a tanulás, a szórakozás területén. A munkaképes lakosság 60%-a a fővárosban, 38%-uk helyben illetve a környező településeken dolgozik. Ez az út ugyanis nem más, mint az ősi nagykőrösi marhahajtó országút, ami ugyan…'),
    ('Csókakő', 'A Móri-árok Vértes felőli oldalán helyezkedik el, a móri borvidékhez tartozik. Mórtól körülbelül 10, Székesfehérvártól 23 kilométerre fekszik. A falu neve eredetileg kizárólag a várra vonatkozott. A település neve valójában Váralja volt. Említése 1461 után már nem szerepel az okmányokban, amiből arra lehet következtetni, hogy a település a török idők elején megsemmisült.'),
    ('Csólyospálos', 'A szomszéd települések: észak felől Kömpöc, kelet felől Balástya, délkelet felől Forráskút, dél felől Üllés, északnyugat felől pedig Kiskunmajsa. Délnyugati és nyugati irányból ugyancsak ez utóbbi városhoz tartozó külterületek övezik. Csólyospálos két puszta: Csólyospuszta és Pálospuszta tanyavilágának összeolvadásából keletkezett, 1945. július 1-én lett önálló község.'),
    ('Csór', 'Székesfehérvár és Várpalota között fekszik, utóbbihoz kicsit közelebb. Északon a Bakony, délen a Sárrét öleli körbe. A közvetlenül határos települések: észak felől Iszkaszentgyörgy, kelet felől Székesfehérvár, délkelet felől Sárszentmihály, dél felől Sárkeszi, délnyugat felől Nádasdladány, nyugat felől Várpalota (Inota), északnyugat felől pedig Bakonykúti és Isztimér.'),
    ('Csót', 'A település a Bakonyalja északi részén, Pápától 13 kilométerre északkeletre fekszik. A már a rómaiak által ismert terület első írásos emlékei 1212-re vezethetők vissza. Első okleveles említése 1488-ból származik. A 15. század elején a veszprémi püspökség birtoka volt, öt évvel később az esztergomi érseké. 1626-tól az Esterházy család ugodi birtokához tartozott.'),
    ('Csöde', 'Önkormányzata Zalalövőn működik. Az említett út Alsócsödén, majd Felsőcsödén végighaladva egészen Kerkafalváig húzódik, de a Felsőcsöde utáni szakasza már csak önkormányzati útnak minősül. Így naponta több járat köti össze Zalalövővel és Zalaegerszeggel, de Körmend is közvetlenül elérhető a településről. A település első említése 1342-ből Chede alakban való.'),
    ('Csögle', 'Csögle a Kisalföld középtáján a Marcal-medencében, a Marcal folyó mentén észak-déli irányban hosszan elnyúló Marcal-völgy középső részén, a folyó 4–5 kilométer széles teraszos völgyében helyezkedik el. Közigazgatási területe kelet felől, pontszerűen érintkezik még Nagyalásony, kelet felől pedig egy rövidke szakaszon Celldömölk határszélével is. A község határában fut a Marcal folyó, melynek medre és partja gazdag élővilággal bír.'),
    ('Csökmő', 'A Bihari-sík délnyugati peremén, a Berettyó és a Sebes-Körös folyók találkozásához közel fekszik. A legközelebbi város Szeghalom 12 kilométerre nyugatra helyezkedik el. További szomszédai: északkelet felől Darvas, kelet felől Komádi, délkelet felől Újiráz, nyugat felől Szeghalom, északnyugat felől pedig Füzesgyarmat. Különálló településrészei Kóróssziget, a központjától 3,5 kilométerre északra, valamint Czirkópuszta (vagy Cirko), 3 kilométerre kelet-délkeleti irányban helyezkedik el.'),
    ('Csököly', 'Területe mintegy 2984 hektár. Nagyatádtól északkeletre, Gige és Jákó közt fekszik, központján a Nagybajom-Kadarkút közti 6618-as út halad keresztül. Csököly nevét 1332-1337 évi pápai tizedjegyzék említette először, tehát már ekkor egyházas hely volt. 1382-1383-ban Chukul, 1466-ban Chekel alakban írták. 1466-ban a veszprémi püspökség birtoka volt, majd 1536-ban Pekry Lajos volt birtokosa.'),
    ('Csömend', 'A további, közvetlenül határos települések: észak felől Somogyszentpál, északkelet felől Táska, kelet felől Nikla, délkelet felől Libickozma, dél-délnyugat felől pedig Gyótapuszta (Marcali része). Táskával és Libickozmával nincs közvetlen közúti kapcsolata. Csömend nevét az 1332-1337. évi pápai tizedjegyzék említette először, tehát már akkor is egyházas hely volt.'),
    ('Csömödér', 'A Zalai-dombság nyugati peremén, a Kerka-folyó mentén, a Cserta és a Válicka patakok völgyében, Lenti városától délkeletre helyezkedik el. A település és környéke ősidők óta lakott, az első településnyomok az újkőkorból valók, de a római korból való településnyomok is előkerültek. Nevét 1324-ben említették először az oklevelek Chydemer alakban helyezkedik el.'),
    ('Csömör', 'A térségben a települést intenzív civil szervezeti, közösségi és kulturális élet jellemzi. 2010 óta országos viszonylatban is ritkaságnak számító módon, politikai pártoktól teljesen független civil önkormányzati vezetés működik Csömörön. Önkormányzati alapintézményei (polgármesteri hivatal, óvoda, bölcsőde) mellett evangélikus óvodája, általános iskolája, könyvtára, zeneiskolája, sportcsarnoka és egy különlegesen szép horgásztava is van.'),
    ('Csönge', 'A Rába folyó kavicsos hordalékából álló Kemenesháton fekszik, amelyet a 19. század közepéig hatalmas csererdő borított. Ezt később akácerdő váltotta fel, melynek szaporítóanyagát főleg az a fa adta, amely ma is (immár több mint 200 éve) áll a csöngei evangélikus parókia udvarán, s amely testvérfája a szarvasi „Tessedik-fának”. A szomszédos települések: észak felől Kenyeri, délkelet felől Vönöck, Kemenessömjén és Kemenesmihályfa, dél felől Ostffyasszonyfa, nyugat felől pedig Uraiújfalu.'),
    ('Csörnyeföld', 'A községet körülölelő dombok, a klimatikus adottságok kiválóan alkalmasak szőlőtermesztésre, az erdők értékes faállományukon kívül vadban rendkívül gazdagok. A település első írásos emléke 1361-ből származik.'),
    ('Csörög', 'Vác délkeleti szomszédjában fekvő település. Csörög földrajzi adottságai már az őskori ember számára is vonzóak voltak a letelepedésre helyezkedik el. Jellegzetes alakzat a miocén (föld-történeti harmadkori) eredetű csörögi Kígyó-hegy, amely vulkanikus eredetű andezit kőzetből áll. Érdekessége, hogy tulajdonképpen egy telér része, mely a Keleti-Cserhátból sugárirányban induló „kőzet- folyamok” közül a leghosszabb, 21 kilométer.'),
    ('Csörötnek', 'A rendszerváltást követő években megvalósult infrastrukturális fejlesztéseknek köszönhetően a település vízvezeték-, csatorna-, villany-, gáz- és kábeltévé- hálózattal rendelkezik. Szerekre oszló település. Magyar és katolikus község, a faluban roma közösség is él. Az kétségtelen, hogy a történelmi Őrség hatása mind nyelvben, mind szokásokban és akár a település szeres szerkezetében visszaköszön, ezen az alapon a vidék, benne Csörötnek az Őrséghez tartozónak tekinthető, de a történelmi Őrség mintegy 8–10 kilométer-re kezdődik a falutól.'),
    ('Csősz', 'A Mezőföldön, a Sárvíz-malomcsatorna mellett helyezkedik el, legközelebbi város a 15 kilométer-re található Székesfehérvár. Csősz címere úgynevezett csücskös talpú pajzson kék mezőben, zöld talajon, két lábon álló, nyelvét nyújtó, ordító, aranysárga színű, vörös nyelvű oroszlán látható, jobb mancsában vezéri botot (buzogányt), bal mancsában háromágú korbácsot tart (a hatalom jelképeit).'),
    ('Csővár', 'Csővár régi várát 1448–1461 között már említették, ekkor a Ráskayak kezén volt. Az alatta levő falu a 15. században a váci püspöké volt, 1460-ban Szadai Reichel Sebald, 1461-ben pedig Csóri Miklós volt Csővár kapitánya. A török megszállás alatt is lakott maradt. 1695-ben mint népes helységet 3/4 portával rótták meg. Az 1715–1720 évi összeírásokban nemes községként szerepelt.'),
    ('Cák', 'A kőszeghegyaljai falu Szombathelytől 25 kilométerre északnyugatra, Kőszegtől 6 kilométerre délnyugatra fekszik, a Kőszegi-hegység keleti lábánál. A szomszédos települések: délkelet felől Kőszegdoroszló, dél felől Kőszegszerdahely, délnyugat felől pedig Velem. A legközelebbi város a 6 kilométerre északkeletre fekvő Kőszeg, melynek csak külterületeivel határos a község.'),
    ('Cégénydányád', 'Szomszédai: észak felől Penyige, északkelet felől Zsarolyán, kelet felől Gyügye, dél felől Rápolt, délnyugat felől Ököritófülpös, nyugat felől Fülpösdaróc, északnyugat felől pedig Fehérgyarmat. A 4136-os út elméletileg Ököritófülpössel is összeköti, de mióta megszűnt az itteni kompközlekedés, nincs közúti kapcsolat a két település között. A település és környéke ősidők óta lakott hely, amiről…'),
    ('Cún', 'Cún nevét az oklevelek 1244-ben említették először Chun néven. 1332-ben Chun, 1479-ben Czwn alakban írták nevét. Az 1200-as évek elején a település az örökös nélkül elhalt János fia János és Péter birtoka volt. 1244-ben IV. Béla király Albert ispán fiának, Sup ispánnak adta, és határát leíratta. A falu a török hódoltság alatt is állandóan lakott volt.'),
    ('Dabas', 'Alsódabas és Felsődabas egyesítésével keletkezett 1950-ben, majd 1966-ban hozzá csatolták Gyónt és Sárit is. A mai város a területén korábban különálló négy falu (Gyón, Alsódabas, Felsődabas és Sári), illetve két, mára belterületté átalakult tanyacsoport (Dabasi Szőlők és Sáribesnyő) összevonásával jött létre. Északi részei a Pesti-síkságon, míg déli területei a kiskunsági homokhátságon fekszenek.'),
    ('Dabronc', 'A község körjegyzőségi székhelytelepülés, Hetyefő és Zalaerdőd települések tartoznak az itteni körjegyzőséghez. Közigazgatásilag hozzá tartozik a korábban önálló Ötvös falu is, amely a központtól elkülönülten helyezkedik el, attól mintegy 2,5-3 kilométerre nyugatra. Központját azonban egyik sem érinti – a 7331-es attól nyugatra halad el, Ötvösön keresztül, a 7337-es pedig a külterület déli részén –, oda csak a 73 168-as út vezet Zalaerdőd-Hetyefő felől és a 73 173-as út Ötvös felől.'),
    ('Dabrony', 'Az ország nyugati térségében, a Kisalföld legdélibb részét képező Marcal-medence szélén, a Bakonyaljának is nevezett átmeneti vidéken helyezkedik el. A Gányás- és a Hajagos-patakok medrei között létesült. Határai egyik oldalról a Marcal-völgy rétjeivel, mocsaras-lápos területeivel, másik oldalról a bakonyi erdők nyúlványaival érintkeznek.'),
    ('Dad', 'Budapesttől 80, Tatabányától 18, Oroszlánytól 10, Kömlődtől 5, Császártól 8, Kocstól pedig 12 kilométer távolságra található. Autóbusszal elérhető az 1256-os, 1702-es, 1848-as, 1851-es, 8464-es, 8560-as, 8562-es, 8570-es, 8574-esés 8594-es számú vonalakon helyezkedik el. Dadról az első írásos adat 1230-ból ismert, ekkor Dod alakban említették. Ennek ellenére 1326-ban Csák nemzetségbeli István fiainak birtokai között sorolták fel, melyet Károly Róbert király cserébe elvett tőlük.'),
    ('Dalmand', 'Ezek a mezővárosok többnyire a földesúri lakhelyet jelentő vár aljában, vagy közelében, keletkeztek. Lakóik jobbágyok voltak, melyeket egyedül kiváltságaik különböztettek meg a falusi jobbágyoktól helyezkedik el. Az egykori mezővárosa törökök kiűzése után pusztán maradt. Később az egykori nagybirtokok, elsősorban az Eszterházy-uradalom területén létrejött állami gazdaság központjaként fejlődött tovább.'),
    ('Damak', 'Edelény keleti szomszédságában fekszik, a megyeszékhely Miskolctól közúton kb. 30 kilométerre északra. A környező, közvetlenül határos települések: északkelet felől Lak (kb. 7 kilométer), kelet felől Hegymeg (5 kilométer), dél felől Hangács, nyugat felől Edelény (7 kilométer), északnyugat felől pedig Balajt. Csak közúton érhető el, Edelény felől, vagy Lak-Hegymeg érintésével – mindkét irányból a 2616-os úton –, Hangács felől pedig egy szilárd burkolatú, de számozatlan önkormányzati úton.'),
    ('Daraboshegy', 'A Vasi-Hegyháton elhelyezkedik el, Körmendtől néhány kilométerre délre. A Szent István korában alapított Nádasdi Plébánia tíz falujának egyike. Neve középkori birtokosaitól, a nádasdi Darabos családtól származik. 1870-ben lett önálló község, ekkor kapott bírói pecsétnyomót, amely ma is megtalálható a körmendi múzeumban. Postája és távírója Körmend.'),
    ('Darnó', 'Szomszédai: északkelet felől Vámosoroszi, kelet felől Kisnamény, dél felől Jánkmajtis, nyugat felől pedig Kisszekeres. A környező települések közül Kisnamény 5, Csaholc 10, Jánkmajtis 6, Szamosújlak 10,5, Gyügye pedig 17 kilométer távolságra található. A települést egykor szászok lakták, és Szaksza Darnó-nak nevezték. Darnó nevét a Hunyadiak korában már…'),
    ('Darnózseli', 'A település a Szigetközben, ezen belül is az úgynevezett Felső-Szigetközben található. Az Öreg-Dunától körülbelül 4 kilométerre, a Mosoni-Dunától mintegy 3 kilométerre fekszik. Mosonmagyaróvártól 16, a megyeszékhely Győrtől pedig 28 kilométerre található. A környező települések: északon Püski, Kisbodak és Dunaremete, keleten Lipót, délkeleten Hédervár, délnyugaton Novákpuszta (Kimle településrésze) és Kimle, északnyugaton pedig Arak (Halászi településrésze).'),
    ('Daruszentmiklós', 'A 6228-as út csak Kisszentmiklós nevű településrészét érinti, a település tulajdonképpeni központján, Daruhegyen csak a 62 123-as út húzódik végig. Dunaföldvár és Nagykarácsony egyaránt 8,5, Mezőfalva 9, Solt pedig 15 kilométer távolságra található. A község területének régmúltjáról Daruszentmiklós vidéke, illetve Mezőföld délkeleti része ősidők óta lakott terület volt.'),
    ('Darvas', 'A Berettyó bal partján, a Bihari-sík északnyugati peremén helyezkedik el. Határában folyik össze az Ölyvös-ér-mellékcsatorna és a Kutas-főcsatorna. Szomszédai: észak felől Nagyrábé, északkelet felől Zsáka, délkelet felől Komádi, dél felől Csökmő, nyugat felől pedig Füzesgyarmat. Kelet felől közel van hozzá még Vekerd is, de közigazgatási területeik nem érintkeznek.'),
    ('Darány', 'Barcstól 10 kilométerre keletre helyezkedik el, a Dráva közelében. A szomszédos települések: észak felől Istvándi, kelet felől Zádor, dél felől Kastélyosdombó, délnyugat felől Drávatamási, nyugat felől Barcs, északnyugat felől pedig Szulok. Darány első írásos emléke 1437-ből származik, amikor az utód nélkül elhalt Alsáni Gergely fia, János, birtokát a Marczaliaknak adományozták, de valószínűleg már korábban is létezett.'),
    ('Debercsény', 'A Cserhátban található, Szente és Magyarnándor között. Csak közúton érhető el, a két említett település valamelyikén keresztül, a 2118-as úton. Debercsény nevét 1335-ben említette először oklevél Deberchen néven helyezkedik el. Az Árpád-korban e tájon Szente és Ecset egymással érintkező határánál, a Mogyorós és Kövecses-hegy felé levő Csabád falu a Szentei nemesek földjével volt határos.'),
    ('Debrecen', 'Időnként „a kálvinista Róma” néven vagy „cívisváros”-ként emlegetik. A 13. században tűnik fel írott forrásokban, 1361-ben I. Lajos mezővárosi jogokat adott a városnak, majd 1693-ban szabad királyi várossá vált. Fő bevételi forrásai a szarvasmarha-kereskedelem, az állattenyésztés és a kézművesség voltak.'),
    ('Debréte', 'Földrajzilag az Észak- magyarországi középhegységben, az Aggtelek- Rudabányai hegység középtájban, azon belül a Tornai- dombság szívében található. Miskolctól közúton kb. 60 kilométerre északra, a szlovák határtól 6 kilométerre fekszik. Neve az ószláv debri (völgy) vagy dub (tölgyfa) szóból magyarosodott el. Északi határában ered a Debréte-patak, amely keresztül szeli a települést.'),
    ('Decs', 'A legközelebbi települések: Őcsény (3 kilométerre északra), Sárpilis (4 kilométerre délnyugatra), a legközelebbi városok: Szekszárd (11 kilométerre északnyugatra) és Bátaszék (14 kilométerre délnyugatra). Közigazgatási területe érintkezik még kelet felől Érsekcsanád és Baja, dél felől Pörböly és Alsónyék, nyugat felől pedig Várdomb és Alsónána határszéleivel is.'),
    ('Demecser', 'Központjától különálló településrésze Borzsova, néhány kilométerre délre helyezkedik el. A térség más, fontosabb települései közül Kék 4, Gégény 3, Dombrád 11, Berkesz 5, Székely pedig 6,5 kilométerre található. A közvetlen szomszédai: észak felől Dombrád, északkelet felől Gégény, kelet-délkelet felől Berkesz, délkelet felől Ramocsaháza, dél felől Székely, délnyugat felől Nyírbogdány, nyugat felől Kék, észak-északnyugat felől pedig Újdombrád.'),
    ('Demjén', 'Egertől 10 kilométerre délnyugatra, Egerszalóktól 5 kilométer távolságra helyezkedik el, a Laskó-patak mellett. Demjén határában újkőkori leleteket, valamint honfoglalás kori villás nyílhegyeket találtak. Írott forrás 1331-ben említi először Demyen névalakban.Csanád egri püspök vásárolta meg, majd 1331-ben – már mint esztergomi érsek – az egri káptalannak adta. 1363-ban Mihály püspök a gönci tizedeket cserébe adta a káptalannak Demjén faluért, mely ettől kezdve 1804-ig az egri püspöké, 1805-től pedig az érseké maradt.'),
    ('Dencsháza', 'Szigetvártól 7 kilométer-re délre helyezkedik el, déli szomszédja Szentegát, keletről Katádfa határolja. A falu belterületétől nyugatra nagy kiterjedésű mezőgazdasági területek találhatók, a község nyugati szomszédai, Hobol, Várad és Bürüs légvonalban is mintegy 5-6 kilométer távolságban fekszenek. Csak közúton közelíthető meg, a 6-os főútból Szigetvárnál kiágazó 58 107-es számú mellékúton helyezkedik el.'),
    ('Derecske', 'Az ország keleti részén helyezkedik el, a Hajdúságban, a megyeszékhely Debrecentől mintegy 22 kilométerre. A szomszédos települések: észak felől Sáránd, északkelet felől Hajdúbagos, kelet felől Konyár, délkelet felől Szentpéterszeg, délnyugat felől Berettyóújfalu, nyugat-délnyugat felől Földes, északnyugat felől pedig Hajdúszovát.'),
    ('Derekegyház', 'Szentestől 13, Hódmezővásárhelytől 26, Orosházától 24 kilométerre található. Szomszédai: észak felől Szentes Lapistó nevű külterületi városrésze, keleten Nagymágocs, délkeletről Székkutas, délen Hódmezővásárhely, délnyugaton Mindszent, nyugat felől Szegvár, északnyugatról pedig maga Szentes. Közigazgatási területének délnyugati szélén ágazik ki a 45-ösből a Mindszentre vezető 4523-as út.'),
    ('Deszk', 'Szegedtől délkeletre, a Bánság Magyarországon maradt területén, a torontáli háromszög Marosszög nevű északi csücskében helyezkedik el, Szőreg városrésztől mindössze 3 kilométer távolságra. Közigazgatási területének északi szélét a Maros folyása jelöli ki – azon túl abból az irányból Szeged keleti külterületeivel, Tápairét településrésszel határos –, további szomszédai északkelet felől – még ugyancsak a Maros túlsó partján – Maroslele, kelet felől Klárafalva, délkelet felől Kübekháza, délnyugat felől Újszentiván, nyugat felől pedig Szőreg.'),
    ('Detek', 'A Cserehát tájegység keleti részén fekszik, a Vasonca-patak völgyében, a megyeszékhely Miskolctól közúton kb. 40 kilométerre északkeletre. A közvetlenül határos települések: észak felől Beret, kelet felől Forró, délkelet felől Ináncs, dél felől Rásonysápberencs, nyugat felől pedig Selyeb. A legközelebbi város a kb. 15 kilométerre fekvő Encs. Neve valószínűleg magyar személynévi eredetű, amely név a szlávból került a magyarba.'),
    ('Detk', 'Gyöngyöstől keletre fekszik, a Keleti-Mátraalján, a Mátrai Erőmű két lignitbányája között. A közvetlenül határos települések: észak felől Domoszló, kelet felől Kápolna, délkelet felől Kompolt és Nagyút, dél-délnyugat felől Ludas, nyugat felől Halmajugra, északnyugat felől pedig Markaz. Északkelet felől Aldebrőhöz tartozó külterületekkel határos, de maga a település viszonylag távol esik tőle.'),
    ('Devecser', 'Első írásos említése a 14. századból származik, bár a térség már korábban is lakott volt. A település életében meghatározó szerepet játszottak a nemesi birtokosok, különösen a 18. században épült Esterházy-kastély, amely ma is a város egyik legfontosabb műemléke. A kastélyparkot és a régi épületeket ma is megcsodálhatják az ide látogatók. A város gazdasága hagyományosan a mezőgazdaságra épült, különösen a szőlő- és bortermelésre, amit a Somló-hegy kiváló adottságai nyújtottak.'),
    ('Dinnyeberki', 'Dinnyeberki nevét az oklevelek 1305-ben említették először Dinneberki néven, 1327-ben Dinnyeberki, 1328-ban Dennaberke módon írták. A település a Dinnyeberki nemesek birtoka volt. 1305-ben Viktorin végrendeletében testvéréről, Kornélról reá szállt dinnyeberki birtokrészeket Kornél feleségére Ilonára és annak leányára, Cristolra hagyja. 1542-ben készült adólajstromban is szerepelt neve Dinnyeberki néven.'),
    ('Diósd', 'Érd, Törökbálint és Budapest között helyezkedik el, a Tétényi-fennsík déli lejtőin. A domborpajzs vörös kerettel szegélyezett haránt irányban szelt vörös színű pályával. A bal alsó mező (heraldikai jobb oldal) kék, a jobb felső mező (heraldikai bal oldal) sárga színű. A heraldikai bal oldalon a kék mezőben a Szent Gellért kápolna stilizált képe, melynek külső kontúrvonala fehér, belső színezete sárga és barna.'),
    ('Diósjenő', 'Szomszédos települések: Nógrád, Nőtincs, Tolmács, Rétság, Berkenye, Borsosberény, Kemence. Diósjenő Jenő (vár) már a kőkor óta lakott hely lehetett, a környéken talált kőkorból származó leletek szerint. Római történetírók szerint 173-ban a diósjenői tónál ütköztek meg Marcus Aurelius (filozófusként is ismert) császár légiói a Pannóniát fenyegető barbárokkal (markomannok, kvádok), és megsemmisítő csapást mértek rájuk.'),
    ('Dióskál', 'Keszthelytől 23 kilométerre nyugatra, a Kis-Balaton mellett található. Sármelléktől 12, Zalakarostól 17, Hévíztől 19 kilométerre található a falu. Központján az Esztergályhorváti és Pacsa közti (a 7522-es utat és a 75-ös főutat összekötő) 7526-os út halad végig, a falun keresztül húzódó Bárándi-patak és mellékvizei völgyeiben. A település Pacsa, Zalaapáti Keszthely és Zalakaros irányából autóbuszon rendszeresen elérhető, és Zalaegerszegre is járnak járatok innen helyezkedik el.'),
    ('Diósviszló', 'A Villányi-hegység déli oldalán helyezkedik el, Harkánytól északnyugatra. A szomszédos települések: észak felől Szava, délkelet felől Márfa, dél felől Drávaszerdahely, délnyugat felől Rádfalva, északnyugat felől pedig Hegyszentmárton és Babarcszőlős. Az Ormánság keleti szélén elterülő település történelme visszanyúlik az őskorba. A mai értelemben vett állandó település – az eddigi adatok alapján –…'),
    ('Doba', 'A Somló északkeleti lábánál, Devecsertől 13 kilométerre északnyugatra található. Keleti szomszédjával, Oroszival egy szilárd burkolatú, de keskeny és nem túl jó minőségű önkormányzati út köti össze. Első híradás a településről: 1288: Doba (Csánki III. 228) A Doba településnév a vastag, kövér értelmű középkori magyar személynévből származik. A középkorban a település Kinizsi Pál, majd a 16. századtól egészen 1945-ig az Erdődy-család birtoka volt, régebben somló-vár, majd a jánosházai uradalomhoz tartozott.'),
    ('Doboz', 'A Kettős-Körös és Sebes-Körös által alkotott Körös menti síkon fekszik, a Kettős-Körös szanazugi összefolyásához közel, attól mintegy 5 kilométerre. Szomszédai: észak felől Tarhos, kelet felől Sarkad, dél felől Gyula, délnyugat felől Gerla (Békéscsaba), északnyugat felől pedig Békés. A hazai vasútvonalak elkerülik a települést, s a környék minden fontosabb vasútállomása aránylag messze esik tőle.'),
    ('Dobri', 'Dobri a Kerka völgyének jellegzetes települése, a kis folyó vízgyűjtőjéhez tartozik. Árvizei a területen élőknek régen sok gondot okoztak, néha még napjainkban is emlékezetessé tudnak válni. A dél-zalai dombvidék általában gyenge minőségű rossz vízgazdálkodású terület, mindez az egyik oka a táj sokat emlegetett szegénységének. A térség éghajlata nedvesebb és hűvösebb, mint az országos átlag.A magasabb területek az erdőgazdálkodásra, a völgyek és a lankás területek a nem túl hőigényes növénykultúrák termesztésére alkalmasak.'),
    ('Dobronhegy', 'A csonkahegyháti körjegyzőséghez tartozik, önálló önkormányzata van. A településtől délnyugatra emelkedik a Göcsej legmagasabb pontja, a Kandikó. A Bödei elágazás–Becsvölgye–Pórszombat úton fekszik, kiindulópontja a Milejszeg felé vezető bekötőútnak. A Kustánszeg és Becsvölgye felé tartó járatok mind érintik a falut. A település első említése 1271-ben Dabrua néven való.'),
    ('Domaháza', 'A falu a 2306-os út mentén Miskolctól kb. 70, Ózdtól kb. 17 kilométerre nyugatra fekszik. A település a 13. században jött létre, templomát 1332-ben említik először. Eredeti neve a Hangony-patak közeli forrása után Hangony-fő volt, mai nevét Domahidi János földbirtokosról kapta. A falu nem hódolt be a töröknek, részt vettek Eger várának védelmében, ezért 1517-ben több domaházi család nemesi címet kapott.'),
    ('Domaszék', 'A település a Dél-Alföldön fekszik, Szegedtől 11 kilométerre nyugatra. A szomszédos települések: dél felől Röszke, nyugat felől Mórahalom, északnyugat felől pedig Zákányszék és Bordány. Északi és keleti irányból a megyeszékhelyhez, Szegedhez tartozó területek határolják.'),
    ('Dombegyház', 'A szomszédos települések: észak felől Kevermes, északnyugat felől Kisdombegyház, dél-délkelet felől Battonya, Románia felől pedig déli irányból Kisvarjaspuszta, kelet felől pedig Nagyiratos. A település népességének változása: 2001-ben a település lakosságának 98%-a magyar, 2%-a egyéb (főleg cigány, román és szlovák) nemzetiségűnek vallotta magát. A 2011-es népszámlálás során a lakosok 86,6%-a magyarnak, 1,1% cigánynak, 0,2% németnek, 2,9% románnak, 0,2% szerbnek mondta magát (13% nem nyilatkozott.'),
    ('Dombiratos', 'Szomszédjai észak felől Nagykamarás, kelet felől Kevermes, dél felől Kisdombegyház és Magyardombegyház, nyugat felől pedig Kunágota. Lakott területén kelet-nyugati irányban végighúzódik a Kunágotát Lőkösháza térségével összekötő 4438-as út, csak ezen érhető el Kevermes és Kunágota felől is. Oklevelekben 1418-ban mint Belsőiratos, 1510-ben már Dombiratos néven szerepel.'),
    ('Dombrád', 'A Rétközben, a megye északnyugati szélén helyezkedik el, a Tisza mellett, a folyó bal parti oldalán. Különálló településrészei: Üdülőtelep, közvetlenül a folyó partján, a központtól 3 kilométerre északnyugatra, valamint Kistiszahát, a belvárostól 7 kilométerre nyugati irányban helyezkedik el.'),
    ('Domony', 'Különálló településrésze a déli határszéle közelében kialakult, dinamikusan fejlődő Domonyvölgy. Közúton csak egy öt számjegyű úton, a 21 115-ös számú mellékúton érhető el, Bag felől a 3-as főútról, vagy Iklad felől a 2108-as útról letérve. A sztrádáról a 39-es kilométerszelvénynél található Bag–Tura–Aszód-csomópontnál lehajtva közelíthető meg, a 3-as főútról pedig a bagi körforgalomban leágazva.'),
    ('Domoszló', 'A települést a Závoza-patak szeli ketté. A falu határában található az ország egyik legtisztább vízű, háborítatlan környezetű mesterséges horgászó tava, melyet a hegyekben eredő Berek-patak vize táplál. A falu a 2416-os és a 2418-as utak találkozásánál fekszik Budapesttől 97 kilométer-re, Gyöngyöstől 19 kilométer-re. Nevét a XI. szádban élő Domoszló (Damazlaus) hercegről kapta, aki a pécsváradi apátságnak ajándékozta Fegyvernek és Markaz birtokokat.'),
    ('Dormánd', 'Füzesabonytól déli szomszédságában fekszik, a várostól 4 kilométerre. A további szomszédos települések: kelet felől Mezőtárkány, dél felől Besenyőtelek, nyugat felől pedig Erdőtelek. Csak közúton érhető el, az M3-as autópályán, a 31-es és a 33-as főúton. A község határában rézkori csákányt találtak, a Csörsz-árok közelében késő bronzkori és szarmatakori sírok kerültek elő.'),
    ('Dorog', 'A Pilis és a Gerecse völgye már az újkőkor óta lakott hely. Itt haladt keresztül az a római hadi út, mely Aquincumot és a nyugati provinciákat kötötte össze, a város délkeleti határában a 4. századból származó római padlófűtéses villa romjait tárták fel. Nevét 1181-ben említette először oklevél Durugh formában, a török hódoltság idején elpusztult ősi falu a mai lakóterülettől délre feküdt, Ódorog néven ismert.'),
    ('Dorogháza', 'Közigazgatásilag a Dorogháza-Nemti-Szuha körzetbe tartozik. Simon fiai: Baksa, Tamás, Dénes, Detre, György és Simon a Rátót nemzetségbeli Roland nádor fiainak adták cserébe. Később azonban e cserét mégis megváltoztatták és pénzért vásárolták meg Kövesdet a Baksa nemzetségbeliek. 1296-ban Dorog birtokot még a Baksa nemzetségbeliek birtokának írták, 1332 és 1337-es pápai tizedjegyzékben Rabasháza (Dorokháza) néven említették. 1465-1479-ben Sirok várához tartozott, melyet tari György utód nélküli halála esetére Kompolthi János…'),
    ('Dozmat', 'Szombathelytől 8 kilométerre nyugatra fekszik, az Arany-patak jobb partján emelkedő dombon. A szomszédos települések: észak felől Bucsu, kelet felől Torony, délkelet felől Nárai, délnyugat felől Felsőcsatár, nyugat felől pedig Narda. Neve a délszláv drozg (= rigó), mások szerint a szláv druzba (= barátság) szóból alkotott személynévből ered. 1238-ban Druzmoth néven említik először.'),
    ('Drágszél', 'Magyarországon, az Alföld nyugati részén, Budapesttől 140 kilométerre délre, Kalocsa városától 10 kilométerre délkeletre található. A Duna 12 kilométerre nyugatra folyik Drágszéltől. Mindössze három települési szomszédja van: északkelet felől Homokmégy, dél felől Miske, északnyugat felől pedig Kalocsa.'),
    ('Drávacsehi', 'Legközelebbi szomszédai északról Drávaszerdahely és Kovácshida, délkelet felől Drávapalkonya, nyugatról Tésenfa, északnyugatról pedig Drávacsepely. A település lakott területe viszonylag távol, mintegy 3 kilométerre fekszik az országhatárt ezen a szakaszon több helyütt is kereszteződ Drávától, és így az országhatártól, de a falu közigazgatási területe egy rövid sávban lenyúlik egészen a folyóig, sőt egy egészen kis területen átnyúlik a túlpartra is, így tehát Drávacsehi is határfalunak tekinthető.'),
    ('Drávacsepely', 'Harkánytól nyugatra helyezkedik el, Rádfalva, Kémes és Drávacsehi között. A baranyai vár faluja volt. A tatárok elvonulása után a falut újjáépítették. A török hódoltság alatt is lakott maradt a falu. Katolikus lakosai ekkor református hitre tértek át. A falu a 18. században a Batthyány család siklósi uradalmához tartozott. Az egykézés miatt a református lakosság számát ma…'),
    ('Drávafok', 'A szomszédos települések: Bogdása, Markóc, Lakócsa és Teklafalu. A megyeszékhely, Pécs felől Szigetváron vagy Sellyén át közelíthető meg. Az írott források először 1257-ben említik Fukó néven, mai névalakja 1493-ból való. A neve a Dráva folyónév és a fok, magas vízállású folyóág vagy a tó vizét elvezető ér főnév összetétele. A településen a fokgazdálkodás volt jellemző.'),
    ('Drávagárdony', 'Barcstól délkeletre helyezkedik el, a Dráva közvetlen közelében, a déli országhatár mellett, Potony és Drávatamási között. Keresztülszeli a községet az EuroVelo nemzetközi kerékpárút-hálózat 13. számú, „Vasfüggöny” útvonalának horvát-magyar határ menti szakasza, amelynek a Drávatamási és Drávasztára közti 3. számú etapja érinti a falut. Érdekesség, hogy a térségben amúgy jobbára a Dráva töltésén vezető útvonal itt több kilométeren keresztül eltávolodik a folyótól, északi irányba.'),
    ('Drávaiványi', 'Az Ormánság nyugati részén helyezkedik el, Sellyétől mintegy 3,5 kilométerre délnyugatra. A további szomszédos települések: délkelet felől Sósvertike, dél felől Drávasztára, délnyugat felől Révfalu, nyugat felől Drávakeresztúr, északnyugat felől pedig Bogdása. Drávaiványi nevét a 14. században említik először az oklevelek. 1332-ben már mint plébániás helyet említik.'),
    ('Drávakeresztúr', 'Szigetvártól délre helyezkedik el, a Dráva folyó közelében. A környező települések: észak felől Markóc, északkelet felől Drávaiványi, kelet felől Drávasztára, délkelet felől Révfalu, nyugat felől pedig Felsőszentmárton helyezkedik el. Ugyanez az út köti össze nyugati szomszédjával, Felsőszentmártonnal is.'),
    ('Drávapiski', 'A szomszédos települések: északkelet felől Rádfalva, kelet felől Drávacsepely, dél felől Kémes, nyugat felől Adorjás, északnyugat felől pedig Kórós. Drávapiski nevét már 1177-ben említik a korabeli oklevelek Pyspeky néven, később pedig Pysky formában helyezkedik el.'),
    ('Drávaszabolcs', 'A szomszédos települések: észak felől Ipacsfa, kelet felől Gordisa, nyugat felől Drávapalkonya, északnyugat felől pedig Kovácshida. A határon túl Alsómiholjác (Donji Miholjac) az első horvátországi település. A terület már a bronzkorban is lakott hely volt, az itt talált régészeti leletek alapján. A település nevét 1216-ban már említették Zobolson alakban írva, majd 1395-ben Zabolch, 1478-ban Zabolcz formában írták.'),
    ('Drávaszerdahely', 'Nevének első része a közelében folyó Drávára, második része a szerdai napokon itt tartott vásárokra utal. Harkánytól nyugatra helyezkedik el, a közvetlen szomszédai kelet felől Kovácshida, nyugat felől Drávacsepely. Drávaszerdahely nevét az oklevelek már 1177-ben említették először, Zeredahel néven. 1177-ben az aradi prépostság kémesi uradalmának faluja volt. 1332-ben több változatában is említve volt.'),
    ('Drávasztára', 'A település Sellyétől délre, a horvát-magyar határ közelében fekszik, néhány száz méternyire a Drávától, így az Ormánság legdélebbi fekvésű települései közé tartozik. A falu határában húzódik, sőt a településközponton is áthalad az EuroVelo nemzetközi kerékpárút-hálózat 13. számú, „Vasfüggöny” útvonalának horvát-magyar határ menti szakasza, amelynek itt ér véget a Drávatamásitól induló 3. számú etapja, és itt kezdődik a Szaporcáig tartó 4. etap.'),
    ('Drávatamási', 'Barcstól délkeletre, majdnem közvetlenül a Dráva partján fekszik, közvetlenül a déli (magyar-horvát) országhatár mellett. A szomszédos települések a határ magyar oldalán: nyugat felől a ma már Barcshoz tartozó Drávapálfalva, észak felől Darány, északkelet felől Kastélyosdombó, kelet felől pedig Drávagárdony. Délen a legközelebbi település a Dráva túlpartján, szinte pontosan átellenben fekvő horvátországi Újgrác (Novi Gradac).'),
    ('Dubicsány', 'Kazincbarcika és Putnok között helyezkedik el, Miskolctól 26 kilométerre északnyugatra, Ózdtól 25 kilométerre északkeletre. A közvetlenül határos települések: észak felől Dövény, kelet felől Sajógalgóc, dél felől Sajóvelezd, nyugat felől pedig Putnok. Felszínét nagyobbrészt folyóvízi homok és kavics fedi. A település a 13. vagy a 14. században jött létre.'),
    ('Dudar', 'A település a Bakony keleti felében, Zirctől mintegy 7 kilométerre keletre fekszik, a várost Mórral összekötő 8216-os út mentén. Miután 1995-ben az utolsó helyi bányaüzemeket is bezárták, ezen a szakaszon megszűnt a személyforgalom, azóta csak alkalmi teherszállítás (leginkább bauxit és faanyag szállítása) folyik itt. András idejében Possessio Dudar néven, mint Csókakő várának tartozékát említi egy okleveles adat.'),
    ('Duka', 'A Balatontól mintegy 45 kilométerre északra fekszik, a 8-as és a 84-es főutak kereszteződése közelében. A közvetlenül határos települések: észak felől Kissomlyó, kelet felől Jánosháza, dél felől Keléd, délnyugat felől Bögöte, nyugat felől pedig Vashosszúfalu. Főutcájaként a 8436-os út húzódik rajta végig, központját az köti össze mindkét említett főúttal és Kissomlyóval is.'),
    ('Dunaalmás', 'A környék fontosabb települései közül Komárom 16, Tata 9, Almásfüzitő 4, a megyeszékhely Tatabánya pedig 17 kilométer távolságra található. A hagyomány szerint a település környékén hajdan nagy almafaerdők voltak, s e almaligetekről nevezték el a települést Almásnak. Dunaalmás és környéke már ősidők óta lakott hely, ahol bronz-, római-, népvándorláskori leletek kerültek elő.'),
    ('Dunabogdány', 'Távolsága: Budapesttől 35, Szentendrétől 18, Visegrádtól 5, Esztergomtól 30 kilométer. Szomszédos települések: Visegrád, Kisoroszi, Tahitótfalu és Pilisszentlászló. Dunabogdány határos a Duna–Ipoly Nemzeti Park [1] területével. A településen folytatott régészeti feltárások alapján arra lehet következtetni, hogy a mai Dunabogdány területét igen kedvező természeti adottságai miatt már az őskorban is lakták.'),
    ('Dunaegyháza', 'A Duna mentén, a bal parti oldalon elterülő Solti-síkon helyezkedik el. A folyam a községtől mintegy 1 kilométerre nyugatra húzódik. A tájegység névadója, Solt település északi, Apostag déli szomszédságában helyezkedik el, a bal parton nincs is más települési szomszédja. Közigazgatási területe azonban nyugat felől érintkezik még a túlsó parton fekvő Dunaföldvár és Baracs határszélével is.'),
    ('Dunafalva', 'A szomszéd települések: észak felől Báta, északkelet felől Szeremle, kelet felől Bátmonostor, délkelet felől Nagybaracska, dél és délnyugat felől a Mohácshoz tartozó Sárhát és Újmohács, nyugat felől pedig Bár és Dunaszekcső.'),
    ('Dunaharaszti', 'A térség történelmi emlékekben leggazdagabb városai közé tartozik. Budapesttől mintegy 20 kilométerre, délre, Kecskeméttől 70 kilométerre, északnyugatra található. Az Alföldön, a Csepeli-sík és a Pesti-hordalékkúpsíkság határán, a Ráckevei-Duna bal partján, a budapesti agglomeráció dél-pesti részén helyezkedik el. Közvetlenül határos Budapest XXIII. kerületével, a főváros belső kerületeitől mintegy 17 kilométerre helyezkedik el.'),
    ('Dunakeszi', 'A megye második legnépesebb települése Érd után helyezkedik el. A Duna túloldalán elhelyezkedő Budakalász várossal megosztva a „Dunakanyar kapuja”-ként is emlegetik. Dunakeszi a Duna bal partján, Budapesttől mintegy 15 kilométerre északra terül el. Dunakeszi az Alföld Duna menti síkság nevű középtájához tartozik, azon belül nagy része a Pesti-hordalékkúpsíkság, kisebb része a Vác–Pesti-Duna-völgy kistájak területén helyezkedik el.'),
    ('Dunakiliti', 'Dunakilitihez tartozik a mintegy 120 lelket számláló Tejfalusziget. A település 2010 óta a „Humanitárius település” címet viseli. 2015-ben a Magyarországi Falumegújítási Díj kiváló fokozatát nyerte el. 2015-ben 1. helyezett lett a „Virágos Magyarországért” versenyben, és így 2016-ban Dunakiliti képviseli a magyarországi falvakat az Entente Florale Europe rangos környezetszépítő versenyen.'),
    ('Dunapataj', 'Területén található a közkedvelt fürdő- és üdülőhely, a Szelidi-tó, illetve a tó déli oldalán kiépült Szelid településrész. A szomszédos települések: észak felől Harta, kelet felől Kiskőrös, délkelet felől Szakmár és Újtelek, délnyugat felől Géderlak, nyugat felől Ordas, északnyugat felől pedig a Duna túlsó partján fekvő Madocsa. Közigazgatási területe keleten pontszerűen érintkezik még Kecel, dél felől pedig egy-egy rövid szakaszon Uszód és Foktő határszélével is.'),
    ('Dunaremete', 'Dunaremete önálló a püski körjegyzőségben, a Szigetköz középső harmadában, a Duna jobb partján helyezkedik el. Mosonmagyaróvártól 13 kilométerre keletre, Győrtől 26 kilométerre északnyugatra fekszik. A múlt században hajókikötő is működött itt, vízállásjelentésben rendszeresen említik itt a Duna vízállását. A település neve a nyelvtudomány szerint a magyar „remete” főnévből keletkezett, míg a „Duna” előtag a folyam mellékére utal.'),
    ('Dunaszeg', 'Magyarország északnyugati részén, a Mosoni-Duna egyik kanyarulatában, Győrtől 12 kilométerre helyezkedik el. Önálló a Szigetköz keleti harmadában, a Mosoni-Duna bal partján, néhány kilométerre a Dunától helyezkedik el. A terület régebbi korokban is lakott volt. A hagyomány szerint a falu lakossága Huba vezér törzséből származik, első letelepedője egy Pata nevű személy volt, aki a mai Pataháza utca környékén épített kunyhót.'),
    ('Dunaszekcső', 'A Szekcső helynév a magyar szökik ige gyakorító képzős szökös származékának folyamatos melléknévi igenévből keletkezhetett, etimológiailag azonos lehet a szöcske (régi magyar nyelven szökcse) rovarnévvel. Valószínűnek látszik, hogy a középkorban volt egy Szekcső hangalakú és sebesen fodrozva haladó víz, sellő zuhatag, valamint gázló-féle jelentésű magyar földrajzi köznév és ez válhatott helynévvé.'),
    ('Dunaszentbenedek', 'A falu Dunapatajtól 10, Kalocsától 12 kilométerre fekszik. A környező településekkel naponta több buszjárat köti össze. A közeli Duna-hidak, a Tomori Pál híd (korábban Kalocsa–Paks Duna-híd), amely Paks és Foktő közigazgatási területeit köti össze, emellett a Beszédes József híd Dunaföldváron és a Szent László híd Szekszárdon is igénybe vehetők a Dunántúl irányában.'),
    ('Dunaszentgyörgy', 'A Duna jobb partján fekszik, Pakstól 10 kilométerre délre, Szekszárdtól 25 kilométerre északra. A közvetlenül határos települések: észak felől Paks, délkelet felől Gerjen, dél felől Fadd, nyugat felől pedig Tengelic. Kelet felől a legközelebbi település a Duna túloldalán fekvő Foktő, de a közigazgatási területeik nem érintkeznek. A történelem folyamán többféle néven említik a települést: Tolnaszentgyörgy, Magyarszentgyörgy, Ráczszentgyörgy és Dunaszentgyörgy.'),
    ('Dunaszentmiklós', 'A Gerecse hegység északnyugati részén, egy kicsi völgyben, körülbelül 200 méter tengerszint feletti magasságban fekszik. Tiszta időben néha a Bakony csúcsai is láthatók, Tata síkságára is jó a kilátás. Olyannyira dombos, hogy alig van sík területe. Az itt található és egymástól szakadékokkal elválasztott magaslatokat tájvédelmi körzetté nyilvánították, ám ezek közül is szigorúan védett rész Dunaszentmiklós közigazgatási területén található Nagy-Somlyó és a Lábas-hegy.'),
    ('Dunaszentpál', 'Horvátul két neve létezik a falunak. A horvátkimlei horvátok Sepalnak, a bezenyei horvátok Sempalnak nevezték. A szigetközi község lakóinak életét a folyó áradásai gyakran megkeserítették, ugyanakkor a rét- és legelőgazdálkodásnak kedvezett, sőt az árvízmentes térszíneken még növénytermesztéssel is foglalkoztak. Az árvizektől védett teraszokon már a honfoglalás óta éltek emberek.'),
    ('Dunasziget', 'A felső Szigetközben fekszik, Mosonmagyaróvártól 15 kilométer, Halászi és Dunakiliti szomszédságában. Több, a Duna túlsó partján fekvő település külterületi részeiből alakult ki a 20. században helyezkedik el. Központja az egykori Sérfenyősziget, további különálló településrészei: Doborgazsziget, Cikolasziget és Galambos. Az 1954-es nagy szigetközi árvíz idején minden községrész lakosságát ki kellett telepíteni, ezután a települést gyakorlatilag teljesen újraépítették.'),
    ('Dunatetétlen', 'A további közvetlen szomszédai: északkelet felől Fülöpszállás, kelet felől Soltszentimre, délkelet felől Akasztó, délnyugat felől pedig Harta. Vasúton a Kunszentmiklós-Tass–Dunapataj-vasútvonalon volt elérhető, 2007 óta azonban ezen a vasútvonalon nincs személyforgalom. Dunatetétlen kis település és csak néhány évtizede önálló község, a régmúltból kevés emlék és kevés dokumentum maradt fenn.'),
    ('Dunavarsány', 'Állandó lakosainak száma körülbelül 8800 fő. Magyarország középső részén, az Alföldön, a Csepeli-sík és a Pesti-hordalékkúpsíkság határán, a Ráckevei-Duna balparti oldalán helyezkedik el, Budapest déli határától mintegy 12 kilométerre délre, nagyjából átellenben a Csepel-szigeti Szigethalommal. A város a Duna ártéri talajára, legfőképp homoktalajra települt, tengerszint feletti magassága 100-115 méter.'),
    ('Dunavecse', 'A Pentele híd megépülésénél szempont volt, hogy Dunavecsének több száz éve bejáratott kikötője van. A folyó vecsei szakasza mintegy 4,5 kilométer hosszú. Belterülete hullámos felszínt mutat, legmagasabb pontja a Rózsadomb. Tengerszint feletti magassága 105 méter. A szomszédos települések: észak felől Szalkszentmárton, északkelet felől Kunszentmiklós, kelet felől Szabadszállás, délkelet felől Újsolt, dél felől Solt és Apostag, nyugat felől pedig, a folyó túlsó partján és a megyehatár túloldalán Dunaújváros.'),
    ('Dunaújváros', 'Magyarország egyik legmagasabb jövedelmű települése, jelentős gazdasági, kulturális és sportközpont, valamint egyetemváros. 5267 hektáros kiterjedésével Magyarország legkisebb közigazgatási területű megyei jogú városa. Az ókorban a területén feküdt a rómaiak Intercisa nevű fontos katonatelepülése. Pentelét, az újkortól jelentős mezővárost az 1950-es évektől fejlesztették iparvárossá.'),
    ('Dusnok', 'A falu a Kalocsai Sárköz egyik Vajas-menti települése, nagyjából félúton fekszik Baja és Kalocsa városok között. Budapesttől 135 kilométerre délre helyezkedik el, a Duna bal partján. A folyótól mintegy 5 kilométerre fekszik. A környék jellegzetes folyómenti táj, amelynek felszínét, termékeny földjeit, bőséges erdeit a Duna, a Vajas és az Örjeg vizei alakították ki.'),
    ('Dág', 'Dág a Gerecse és Pilis koszorúzta völgy keleti részén fekszik, Budapesttől 29, Esztergomtól 17, Dorogtól 8 kilométer távolságra helyezkedik el, nagyjából Szentendrével azonos földrajzi szélességen. Szomszédos települések: Csolnok, Leányvár, Pilisjászfalu, Úny, Máriahalom és Sárisáp. A települést három kiemelkedés fogja közre: a Károly-hegy, a Ló-hegy és a Templom-hegy.'),
    ('Dáka', 'Pápától délnyugatra, Kéttornyúlak és Nagyalásony közt fekvő település. Dáka és környéke már a bronzkorban is lakott hely volt, az itt előkerült régészeti leletek tanúsága szerint. Nevét az oklevelek 1320-ban említették először Dalka néven helyezkedik el. A település a 14. században a Hathalmy család, a 17. században pedig a Bottka család birtoka volt.'),
    ('Dámóc', 'A Bodrogköz magyarországi részének északkeleti csücskében helyezkedik el, közvetlenül a szlovák határ mellett, a megyeszékhely Miskolctól közúton mintegy 110, Sárospataktól 50 kilométerre keletre. A határon túl a legközelebbi települések a szlovákiai Perbenyik (Pribeník), Kisdobra (Dobrá) és Bély (Biel). A legközelebbi város pedig Tiszacsernyő (Čierna nad Tisou).'),
    ('Dánszentmiklós', 'Budapesttől, Szolnoktól és Kecskeméttől is egyaránt mintegy 60 kilométerre fekszik. Cegléd (30 kilométer) kistérségéhez tartozó település, aktív tagja a Dél-Pest megyei Településfejlesztési Társulásnak. A község első írásos említése 1324-ből származik. Területén több Árpád- korban létezett falu nyomát is megtalálták. Neve Dán (Dány) és Szent Miklós összetételéből keletkezett.'),
    ('Dány', 'Gödöllőtől és Hatvantól kb. 22 kilométer-re, Budapest határától kb. 25 kilométer-re keletre fekszik. Földrajzi elhelyezkedését tekintve az Alföld és az Északi-középhegység találkozásánál, a Gödöllői-dombság és a Tápió-Galga-Zagyva hordalékkúp-síkság határán található. A falu határában csörgedező patakok a közeli Hajta-patakhoz csatlakozva a Zagyva vízgyűjtőjét képezik.'),
    ('Dávod', 'A régi neve többféle alakban fordul elő: Daut, Dauch, Dawoth, Davotháza. A községet először egy adományozás kapcsán említik. Az 1089-1090 körül keletkezett oklevél tanúsága szerint Dávid herceg – I. Dávid dux-ban olvasható: „5 szolga családot, három eke földet, öt halászóhelyet…'),
    ('Dédestapolcsány', 'A Bükk-vidék területén fekszik, Miskolctól kb. 30 kilométerre északnyugatra. Csak közúton közelíthető meg: Vadna vagy Nagyvisnyó felől a 2506-os, Miskolc-Mályinka felől a 2513-as, Nekézseny felől a 2518-as úton, Kazincbarcika-Tardona felől pedig a 25 127-es számú mellékúton helyezkedik el. Dédes neve a magyar Dedus személynévből keletkezett, melyet mint személynevet 1221-ben, majd 1230-ban említenek a források.'),
    ('Dég', 'Nyugodt környezetével és gazdag kulturális örökségével Dég a múlt és a természet szerelmeseinek paradicsoma. Természetföldrajzilag a terület a Mezőföldhöz tartozik. A szűkebb kistáj Dégi-süllyedék néven ismert. Kiterjedése kb. 5 km². A nagytáj jellegzetes formái (löszvölgyek, dombok, patakok, tavak), növényzet és állatvilág itt megtalálható. Egy része – a kastélypark és környéke – megyei értékű természetvédelmi terület.'),
    ('Délegyháza', 'Délegyháza a fővárostól délre, kb. 30 kilométer távolságra található. Északról Dunavarsány, délről Kiskunlacháza, nyugatról Majosháza, keletről Bugyi község határolja. A település a Kiskunsági Nemzeti Park, az Ócsai Tájvédelmi Körzet és a Ráckevei-Duna közvetlen közelében fekszik. A község területén 12 db kavicsbányató található mintegy 300 ha vízfelülettel, amely fürdésre, horgászásra és különféle vízi sportokra alkalmas.'),
    ('Dénesfa', 'Éghajlata a táj jellegének megfelelő, a Répce mellett különleges mikroklíma alakult ki, ahol az örökzöldek is otthonosak. A Répce egykori árterén, a község belterületén, a 18. század utolsó harmadában kezdték kialakítani a már védett parkot. Szomszédai: észak felől Cirák, északkelet felől Beled, dél felől Csánig, délnyugat felől Répceszemere, nyugat felől pedig Iván helyezkedik el.'),
    ('Dévaványa', 'Dévaványa területének éghajlata mérsékelten meleg, száraz, kontinentális jellegű. Az éves napsütéses órák száma 2000 óra körüli. Dévaványa évi középhőmérséklete 10,3-10,4 °C, az évi abszolút hőmérsékleti maximumok adatok átlaga 34,1-34,4 °C, a minimumoké -16,7 °C. Dévaványát szélsőséges hőmérsékleti ingadozás jellemzi. Az évi 540-570 milliméternyi lehullott csapadék mennyiség eloszlása egyenetlen.'),
    ('Dóc', 'Szegedtől 25 kilométerre északra helyezkedik el, a Tisza jobb partján, de a folyótól mintegy 4 kilométerre nyugatra. Szomszédai: észak felől Baks, északkelet felől Mindszent, kelet felől Mártély és Hódmezővásárhely (mindhárom utóbbi a folyó túlpartján), dél felől Sándorfalva, nyugat felől Balástya, északnyugat felől pedig Ópusztaszer. Kiss Lajos 1988-ban megjelent Földrajzi nevek etimológiai szótára szerint a név valószínűleg szláv eredetű.'),
    ('Döbröce', 'Polgármesteri hivatala Sümegcsehin székel. Nevét a horvát drbra (völgy, szakadék) jelentésű szóból kapta. Az első emlék a település létezésére IV. László idejéből valók. Újabb említése 1416-ból mint Enyere település szomszédja való. A 16. század második felében a töröktől menekülő lakosság elhagyta a települést. Az amúgy is kis lakosságú település teljesen elnéptelenedett, 1613-ban is csak egyetlen negyedtelkes lakott portáját írták össze.'),
    ('Döbrököz', 'A település környéke már a bronzkorban is lakott hely volt, a falu határában található ún. Tüszküs-hegy környékén őskori leletek kerültek elő. Az első földvárat az Apor, vagy a Szák nemzetség építette, amit egy 1309-ben kelt oklevél bizonyít. Százharminc évvel később a vár a Szerecsen-família birtokába került. A legutolsó családfő – János – halála után annak özvegye, szekcsői Herceg Katalin Werbőczy Istvánhoz ment feleségül.'),
    ('Döbrönte', 'Neve személynévi eredetű, a szláv Dobrete személynévből származik. Döbrönte és környéke már a római korban is lakott hely volt. Nevét az oklevelek 1330-ban említették először, Debrenthe alakban helyezkedik el. A település a középkorban a Himfy család birtokai közé tartozott. A falu fölötti várat is az e családból való Himfy Benedek bán, Nagy Lajos király kedvelt hadvezére emeltette 1367-ben, aki döbröntei uradalma területére a királytól várépítési jogot kapott.'),
    ('Döbörhegy', 'A Kemenesháton, Körmendtől mintegy 13 kilométerre délkeletre fekszik. Környező települések: Szarvaskend, Döröske és Gersekarát. A kis település első okleveles említése 1538-ból származik. Feltehetőleg a falu már sokkal régebb óta létezett. A kettős identitások miatt a végösszeg nagyobb lehet 100%-nál).'),
    ('Döge', 'A szomszédos települések: északkelet felől Fényeslitke, dél felől Kisvárda, délnyugat felől Kékcse, északnyugat felől pedig Szabolcsveresmart. A környék fontosabb települései közül Kisvárda 2, Szabolcsveresmart 11, Komoró 7,5, Fényeslitke 5, Tuzsér pedig 12 kilométer távolságra található. Döge Árpád-kori település.'),
    ('Dömsöd', 'Szomszédos települése északon Kiskunlacháza, keleten Apaj, délen Tass, a Ráckevei-Duna túloldalán pedig nyugaton Makád, északnyugaton Szigetbecse. A Csepeli-síkon elhelyezkedő községet nyugatról a Ráckevei-Duna határolja, emiatt a térség egyik meghatározó fürdő- és horgászparadicsomává nőtte ki magát, gyakran a „Stégek városaként” emlegetik. Dömsöd környékén már a legrégibb időkben is kiváló gyümölcsöt termeltek.'),
    ('Dömös', 'Budapesttől 45, Esztergomtól 16, Visegrádtól 5 kilométer távolságban helyezkedik el. A településen a 11-es számú (Budapest-Visegrád-Esztergom) főközlekedési út halad át. Hajóúton Nagymarossal és Szobbal is összeköttetésben van. Ez a kedvező fekvésű vidék a legősibb időktől kezdve megtelepedésre csábította az embert. Az emberi település legkorábbi nyoma a község északkeleti részén az őskőkorszakból ismert.'),
    ('Dör', 'A Kisalföldet – benne Dör község határát is – az Alpokból jövő folyók töltötték fel a magukkal görgetett hordalékkal. A település átlagos tengerszint feletti magassága 114-117 méter. A régi mocsarak helyén ma korszerűen művelt szántók, legelők, kaszálók sorakoznak. A Fertő–Hanság Nemzeti Park, melynek egyik területrésze a község határának keleti széléig nyúlik, sok mindent megőrzött a környék sajátos növény- és állatvilágából.'),
    ('Dörgicse', 'Balatonakalitól körülbelül 5 kilométerre északnyugatra helyezkedik el, a Balaton-felvidék középső, Balatonfüred és Badacsony közti szakaszára jellemző, a tóparti hegysor mögött kialakult márgás alapkőzetű medencék egyikében, amit a település után Dörgicsei-medencének neveznek. Több, korábban különálló, mára már többé-kevésbé egybeépült településrészből áll, ezeket a Balatonakali-Balatonszőlős között húzódó 7338-as út köti össze egymással és a környék távolabbi településeivel.'),
    ('Döröske', 'Döröske a Kemeneshát Rábára tekintő peremén fekszik, Körmendtől keletre 12 kilométerre, 180-244 méter közötti tengerszint feletti magasságban. Központján a Molnaszecsőd-Katafa közti 7445-ös út húzódik végig. A környező települések: Molnaszecsőd, Magyarszecsőd, Döbörhegy, Szarvaskend, Nagymákfa és Gersekarát. Éghajlata kiegyensúlyozott, szélsőségektől mentes.'),
    ('Dötk', 'A Zala folyó mellett található, Pakodtól délre. A lakosok 64%-a római katolikusnak vallotta magát (28% nem nyilatkozott). 2022-ben a lakosság 84,1%-a vallotta magát magyarnak, 11,4% németnek (4,5% nem nyilatkozott). Vallásuk szerint 31,8% volt római katolikus, 13,6% felekezeten kívüli (54,5% nem válaszolt).'),
    ('Dövény', 'A környező települések: észak felől Zubogy, északkelet felől Felsőkelecsény, délkelet felől Jákfalva (2 kilométer), dél felől Sajókaza és Sajógalgóc, délnyugat felől Putnok, északnyugat felől pedig Alsószuha (5 kilométer). A legközelebbi városok: Rudabánya (kb. 15 kilométer) és Kazincbarcika (kb. 20 kilométer). Csak közúton érhető el, Jákfalva vagy Alsószuha érintésével, a 2605-ös úton.'),
    ('Ebergőc', 'Soprontól 25 kilométerre keletre, Kapuvártól 20 kilométerre nyugatra helyezkedik el. Aránylag kis közigazgatási területtel bíró község, mindössze két közvetlen szomszédja van: nyugat felől Nagylózs, délkelet felől Röjtökmuzsaj településsel határos, a többi égtáj felől pedig az előbbiek valamelyikéhez tartozó lakatlan külterületek határolják. Ma ismert első okleveles említése 1343-ból való „Eburgheuch” írásmóddal.'),
    ('Ebes', 'A további szomszédos települések, településrészek: észak felől a Debrecenhez tartozó Ondód, délkelet felől Mikepércs, északnyugat felől pedig Nagyhegyes. A Váradi regestrum említi először a település nevét 1271-ben Ebey alakban helyezkedik el. Valószínűnek látszik, hogy a pecérek, a királyi, királynéi vagy hercegi udvarház, fejedelmi, hercegségi vadászataihoz tenyésztettek itt vadászkutyákat, agarakat. 1440-ben a Szepesi család birtokába került Ebesfalva tíz másik…'),
    ('Ecseg', 'A Novohrad-Nógrád UNESCO Globális Geopark települése. Pásztótól nyugatra, a Cserhát déli lábánál található, a Szuha-patak és a Kozárdi-patak összefolyásánál. A közvetlenül határos települések: észak felől Alsótold, északkelet felől Kozárd, kelet felől Pásztó, dél felől Csécse, nyugat felől Buják, északnyugat felől pedig Cserhátszentiván. Csak közúton érhető el, Pásztó felől a 2126-os, Kozárd, illetve Csécse érintésével pedig a 2128-as úton.'),
    ('Ecsegfalva', 'Szomszédai: északkelet felől Bucsa, kelet felől Kertészsziget, dél felől Dévaványa, délnyugat felől Túrkeve, északnyugat felől pedig Kisújszállás. Meglehetősen kevés híja van annak, hogy közigazgatási területei nem érintkeznek észak felől még Karcag határszélével is. A községen végighúzódik, nagyjából északnyugat-délkeleti irányban a Kisújszállás-Körösladány közti 4205-ös út, közúton csak ezen érhető el a két végponti település irányából.'),
    ('Ecseny', 'Domborzatilag erősen tagolt észak–déli irányú völgyben terül el. A kis lélekszám ellenére nagy kiterjedéssel bír, 13 kilométeres úthálózattal rendelkezik, amelynek mintegy 50%-a földút. Ecseny neve először III. Béla 1193-as okiratában szerepel. A török dúlástól elnéptelenedett falu betelepítése evangélikus svábokkal Mária Terézia idején kezdődött meg. 1784 körül a tolnai és baranyai sváb településekből költöztek át evangélikus családok.'),
    ('Ecser', 'Területe régóta lakott, régészeti feltárások során kelták, szarmaták és rómaiak nyomaira bukkantak. A török uralom alatt elnéptelenedett, utána többségében szlovákokkal telepítették be, napjainkban is rendelkezik szlovák kisebbséggel. Nemzetközileg az Ecseri lakodalmas révén ismert.'),
    ('Ecséd', 'A Mátra lábánál fekszik, Hatvantól körülbelül 13 kilométerre északkeletre. Jelentősebb magaslata az Öreghegy, vízfolyása az Ágói-patak. Természeti adottságai révén sok erdő található a külterületeken, amely az 1930-as éveket követően sajnos, megritkult. A külterületek nagysága 7121 hold, többsége mezőgazdasági terület, a délnyugati fekvésű területeken pedig különböző kultúrnövények, valamint gyümölcsök termesztése folyik.'),
    ('Edelény', 'A település legfőbb nevezetessége a L''Huillier-Coburg-kastély, hazánk egyik legnagyobb barokk kastélya, amely impozáns építészeti megoldásaival és gyönyörű freskóival vonzza a látogatókat. Edelény emellett a környék gazdasági és közlekedési központja, valamint a helyi hagyományok és természeti szépségek révén népszerű a turisták körében. A város barátságos hangulatával és pezsgő kulturális életével ideális hely egy kellemes kirándulásra helyezkedik el.'),
    ('Edve', 'Magyarország északnyugati részén, Kapuvártól 21 kilométerre délre helyezkedik el. Termőföldje jó minőségű, sokoldalú mezőgazdasági hasznosításra alkalmas. A település határában római kori kőkoporsót találtak, elképzelhető, hogy már ekkor lakott hely volt. 1264-ből maradt fenn első írásos említése „Edw” alakban.'),
    ('Eger', 'Eger Észak-Magyarországon, az Eger-patak völgyében, a Bükk-vidék délnyugati szélén helyezkedik el. Eger jelentős oktatási és kulturális központ, itt található Magyarország egyik legnagyobb bazilikája, az egri főszékesegyház, számos más híres műemlékkel és múzeummal is rendelkezik, melyek közül kiemelkedő az egri vár. Eger nevű város volt a mai Csehország nyugati területén, mai neve Cheb, valószínűleg vidékéről települtek át Egercsehi lakói Nagy Károly frank uralkodó hódítása elől.'),
    ('Egeralja', 'A szomszédos települések: észak felől Adorjánháza, északkelet felől Nemesszalók, dél felől Csögle, nyugat felől pedig Celldömölk. Kis híja van annak, hogy közigazgatási területe nem érintkezik kelet felől még Dabrony határszélével is. Adorjánházával mára gyakorlatilag teljesen összenőtt. Csak közúton közelíthető meg, a 8413-as úton, amely nagyjából dél-északi irányban húzódik végig a központján.'),
    ('Egeraracsa', 'Egeraracsa a Zalai-dombság délkeleti felén terül el, egy festői szépségű völgykatlanban. A települést a Kis-Balatonba tartó Bárándi-patak választja ketté. Központján az Esztergályhorváti és Pacsa közti (a 7522-es utat és a 75-ös főutat összekötő) 7526-os út halad végig, közúton ebből a két irányból érhető el. Autóbuszok indulnak Zalaegerszegre, Keszthelyre és Zalakarosra helyezkedik el.'),
    ('Egerbakta', 'A közvetlenül határos települések: észak felől Bátor, északkelet felől Szarvaskő, kelet felől Felnémet (Eger része), délkelet felől Eger, dél felől Egerszalók, délnyugat felől Egerszólát, nyugat felől pedig Sirok. Északi szomszédjával a 2413-as út köti össze. A legkorábbi írásos emlék a faluról 1261-ből származik. 1295-ben villa Bacha alakban írva említették.'),
    ('Egerbocs', 'A közvetlenül határos települések: észak felől Egercsehi, északkelet felől Mikófalva, kelet felől Mónosbél, délkelet felől Szarvaskő, dél felől Bátor, délnyugat felől Hevesaranyos, nyugat felől Fedémes, északnyugat felől pedig Szúcs. Egerből indulva a legegyszerűbb ez utóbbi útvonalat követni. Az egerbocsi elágazást Szarvaskő után körülbelül 7 kilométerrel érjük el.'),
    ('Egercsehi', 'Közelében ered a Villó-patak. Természetes növényzetét cseres tölgyesek, bükkösök alkotják. A falu jellege szerint részben patak menti, részben út menti település, a községtől keletre dombon álló templommal, északi részén kúriával és tőle különállóan elterülő bányateleppel. Egercsehit 1285-ben említi először egy oklevél terra Cheh alakban, a Baksa nemzetség birtokában, és ezen a néven maradt egészen 1903-ig.'),
    ('Egerfarmos', 'A közvetlen szomszédos települések: észak felől Mezőszemere és Mezőkövesd, kelet felől Egerlövő, délkelet felől Poroszló, nyugat felől pedig Mezőtárkány. Dél felől a település határszéle Besenyőtelekhez tartozó külterületekkel érintkezik, de ezen községgel épp csak ennyire határos. Közúton két útvonalon érhető el: a 3-as főútból Szihalomnál kiágazó 33 102-es számú mellékúton, illetve Mezőtárkány központja felől, egy számozatlan önkormányzati úton.'),
    ('Egerlövő', 'Az Egri-Bükkalja és a Tisza közti ártéren, sík területen helyezkedik el, Miskolctól mintegy 50 kilométerre, Mezőkövesdtől 11 kilométerre délre. A települést 1221-ben a Váradi regestrumban említik először, Luen alakban helyezkedik el. A községet székely lövészek alapíthatták. Környéke a bronzkorban is lakott lehetett, erre utalnak a 19. században talált leletek: hamvvedrek, díszes cserepek. 1984-ben miskolci régészek az ún.'),
    ('Egerszalók', 'A településtől északra a Laskó-patak felduzzasztásával létrehozott, 130 hektáros víztározó és horgásztó, délre pedig gyógyfürdő, szálloda, kemping miatt turisztikai célpont. Határszélét északon érinti még a 24 128-as út is. Szalók a honfoglalás óta lakott hely volt, a Szalók nemzetség ősi birtoka.'),
    ('Egerszólát', 'A Bükkalján, a 24 128-as úton Egertől 12 kilométer-re nyugatra, a Rábca-patak völgyében, a Szóláti-patak két partján helyezkedik el. Külterületeit érinti a 2416-os út is. Első írásos említése 1248-ből (Zowlat), illetve 1332-ből való (Zolouth). Az egri vár ostroma (1552) után elnéptelenedett. A 2011-es népszámlálás során a lakosok 87,2%-a magyarnak, 2,1% cigánynak, 0,6% románnak, 0,2% szerbnek mondta magát (12,8% nem nyilatkozott.'),
    ('Egervár', 'A településen polgárőrség működik. A zalai Sárvíz mellett fekszik. Különálló településrésze Dénesfa, a belterület északi részén helyezkedik el. A megyeszékhely Zalaegerszeg északi szomszédságában helyezkedik el, a város központjátől 11 kilométerre. A további határos települések: észak felől Gősfa, kelet felől Vasboldogasszony, délkelet felől Zalaszentlőrinc, dél-délkelet felől Zalaszentiván, délnyugat felől Nagypáli, északnyugat felől pedig Lakhegy.'),
    ('Egerág', 'Németül Egerág neve Egrad. Horvátul két alakot használnak: Egrag (szemelyiek elnevezése) ill. a Jegrag (lothárdiak elnevezése). Pécstől délkeletre fekszik. A szomszédos települések: észak felől Kozármisleny, északkelet felől Szemely és Lothárd, kelet felől Peterd, délkelet felől Kisherend, dél felől Vokány, délnyugat felől Szőkéd, északnyugat felől pedig Pécsudvard.'),
    ('Egyek', 'Népesebb különálló településrészei: Félhalom, a központjától 2 kilométerre délnyugatra, Telekháza 4 kilométerre északkeletre, valamint Ohat, légvonalban körülbelül 8, közúton 9-10 kilométerre keletre helyezkedik el.'),
    ('Egyházasdengeleg', 'A községet a Bér-patak szeli át. A felszínen elsősorban üledékek találhatók: homok és agyag. A közvetlenül határos települések: északkelet felől Kisbágyon, kelet felől Palotás, délkelet felől Héhalom, délnyugat felől Erdőtarcsa, nyugat felől Vanyarc, északnyugat felől pedig Szirák. Pásztóról, Apcról, Hatvanból, Budapestről. Gödöllőről és Szirákról naponta több autóbuszjárattal is elérhető.'),
    ('Egyházasfalu', 'A korábbi Egyházasfalu, Dasztifalu és Kisgógánfa községek 1933-ban egyesültek e néven, majd 1950-ben Keresztényt is hozzácsatolták. A Kisalföld nyugati szélén fekszik. Felszíni vizeit a Metőc-patak gyűjti össze. A szomszédos települések: észak felől Völcsej, északkelet felől Lövő és Nemeskér, kelet felől Újkér, dél felől Tormásliget, délnyugat felől Csepreg és Szakony, nyugat felől Gyalóka, északnyugat felől pedig Sopronhorpács.'),
    ('Egyházasgerge', 'A Novohrad-Nógrád UNESCO Globális Geopark települése. Salgótarjántól 20 kilométerre északra fekszik, a Karancs északi lejtőjén. A közvetlenül határos települések kelet felől Karancskeszi, dél felől Piliny, nyugat felől pedig Mihálygerge. Északon a határa egybeeik az államhatárral, a legközelebbi település abban az irányban a szlovákiai Romhánypuszta (Lipovany).'),
    ('Egyházasharaszti', 'A falu neve is arra utal, hogy már nagyon korán volt temploma, a haraszt pedig tölgyerdőre utal. Már a bronzkorban is lakott település volt, 1294-es iratok alapján fontos helynek mondják, ahól hadiút haladt át. A régi magyarok által lakott település a török időkben is lakott maradt, 1840-ben már 600 lakosa volt és 1837-től van iskolája. Így egy nagyszabású, az idegenforgalmat is vonzó termálprogram körvonalazódik…'),
    ('Egyházashetye', 'Itt született és tizenhárom éves koráig itt élt Berzsenyi Dániel. Kemenesalján, Celldömölktől délre, Kissomlyó, Köcsk és Jánosháza közt fekszik. A többutcás, soros beépítésű, szalagtelkes községet több mint háromszázan lakják. Nevének eredeteként a hetes számot, illetve a hegye szó zöngétlen hetye változatát említik. Az utóbbit erősítheti első írásos említése: Hege (1338).'),
    ('Egyházashollós', 'A helység egyediséget a kedvező földrajzi fekvés, azaz Ausztria közelsége és a tiszta, nyugodt környezet adja. A település nyugaton a körmendi és szentgotthárdi kistérség mellett terül el, északon a szombathelyi, keleten a vasvári, délen a zalaegerszegi és az őriszentpéteri kistérség szomszédja. A szomszédos települések: észak felől Nemesrempehollós, kelet felől Rábahídvég, délkelet felől Kismákfa, dél felől Nagymákfa [közigazgatásilag mindkét utóbbi község Vasvárhoz tartozik], nyugat felől pedig Molnaszecsőd.'),
    ('Egyházaskesző', 'Pápától mintegy 15 kilométerre északnyugatra fekszik, a tőle északra húzódó Rába és a délkeleti határában folyó Marcal között (GPS: N47, 24, 980 E17, 19, 630). A szomszédos települések: észak felől Várkesző, északkelet felől Marcaltő, délkelet felől Nemesgörzsöny, délnyugat felől Magyargencs, nyugat felől Kemenesszentpéter, északnyugat felől pedig Rábasebes és Szany.'),
    ('Egyházaskozár', 'A kis 800 lelkes Árpád kori település már a honfoglalás kora óta lakott, templomos hely volt, mire nevéből is következtetni lehet. A falu első lakosai valószínűleg a honfoglaló magyarsággal ide érkezett kazár (kozár) segédcsapatok e helyen letelepedett tagjai lehettek. Az első írásos emlék 1058-ból származik. A középkorban több néven is szerepelt, mint: Kozár, Nagy-Kozár, Felsew-Kozár, földesurai is változtak ez idő alatt.'),
    ('Egyházasrádóc', 'Három, korábban önálló község, Kissároslak, Egyházasrádóc és Rádóckisújfalu egyesítésével jött létre. Körmendtől 8 kilométerre északra fekszik. A szomszédos települések: észak felől Kisunyom, északkelet felől Sorokpolány, kelet felől Nemesrempehollós, délkelet felől Molnaszecsőd, nyugat felől Rádóckölked, északnyugat felől pedig Ják. Dél felől a két legközelebbi település Körmend városa, illetve Magyarszecsőd, de közigazgatási területe egyikével sem határos, mert elválasztja azoktól egy Rádóckölkedhez tartozó keskeny földsáv.'),
    ('Elek', 'A régió és a megye keleti részén található, Békéscsabától 25, Gyulától 12 kilométerre, a román határ közelében. A szomszédos települések: észak felől Gyula, kelet felől, a jelenlegi országhatár túloldalán Ottlaka (Grǎniceri), dél felől Lőkösháza, délnyugat felől Nagykamarás, nyugat felől pedig Kétegyháza. Természetföldrajzilag az Alföld Körös–Maros köze középtájának Békési-hát nevű kistájához tartozik.'),
    ('Ellend', 'Keletre a „Németrétek”, – nyugatra az egykori pusztához tartozó „Borsós” dűlő található. A földosztásig ez a terület ellendi puszta néven az „Egyetemi-alap”-hoz tartozott, itt, az egykori major helyén ma jelentős lótenyésztés folyik. A községet kettészelő „Gyöngyös-patak” egykor négy vízimalmot hajtott. Ezek közül a falu előtti „Noch–malom” az 1800-as években még őrölt, épülete ma is áll, mint családi ház.'),
    ('Előszállás', 'Valószínűleg kun alapítású, a 17. század második felétől a második világháború utáni évekig a ciszterci rend tulajdona. Itt működött a központja a rend előszállási uradalmának, amely a mai Alsószentiván, Baracs, Daruszentmiklós, Hantos, Mezőfalva, Nagykarácsony, Nagyvenyim községeket foglalta magába, és a két világháború között az ország legjobban jövedelmező nagybirtokainak egyike volt. 1928 óta önálló község.'),
    ('Emőd', 'A Borsodi-Mezőségen, Miskolctól 22 kilométerre délre helyezkedik el. A városban egyesülő Kulcsár-völgyi-patak és a Nyéki-patak mentén a pincesor már a Miskolci-Bükkalja délkeleti peremének szelíd lankáin sorakozik. A közvetlenül határos települések: észak felől Nyékládháza, északkelet felől Hejőkeresztúr, kelet felől Hejőszalonta, délkelet felől Hejőpapi és Igrici, dél felől Mezőcsát, délnyugat felől Csincse, nyugat felől Vatta, északnyugat felől pedig Harsány és Bükkaranyos.'),
    ('Encs', 'A Hernád folyó völgyében fekszik, a megyeszékhely Miskolctól körülbelül 40 kilométerre északkeletre. Nyugatról a Cserehát, keletről a Zempléni-hegység határolja. Különálló településrészei: Abaújdevecser, a központtól mintegy 1,5-2 kilométerre északnyugatra, illetve Fügöd, hasonló távolságra délre helyezkedik el. A közvetlen szomszédos települések: észak felől Szalaszend, északkelet felől Méra, kelet felől Abaújkér és Gibárt, délkelet felől Hernádbűd és Pere, nyugat felől Forró, északnyugat felől pedig Fancsal és Fáj.'),
    ('Encsencs', 'A környező települések közül Nyírbátor 12, Nyíradony 21,5, Mátészalka 28,5, Nyírbéltek 4, Nagykálló pedig 30,5 kilométer távolságra található. A közvetlen szomszédos települések: északkelet felől Piricse, délkelet felől Nyírbéltek, délnyugat felől Nyírlugos, nyugat felől Nyírmihálydi és Nyírgelse, északnyugat felől pedig Nyírbogát. Zsáktelepülésnek tekinthető, mert közúton csak egy útvonalon közelíthető meg, a Nyírbátor-Nyírbéltek-Nyírábrány közt húzódó 4906-os útból Piricse déli széle közelében kiágazó 49 131-es számú mellékúton.'),
    ('Endrefalva', 'A Novohrad-Nógrád UNESCO Globális Geopark részét képező Endrefalva Szécsény északkeleti szomszédságában helyezkedik el, a várostól 7 kilométerre. Különálló településrésze Babat, mely a központjától mintegy 1 kilométerre keletre fekszik. A települést érintő helyközi autóbuszvonalakː 1010, 3072, 3080, 3081, 3082. Endrefalva eredetileg a Záh nemzetség ősi birtokai közé tartozott, mely Záh Felicián merénylete következtében a koronára szállt, majd I.'),
    ('Endrőc', 'A faluba vezető út egyben a főutca is, amely a központban, egy szakaszon ténylegesen is a Fő utca nevet viseli, majd kelet felé továbbhaladva a Dózsa György utca nevet veszi fel. Az út vonalvezetése csaknem pontosan nyugat-kelet irányú. Északnyugati és déli szomszédjai, Teklafalu és Drávafok legegyszerűbben a sellyei országúton érhetők el a településről, délkeleti szomszédjába, Marócsára pedig földutak vezetnek.'),
    ('Enese', 'Magyarország északnyugati részén, a Rábaköz–Tóköz–Hanság találkozásánál, Győrtől 17 kilométerre nyugatra, Csornától 14 kilométerre keletre helyezkedik el. A közvetlenül határos települések: észak felől Mosonszentmiklós, kelet felől Rábapatona, dél felől Rábacsécsény, nyugat felől Kóny, északnyugat felől pedig Bezi és Győrsövényház. A község 6000 éves múlttal büszkélkedhet. 2002 nyarán Langó Péter régész végzett ásatást Enese területén honfoglalás kori leletek után kutatva.'),
    ('Enying', 'A város nevének első írásos említése 1138-ból származik, a dömösi prépostság birtokösszeírásában helyezkedik el. Puszta személynévből keletkezett magyar névadással. Az alapjául szolgáló személynév német eredetű lehetett, Enig vagy Ening. A település története során több nemesi család birtokában volt, köztük a Török családéban a 15. században, majd a Batthyány családéban a 18. század második felétől.'),
    ('Eperjes', 'Szomszédai észak felől Szarvas, északkelet felől Csabacsűd, kelet felől Nagyszénás és Gádoros, dél felől Árpádhalom, nyugat felől Fábiánsebestyén, északnyugat felől pedig Szentes Cserebökény nevű külterületi városrésze. A falutól északra találhatók a cserebökényi puszták, melyek a Körös–Maros Nemzeti Park védett területei közé tartoznak. Közúton Fábiánsebestyén és Gádoros felől közelíthető meg, mindkét irányból a 4403-as úton helyezkedik el.'),
    ('Eperjeske', 'A közvetlen szomszédos települések a határ magyar oldalán: észak felől Tiszaszentmárton, kelet felől Lónya, délkelet felől Tiszamogyorós, délnyugat felől Mándok, nyugat felől pedig Tiszabezdéd. A térség fontosabb települései közül Mándok és Tiszaszentmárton 4-4, Záhony és Tuzsér 12-12, Mezőladány pedig 10 kilométer távolságra található. Központja közúton csak Mándok vagy Tiszaszentmárton érintésével érhető el, mindkét irányból a 4115-ös úton.'),
    ('Eplény', 'Legismertebb nevezetessége a Síaréna Vibe Park, amely télen síelési lehetőséget, nyáron pedig libegőzést és túrázást kínál. Az Öreg-Bakonyban helyezkedik el, a megyeszékhely Veszprém északi szomszédságában, a város központjától 14 kilométerre. Zirctől 7 kilométerre délre helyezkedik el. Veszprémen kívül mindössze három községgel határos közvetlenül: észak felől Olaszfalu a szomszédja, délkelet felől Hajmáskér, nyugat felől pedig Lókút.'),
    ('Epöl', 'A legközelebbi települések: nyugatra Bajna 3 (közúton 4) kilométerre, északnyugatra Nagysáp mintegy 5 (közúton 9) kilométerre, északkeletre Sárisáp 5 (közúton 15) kilométerre, délkeletre Máriahalom 6 (közúton 10) kilométerre, délre Gyermely és Szomor egyaránt 6,5 (közúton 11) kilométerre helyezkedik el. Epöl már a magyarok honfoglalása előtt is lakott település volt, amit a falu határában előkerült régészeti leletek is bizonyítanak.'),
    ('Ercsi', 'A Mezőföldhöz tartozó Érd–Ercsi-hátság déli részén fekszik. A szomszédos települések: észak felől Százhalombatta, kelet felől Szigetcsép és Szigetújfalu, délkelet felől Ráckeve (utóbbi három a Csepel-szigeten), dél felől Iváncsa, délnyugat felől Beloiannisz és Besnyő, nyugat felől pedig Baracska és Ráckeresztúr. Ercsit a Dunán ingázó komp köti össze Szigetújfaluval.'),
    ('Erdőbénye', 'Egyike Tokaj-Hegyalja legrégebbi településeinek, hajdani mezővárosainak. A honfoglalástól kezdődően magyar faluként tartják számon. Hegyekkel körülvett, őslénytani érdekességekben és ásványokban gazdag területen helyezkedik el. A település a Mulató-hegy köré épült, a Zempléni-hegység és az Alföld találkozásánál, az Aranyosi-völgy kapujában fekszik.'),
    ('Erdőhorváti', 'A Zempléni-hegységben, ezen belül is a Tokaji borvidéken, a Tolcsva-patak völgyében helyezkedik el, a megyeszékhely Miskolctól körülbelül 70 kilométerre északkeletre, a legközelebbi várostól, Sárospataktól 20 kilométerre nyugatra. A szomszédos települések: észak felől Háromhuta, kelet felől Komlóska, dél felől Tolcsva, délnyugat felől Olaszliszka és Erdőbénye, nyugat felől Baskó, északnyugat felől pedig Mogyoróska.'),
    ('Erdőkertes', 'A fővárostól északkeletre, a gödöllői dombvidéken található. Az Északi-középhegység nagytájban, a Nyugati-Cserháthoz kapcsolódó Gödöllői-dombság kistájban terül el. Mindössze három olyan település van, amellyel közvetlenül határos, ezek: északkelet felől Vácegres, dél felől Veresegyház, északnyugat felől pedig Őrbottyán. (Utóbbi kettővel szinte teljesen összeépült.) Erdőkertes környékének legmagasabb pontjai a 278 méter magas Szadai-hegy és a 345 méter magas Margita.'),
    ('Erdőkövesd', 'Közúton 2305-ös és a 23 113-as út találkozásánál. Eger 34, Salgótarján 30, Ózd 34 kilométer. A szlovák határátkelő (Cered-Tajti /Tachty) 12 kilométer-re van. Erdőkövesd kis palóc falu (670 lakos) a Tarna-patak jobb partján települt. Észak és kelet felől erdős dombok övezik, biztosítva a jó levegőt, a szép természeti környezetet, a túrázás, lovaglás, vadászat lehetőségét.'),
    ('Erdőkürt', 'A közvetlenül határos települések: észak felől Vanyarc, kelet felől Erdőtarcsa, délkelet felől Kálló, délnyugat felől Galgamácsa, nyugat felől pedig Acsa. A falut elsőként a 13. század végén említik oklevelek, Kywth vagy Kyrth néven helyezkedik el. Neve arra utal, hogy a terület eredetileg a honfoglalás kori Kürt-törzs szálláshelye volt. Az 1500-as évek közepén török fennhatóság alá került, de nem néptelenedett el, mint sok más település, lakóinak száma az ez idő tájt keletkezett…'),
    ('Erdősmárok', 'A Dunától nyugatra, a Geresdi-dombság déli lábainál fekszik. A szomszédos települések: észak felől Geresdlak, északkelet felől Himesháza, kelet felől Székelyszabar, délkelet felől Kisnyárád, délnyugat felől Liptód, északnyugat felől pedig Maráza. Az Árpád-kori település Erdősmárok nevét 1261-ben említették először az oklevelek Mark néven helyezkedik el.'),
    ('Erdőtarcsa', 'Budapesttől mintegy 60 kilométerre északkeletre fekszik, a Cserhát kisebb-nagyobb magaslatai között, a Tarcsai-patak (vagy Ilka-patak) völgyében, mely a belterületétől északra ered, Kiar-puszta közelében. A környék két legmagasabb pontja (Erdőtarcsa két oldalán) a Daróc-hegy és a Kopasz-hegy. A község közepén egy eliszaposodott melegforrás tör fel, aminek vize a téli hónapokban sem fagy be.'),
    ('Erdőtelek', 'A Hevesi-síkon fekszik. A legközelebbi szomszédja Tenk, mintegy 4 kilométerre délre helyezkedik el. A legközelebbi város a 14 kilométerre fekvő Heves. A közvetlenül határos települések: északkelet felől Füzesabony, kelet felől Dormánd és Besenyőtelek, délkelet felől Átány és Tenk, dél felől Heves, nyugat felől Tarnabod, északnyugat felől pedig Kál.'),
    ('Erk', 'A közvetlenül szomszédos települések: északkelet felől Zaránk, kelet felől Tarnaméra, délkelet felől Jászszentandrás, dél felől Tarnaörs, északnyugat felől pedig Visznek. Külterületeinek egy jelentősebb része – közel 4,5 négyzetkilométernyi terület, a központjától délkeletre – a Hevesi Füves Puszták Tájvédelmi Körzet részeként természetvédelmi oltalom alá esik.'),
    ('Erzsébet', 'Az Erzsébet női név, amely a héber Eliseba (אֶלִישֶׁבֵע Elíseva, úgynevezett „erős” alakja אֶלִישָׁבַע Elísáva) névből származik, ennek nyugati Elisabeth alakjából fejlődött ki. Fejlődési sora: Elsábet→Elsébet→Erzsébet. Ennek eredeti jelentése: „Isten az én esküm”, „Isten megesküdött” vagy „Isten a teljesség”, „Isten a tökéletesség”.'),
    ('Eszteregnye', 'A Zalai-dombság délnyugati részén fekszik, az Egerszeg–Letenyei-dombság területén, alig 10 kilométerre a horvát határtól. A közvetlenül határos települések: északkelet felől Magyarszerdahely és Homokkomárom, kelet felől Sormás, dél felől Szepetnek, nyugat felől Rigyác, északnyugat felől pedig Oltárc. Közigazgatási határa északon pontszerűen érintkezik még Bocska délnyugati határszélével is.'),
    ('Esztergom', 'A mai értelemben vett város 1895-ben Esztergom szabad királyi város és a szomszédos Érseki Víziváros, Szenttamás illetve Szentgyörgymező települések egyesítésével jött létre. A rendszerváltástól 2012-ig az Alkotmánybíróság, 1997-től a Duna–Ipoly Nemzeti Park székhelye. Az esztergomi érsek székvárosaként a római katolikus egyház magyarországi központja.'),
    ('Esztergályhorváti', 'A Zalai-dombság délkeleti részén, a Zala folyótól nyugatra, a Kis-Balaton északi szájánál található. A település Keszthely, Nagykanizsa, Pacsa és Zalakaros irányából autóbuszon rendszeresen elérhető, de Zalaegerszegre is járnak járatok innen helyezkedik el. A település területe a 9. században a Zalavár környékén kialakult szláv fejedelemség része volt, így itt is kialakultak ebben az időben kisebb telepek.'),
    ('Esztár', 'A legközelebbi szomszédai: kelet felől Pocsaj, délnyugat felől pedig Hencida. A közúti tömegközlekedést a Volánbusz autóbuszai biztosítják. Esztár és környéke már ősidők óta lakott hely. Határában sok kőkor-i és római kor-i lelet került napvilágra helyezkedik el. Tőle nyugatra halad el a szarmaták által 324 és 337 között épített…'),
    ('Ete', 'A közvetlenül határos települések: észak felől Csép, kelet és délkelet felől Császár, dél felől Vérteskethely, délnyugat felől Kisbér, nyugat felől Ászár, északnyugat felől pedig Tárkány. Területe patakvölgyekkel taglalt hullámos síkság. Határában folyik északnyugati irányban a Csépi-ér, mely Nagyigmánd közelében a Concó-patakba torkollik. Felszíni kőzetei: agyagmárgával kevert laza üledékek…'),
    ('Etes', 'A Novohrad-Nógrád UNESCO Globális Geopark települése. Csak közúton érhető el, a Ságújfalu és Karancsalja között húzódó, a 22-es főutat és a 2206-os utat összekötő, bő 7 kilométer hosszú, 22 109-es számú mellékúton. A falu központi része egy völgykatlanban húzódik, amit kellemes hajlású dombok és kisebb hegyek szegélyeznek. Keleti és déli irányból ide csatlakoznak a szénbányász múlt emlékeit őrző bányatelepek, melyek a település szerves részét képezik.Etes több egymástól elkülönülő lakott részből: a Faluból, illetve Öregetesből.'),
    ('Etyek', 'Elsősorban nemzetközi hírű bortermeléséről és az erre épülő turizmusáról ismert, de itt működik Európa egyik legjelentősebb filmstúdiója, a Korda Studios is. Közelebbi települések: Biatorbágy, Alcsútdoboz, Herceghalom. A község neve eredetileg az Ete személynévből származik.'),
    ('Fadd', 'Ez a lap Fadd településről szól. A FADD fehérjéről itt olvashatsz: FADD. Hozzá tartozik a népszerű üdülőhely, Dombori is. A nagyközség két nagy földrajzi tájegység, a A Dél-Mezőföld és a Tolnai-Sárköz határán, Szekszárdtól északra, a faddi Holt-Duna partján helyezkedik el. A Duna fő ága a 19. század nagy folyamszabályozása nyomán került távolabb (mintegy 5 kilométerre) a településtől.'),
    ('Fajsz', 'Két különálló településrészből áll, melyek közül a nagyobb, északi részben helyezkedik el a központja is. A déli rész jobbára lakatlan, ott inkább csak ártéri erdők és mezőgazdasági területek találhatók. A közvetlenül határos települések: észak-északkelet felől Bátya, kelet felől Miske, délkelet felől Dusnok, délnyugat felől Bogyiszló, északnyugat felől pedig Fadd.'),
    ('Fancsal', 'A Cserehát keleti részén fekszik, Miskolctól mintegy 40 kilométerre északkeletre. Közúton a 3-as főúton érhető el a legegyszerűbben, amelyről Forrónál kell letérni északnyugat felé a 2625-ös útra. A legközelebbi települések: Baktakék 3 és Forró 5 kilométerre, a legközelebbi város, Encs mintegy 6 kilométerre található. Neve magyar személynévből keletkezett, amelynek jelentése fondorlatos, kancsal.'),
    ('Farkasgyepű', 'Az Öreg-Bakony nyugati szélének erdei között bújik meg, a megyeszékhely Veszprémtől és Pápától is közel azonos távolságra. A közvetlenül határos települések: északkelet felől Németbánya, kelet felől Szentgál, délkelet felől Csehbánya, dél felől Kislőd, délnyugat felől Magyarpolány, északnyugat felől pedig Bakonyjákó. Csak közúton közelíthető meg, a Városlődtől Pápán át Győrig vezető 83-as főúton, mely a központján is végighalad.'),
    ('Farkaslyuk', 'Az Upponyi-hegységtől nyugatra, az Ózdi-patak völgyfőjében, medencedombsági területen épült fel. Miskolctól közúton 50 kilométerre nyugatra, Ózdtól 6 kilométerre délkeletre helyezkedik el. Környékén jelentős az erdők aránya. A legközelebbi település egyben a legközelebbi város is: a községtől északra fekvő Ózd legutolsó házai mindössze néhány száz méterre állnak Farkaslyuk északi részének utcáitól helyezkedik el.'),
    ('Farmos', 'A közvetlenül határos települések: észak felől Jászberény, délkelet felől Tápiószele, délnyugat felől Tápiószentmárton, északnyugat felől pedig Nagykáta. A település és környéke az itt talált régészeti leletek szerint már a honfoglalás előtt lakott volt. Első ismert birtokosa 1311-ben Csák Máté volt, majd halála után a Káta nemzetség birtokába került.'),
    ('Farád', 'Nevének eredete a Rábaköz északi, a Hanság mocsaraival határos helyzetére utal: itt volt ugyanis a földművelésre alkalmas vidék vége (fara), amitől északra a mocsárvilág következett. Magyarország északnyugati, a Dunántúl északi részén fekszik, a Kisalföldön, ezen belül pedig a Rábaközben, Csornától 3-4 kilométerre nyugatra. Nyugati határában a Farkas-árok, északi külterületei közt pedig a Kapuvár-Bősárkány-csatorna húzódik.'),
    ('Fazekasboda', 'Pécsváradtól délkeletre fekszik, a Geresdi-dombság nyugati lábainál. A szomszédos települések: észak felől Lovászhetény, északkelet felől Erdősmecske, kelet felől Geresdlak, dél felől Kékesd, délnyugat felől Erzsébet, északnyugat felől pedig Nagypall (Lovászheténnyel, Erdősmecskével és Erzsébettel nincs közvetlen közúti kapcsolata). Nevének Fazekas előtagja a falu fazekas hagyományaira, boda utótagja a régi buda=kemence szó boda nevű változatából ered.'),
    ('Fedémes', 'Az Északi-középhegységben, ezen belül a Heves–Borsodi-dombságban fekszik, a Fedémesi-patak mellett, Pétervásárától kb. 12 kilométerre keletre. A település első írásos említése 1261-ben történik. Neve ekkor Fedemus volt. A falu az egri püspökség birtoka volt. A 16. században a szarvaskői várhoz tartozott. A török hódoltság alatt elnéptelenedett, csak a 17. század első éveiben népesült be újra.'),
    ('Fegyvernek', 'A Nagykunság nyugati peremvidékén fekszik, a Fegyverneki-Holt-Tisza mentén. Közigazgatási területének egy keskeny, alig egy kilométernyi széles sávja érintkezik az élő Tiszával is. Szomszédai: északkelet felől a Kendereshez tartozó Bánhalma (9,5 kilométerre), kelet felől Kenderes (10,5 kilométerre), dél felől Örményes (6 kilométerre), délnyugat felől Törökszentmiklós (12 kilométerre), nyugat felől Nagykörű (7 kilométerre, de a Tisza túlpartján), északnyugat felől pedig Tiszabő (7,5 kilométerre).'),
    ('Fehérgyarmat', 'A szomszédos települések: észak felől Kisar [bár a két település területe nem érintkezik], északkelet felől Nagyar, kelet felől Penyige, délkelet felől Cégénydányád, délnyugat felől Fülpösdaróc és Géberjén, nyugat felől Tunyogmatolcs és Nábrád. A környék fontosabb települései közül Tiszabecs 28,5, Penyige 4, Tarpa 11, Tunyogmatolcs…'),
    ('Fehértó', 'A falu közelében található tó vize feltűnően fehér volt, innen a név: Fehértó. Magyarország északnyugati részén, Csornától 16 kilométerre északkeletre helyezkedik el. A településen, annak főutcájaként a 8503-as út húzódik végig, kelet-nyugati irányban, közúton csak ezen közelíthető meg, Győrsövényház, Bezi és Markotabödöge felől is. A településről az első említést 1368-ból olvashatjuk.'),
    ('Fehérvárcsurgó', 'Bodajk 2 kilométer, Székesfehérvár 13 kilométer, Mór 11 kilométer, Magyaralmás 4 kilométer, Bakonykúti 9 kilométer, Isztimér 8 kilométer, Kincsesbánya 2 kilométer távolságra található. Egyrészt a Móri-árok sík részére, valamint a Bakony utolsó keleti vonulataira épült község. A település 193 hektáros központi belterülete sík területen fekszik, átlagosan 130-160 méteres tengerszint feletti magasságban.'),
    ('Feked', 'A megye északkeleti részén fekszik, a Karasica-patak szelíd dombokkal övezett völgyében, ahol a Kelet-Mecsek lankái a Geresdi-dombságba simulnak. A szomszédos települések: észak felől Ófalu, kelet felől Véménd, délkelet felől Szebény, dél felől Szűr, délnyugat felől Geresdlak, nyugat felől pedig Erdősmecske. Nevét Feketh alakban egy Árpád-kori okmányban, majd az 1372-ben kelt irat szerint, a cikádori cisztercita apátság birtokai között is említik.'),
    ('Feketeerdő', 'Dunakilitivel alkotja a Dunakiliti-Feketeerdő Körjegyzőséget. A község a Mosoni-Duna partján fekszik, a Szigetköz északnyugati részén, Mosonmagyaróvártól 8 kilométerre északra, Pozsonytól 35 kilométerre dél-délkeletre. Egy 1274 körüli oklevélben említik először. (Fekete Erdeu, Fekethewedeu néven írták le) Várbirtokként szerepel Hunyadi-kori tulajdonosai: a Szent-györgyi és Bazini grófok.'),
    ('Felcsút', 'A Vértes peremvidékén, a Váli-víz jobb partján helyezkedik el. Településrésze Szúnyogpuszta, mely Felcsút centrumától 2 kilométerre fekszik nyugati irányban. 2011-es adatok szerint Szúnyogpuszta lakónépessége 62 fő, a lakások száma 15 volt. Szúnyogpusztán az őstermelő Pák-To Kft. telephelye üzemel. A Pák-To Kft. étkezési tyúktojás termelésével és értékesítésével foglalkozik.'),
    ('Feldebrő', 'A Tarna völgyében, a Mátra hegység délkeleti lábainál fekszik. A közvetlen szomszédos települések: észak felől Verpelét, északkelet felől Egerszólát, kelet felől Demjén, délkelet felől Tófalu, dél felől Aldebrő, nyugat felől pedig Vécs. Délkelet felől a legközelebbi település Kerecsend, északnyugat felől pedig Kisnána, de területe (kevés híján) egyikével sem határos.'),
    ('Felgyő', 'Csongrádtól délre, a Tisza jobb partján fekvő település. További szomszédai: kelet felől Szentes, délkelet felől Szegvár (mindkettő a folyó túlpartján), dél felől Csanytelek, délnyugat felől Tömörkény, nyugat felől pedig Gátér. Felgyő (Győ) Árpád-kori település. Nevét már 1075-ben említette oklevél Gehgi néven helyezkedik el. Hercegi birtok volt, melyet 1108 után Álmos herceg a dömösi prépostságnak adott 63 saját szolgával, és mindegyiknek a saját földjével.'),
    ('Felpéc', 'A Sokorói-dombság nyugati vonulatának délnyugati oldalát 4–6 méteres lösz borítja. A táj felszínét az erősen formálódó völgyek, a völgyoldalakba vágódó árkok, lösz mélyutak, szakadékok határozzák meg. A falutól északra futóhomok-dűnék sorakoznak, melyeket a legutóbbi jégkorszak szelei fújtak ki a Bakony-ér medencéjéből a pleisztocén végén helyezkedik el.'),
    ('Felsőberecki', 'A Bodrogközben, közvetlenül a Bodrog bal partján fekszik, Miskolctól közúton mintegy 90 kilométerre keletre. A szomszédos települések: délkelet felől Karos (légvonalban 6, közúton mintegy 10 kilométerre), dél felől Alsóberecki (2 kilométerre), nyugat felől pedig Sátoraljaújhely (10 kilométerre). Északkeleti irányból szlovákiai, Bodrogszöghöz (Klin nad Bodrogom) és Bodrogszerdahelyhez (Streda nad Bodrogom) tartozó területek határolják.'),
    ('Felsőcsatár', 'Szombathelytől nyugatra fekszik, légvonalban mintegy 14, közúton nagyjából 18 kilométer távolságra, a Pinka bal partján, közvetlenül az osztrák határ mellett. A szomszédos települések: észak felől Narda, északkelet felől Dozmat, kelet felől Nárai, dél felől pedig Vaskeresztes. Nyugat felől a legközelebbi település a már Ausztriához tartozó Pinkaóvár (Burg), de valószínűleg határos – északnyugat felől – Csémmel (Schandorf) és talán – délnyugati irányból – Várújfaluval (Woppendof) is.'),
    ('Felsődobsza', 'A Hernád völgyében fekszik, a megyeszékhely Miskolctól közúton 35 kilométerre északkeletre. Teljes lakott területe és közigazgatási területének túlnyomó része a folyó bal parti oldalán helyezkedik el, de egy kisebb, körülbelül 2,5 km²-nyi területrésze a túlparti oldalon található. Itt található a Hernád kis számú magyarországi szigeteinek egyike, a Bárczay-sziget, ahol egy kisebb vízerőmű is létesült, a folyásirány szerint bal oldali folyóágban.'),
    ('Felsőegerszeg', 'A Baranya-csatorna völgye melletti lankák között bújik meg, Sásdtól alig másfél kilométerre délkeletre. A Hegyhát viszonylag kedvező adottságokkal rendelkező kistelepülései közé tartozik. Neve az égerfa név és a szeglet, zug jelentésű szög összetételéből adódik. A felső előtag megkülönböztető szerepű. A dombokra Y alakban felkúszó falu már az őskorban is lakott volt, amit késő bronzkori, vaskori feltárt sírok is tanúsítanak.'),
    ('Felsőgagy', 'A legközelebbi települések: Csenyéte 2 és Alsógagy 3 kilométerre helyezkedik el. A legközelebbi város, Encs 20 kilométerre található. A Gagy szó ismeretlen eredetű, talán személynévre vezethető vissza, azaz a környék egy korai birtokosára utal. A szó magyarázatának eddigi próbálkozásai mind sikertelenek voltak. A magyar helynévadás szokásai szerint az alsó előtag egy másik helyhez képest délebbre fekvő, vagy egy folyóvíz melletti település esetén a folyásirány szerint…'),
    ('Felsőjánosfa', 'A falu a Zala folyó völgyében, annak bal partja közelében, a Zalába torkolló Szentjakabi-patak két partján, Őriszentpétertől 12 kilométerre keletre, Zalalövőtől 3 kilométerre nyugatra, Őrimagyarósdtól 5 kilométerre délre fekszik. Külterületei az Őrségi Nemzeti Park részét képező, védett területek. 1402-ben Januspanfalva…'),
    ('Felsőkelecsény', 'Kazincbarcikától 15 kilométerre északra fekszik, a megyeszékhely Miskolctól közúton 30 kilométerre északnyugatra. A környező települések: északkelet felől Rudabánya (4 kilométer), dél felől Felsőnyárád (4 kilométer), délnyugat felől Jákfalva, nyugat felől Dövény, északnyugat felől pedig Zubogy (3 kilométer). A legközelebbi város Rudabánya. Csak közúton közelíthető meg, Felsőnyárád vagy Zubogy érintésével a 2603-as, Rudabánya felől pedig a 2608-as úton helyezkedik el.'),
    ('Felsőlajos', 'A települést kerékpárút is összeköti a szomszédos Lajosmizsével. Felsőlajos újonnan keletkezett község, amely az alföldi tanyavilágból nőtt ki. A mai község területe a történelmi időkben Lajosmizse külterülete volt. A település kezdetben Közös néven szerepelt a térképeken. 1929-ben egy amerikából hazatelepült gazdálkodó a mai Felsőlajoson telepedett le, ahol faiskolát hozott létre.'),
    ('Felsőmarác', 'Az Őrség és a Kemeneshát tájegységek határvidékén fekszik, Körmendtől néhány kilométerre délnyugatra. Nevének utótagja a ''morva emberek'' jelentésű, szláv moravci szóból ered, míg az előtagot a környék másik hasonló nevet viselő településtől, a muravidéki Alsómaráctól (ma Moravske Toplice) való megkülönböztetés végett kapta. Első okleveles említése Morouch néven 1258-ból ismert (Alsómarácot is ugyanezzel a névvel említik 1366-ban).'),
    ('Felsőmocsolád', 'Az észak-déli irányban viszonylag hosszan elnyúló község Kaposvártól mintegy 30, Mernyétől 6 kilométerre északra helyezkedik el. A közvetlenül határos települések: észak felől Fiad, északkelet felől Kisbárapáti, délkelet felől Ecseny, dél felől Mernye, délnyugat felől Mernyeszentmiklós, nyugat felől Polány, északnyugat felől pedig Gamás. Délkeleti szomszédja, Ecseny a belterületéről kiágazó 65 128-as számú mellékúton érhető el.'),
    ('Felsőnyárád', 'Kazincbarcikától 12 kilométere, a megyeszékhely Miskolctól közúton 30 kilométerre északnyugatra fekszik, a Szuha- és a Csörgő-patak találkozásánál. A környező települések közül Kurityán 2, Jákfalva 3, Felsőkelecsény pedig 4 kilométerre található. A legközelebbi város a 8 kilométerre fekvő Rudabánya. Csak közúton érhető el, Sajókaza vagy Felsőkelecsény érintésével a 2603-as, Kurityán vagy Jákfalva felől pedig a 2605-ös úton.'),
    ('Felsőnyék', 'Magyar település, melynek történetét Magyarország történelméhez hasonlóan: a népvándorlás, a királyok, nemesek csetepatéi alakítják, az egyházak helybeli története, az itteni népszokások, a település épületeinek építészeti stílusa mind ezt adják vissza. A falu több országos hírű tudósnak, így Bakonyi István történésznek, Jánosi Gyula bencés szerzetesnek, illetve európai hírű egyházalapítónak, Méliusz Juhász Péternek a szülőhelye.'),
    ('Felsőnána', 'Zsáktelepülés, közúton csak a 65-ös főútból Kéty északi határában kiágazó 63 125-ös számú mellékúton érhető el. A középkorban virágzó falu volt Királynána néven, amely azután elpusztult. A török korban, 1563-ban 18 adófizetője volt. A 17. század utolsó harmadában néptelenedett el. Egy 1847-ben keletkezett leírás szerint megtalálhatók a középkori templomának maradványai.'),
    ('Felsőpakony', 'Kedvező infrastrukturális kapcsolatokkal rendelkező település. A község a repülőtér légi folyosójától távol esik. Felsőpakony közúton két irányból közelíthető meg: vagy Gyál, illetve az M0 Gyál–Pestszentimre-csomópontja, vagy Ócsa, illetve az M5-ös Ócsa–Üllő-csomópontja felől. Felsőpakony területén állami közútnak…'),
    ('Felsőpetény', 'Régi magyar település, de lakóinak jelentős része szlovák származású. A Cserhát dombvidéke öleli körbe, a település környezetét nagyban meghatározza a cserháti táj jellege. Első írásos említése 1247-ből való (Pethen), akkor még Alsópeténnyel közös falut alkotnak, a két település csak a 14. században vált ketté. Az Árpád-korban a Csák nemzetségbeli Ugrin birtoka volt, akit IV.'),
    ('Felsőpáhok', 'A településen polgárőrség működik. Észak felől Nemesbük és Karmacs, keletről Hévíz, délkeletről Alsópáhok, délről (az Alsópáhokhoz tartozó) Nemesboldogasszonyfa, délnyugatról Szentgyörgyvár, nyugatról Bókaháza, északnyugatról pedig Zalacsány határolja. Felsőpáhok Alsópáhok társtelepüléseként a 18. század végén jelent meg. 1872-ben épült római katolikus temploma.'),
    ('Felsőrajk', 'A község az egykori Kanizsa vizének nevezett mocsaras, ingoványos területre épült, amely a Principális-csatorna megépítésével vált teljesen lakhatóvá. A Felsőrajk keleti részén lévő dombvonulat – az Öreghegy – kiválóan alkalmas növénytermesztésre, valamint szőlőtermelésre helyezkedik el. A szomszédos településen, a Felsőrajktól 3 kilométerre nyugatra fekvő Pötrétén tőzegkitermelés folyik, az ilyen műveletekkel érintett területek a későbbiek során vízzel telnek fel, és jó lehetőséget kínálnak a horgászat szerelmeseinek.'),
    ('Felsőregmec', 'Közvetlenül a szlovák határ mellett fekszik, a határ magyar oldalán csak három települési szomszédja van: dél felől Alsóregmec, délnyugat felől Mikóháza, nyugat felől pedig Vilyvitány. A határ túloldalán a legközelebbi települések: északnyugat felől Kázmér (Kazimír), észak felől Alsómihályi (Michaľany). kelet felől pedig Legenye (Luhyňa). Regmec (Red(e)mec) már az 1200-as években létezett, temploma is ekkor épült.'),
    ('Felsőszenterzsébet', 'A megye egyik legkisebb települése. Felsőszenterzsébet a Kerka és Lendva között fekvő dombságon található. Közúton Kerkakutas irányából érhető el, a 7416-os útból kiágazó 74 133-as úton, Alsószenterzsébet érintésével. A településre hétköznap két busz tér be Csesztreg, illetve Lenti felől. Hétvégén nincs tömegközlekedési összeköttetése. A kis falut 1334-ben említik először Scentelsebethként, 1375-ben Zenthelsebeth 1501-ben Felsewzenthersebeth.'),
    ('Felsőszentiván', 'A szomszédos települések: észak felől Borota, északkelet felől Jánoshalma, kelet felől Tataháza és Mátételke, dél felől Bácsbokod, nyugat felől Csávoly, északnyugat felől pedig Rém. Területe délnyugat felől egy rövid szakaszon még Baja határszélével is érintkezik. Felsőszentiván Árpád-kori település. Nevét 1198-ban említette először oklevél Scentii alakban írva.'),
    ('Felsőszentmárton', 'A Drávától északra, mintegy 1,5 kilométerre fekszik, közvetlenül a déli országhatár mellett. Ez az Ormánság legnyugatibb települése. A szomszédos települések a határ magyar oldalán: észak felől Lakócsa, északkelet felől Drávafok, kelet felől Markóc, délkelet felől Drávakeresztúr, északnyugat felől pedig Szentborbás. A határ túlsó oldalán a két legközelebbi falu Vaska (Vaška) és Kapinci (Kapinci), közigazgatásilag mindkettő Szópiához (Sopje) tartozik.'),
    ('Felsőszölnök', 'A Szölnök helységnév a szlovénből került a magyarba, jelentése: kaszáló, szénapadlás, szénapajta. A falu korai névváltozatai káposztaföldekre is utalnak , így Zelnuk (1387), Zewlnek (1538), Felsőzelnek (1548), feölseo Zelnik (1594). A faluban a pannon és a szubalpin éghajlat együttes hatása érződik. Az évi csapadékmennyiség átlagos középértéke 800 mm.'),
    ('Felsőtelekes', 'Közigazgatási területén található a rudabányai bányató és őshominida-lelőhely is. Területét délről a Rudabányai-hegység vonulatai, nyugatról a Putnoki-dombság nyúlványai határolják. A települést 200-300 méteres magasságú, részben erdőkkel fedett dombvonulatok övezik. A közvetlenül határos települések: észak felől Szőlősardó, kelet felől Alsótelekes, délkelet felől Szuhogy, dél felől Rudabánya, nyugat felől pedig Kánó.'),
    ('Felsőtold', 'Az alsótoldi körjegyzőséghez tartozik. A falu a Cserhát dombjai közt, a Zsunyi-patak völgyében épült. A Kelet-cserháti Tájvédelmi Körzet határa a falu szélén húzódik, a Novohrad-Nógrád UNESCO Globális Geopark települése. A faluközpont főutcája a 2122-esből, annak a 18+850-es kilométerszelvénye közelében északkeleti irányban, Garáb felé kiágazó 21 145-ös út.'),
    ('Felsőtárkány', 'A Bükk-hegységben, a Tárkányi-patak és a Berva-patak által kiszélesített Tárkányi-medencében, Egertől északra fekvő település. A település nevét 1261-ben említették először az oklevelekben Oltarkan, illetve Feltarkan alakban helyezkedik el. A kolostor romjai még ma is láthatók a falu északi határában a Barátréten helyezkedik el.'),
    ('Felsővadász', 'A Belső-Cserehát egyik észak–déli irányú völgyében, a Vadász-patak folyása mentén terül el. A környező települések közül közúton elérhető szomszédja csak kettő van: észak felől Gadna (3 kilométer), dél felől pedig Kupa (5 kilométer). Területe egyébként határos északkelet felől Abaújlakkal, kelet felől Nyéstával, délkelet felől Selyebbel, délnyugat felől Tomor és Lak, nyugat felől Szakácsival, északnyugat felől pedig Irotával is, de ezekkel jellemzően nincs közvetlen közúti kapcsolata, mert a szomszédos völgyekben találhatóak.'),
    ('Felsőzsolca', 'A Sajó–Hernád-síkon, a megyeszékhely Miskolccal közvetlenül határos, attól keletre fekszik, a Sajó folyó bal partján, a borsodi tájegység Abaújjal határos keleti oldalán. Felszíne sík, enyhén hullámos, a talajképző kőzetét löszös anyag alkotja. A környező települések közül Arnóton át Boldvával a 2617-es, Ongával és Gesztellyel a 3605-ös, Sajóláddal és Muhival pedig a 3606-os út köti össze.'),
    ('Felsőörs', 'A Balaton-felvidék azon települései közé tartozik, ahonnan – legalábbis a település egy része felől – látni lehet ugyan a Balatont, de saját tóparttal a helység nem rendelkezik. Felsőörs a Balaton-felvidék keleti részén fekszik, a Veszprém, Balatonalmádi és Balatonfüred által közrezárt háromszögben, Balatonalmáditól körülbelül 5, Veszprémtől 8, Balatonfüredtől kicsit több mint 12 kilométerre.'),
    ('Fenyőfő', 'A település az Öreg (vagy Magas) Bakony átlagosan 270 méteres magasságban lévő községe. Korábban Veszprém megye Zirci kistérségéhez tartozott, de 2002. október 20-án Győr-Moson-Sopron megyébe került át. A község azon hat település egyike, amelyek 1999 decemberében kezdeményezték a Veszprém megyétől való elszakadást a lakosság előzetes véleménynyilvánítása alapján helyezkedik el.'),
    ('Ferencszállás', 'Makó 10,5, Kiszombor 6, Klárafalva 2,5, Deszk 9,5 kilométer távolságra található. Közigazgatási területének északi határát a Maros folyása jelöli ki – azon túl maroslelei és makói külterületek határolják –, további szomszédai kelet felől Kiszombor, nyugat felől pedig Klárafalva. Dél felől Deszkhez tartozó, jobbára lakatlan külterületek határolják, de ez utóbbi település központja valójában nyugatra fekszik tőle, közel 10 kiloméeres távolságban.'),
    ('Fertőboz', 'A világörökség részeként számon tartott Fertő-tájhoz tartozik. Magyarország északnyugati részén, az Alpokaljához tartozó Fertőmelléki-dombságon helyezkedik el, Győr-Moson-Sopron megye egyik legszebb vidékén, a Fertő déli partját övező dombsor és a fertői nádas között. A Fertő–Hanság Nemzeti Park része, gazdag növény- és állatvilág jellemzi. Hozzátartozik Kisboz, a geofizikai obszervatórium és egy GYSEV őrház is.'),
    ('Fertőd', 'Magyarország északnyugati részén, a Fertő–Hanság kistájon található, néhány kilométerre délkeletre a Fertőtől, Ausztria határán. 1995-ben kapott városi rangot, ekkor 3179 lakosa volt. 1950-ben jött létre az Esterházy Miklós herceg által alapított Eszterháza valamint az 1313-ban alapított Süttör községek egyesülésével. Fertőd legismertebb látnivalója a „magyar Versailles” becenevű Esterházy-kastély.'),
    ('Fertőendréd', 'A Hanság déli részén, az Ikva partján fekszik. Korábban a településhez tartozó lakott hely volt Endrédújmajor községrész is, a belterületétől jó 3 kilométerre délkeletre, de az az idők folyamán elnéptelenedett. A szomszédos települések: északkelet felől Agyagosszergény, délkelet felől Vitnyéd, dél felől Csapod, délnyugat felől Fertőszentmiklós és Petőháza, északnyugat felől pedig Fertőd (Süttör).'),
    ('Fertőhomok', 'A közös önkormányzatba Hidegség is bekapcsolódott, így Fertőhomok, Hegykő és Hidegség immár közös önkormányzatot alkot melynek neve Hegykői Közös Önkormányzat, de Fertőhomok és Hidegség önkormányzati testületének hatásköre megmaradt. A Kisalföld nyugati szélén, Soprontól 16 kilométer-re helyezkedik el Hidegség és Hegykő között. Forgalmi út menti, egyutcás település a Fertő partján fésűs beépítéssel.'),
    ('Fertőrákos', 'Kiemelkedő történeti és művészeti emlékekkel rendelkezik. Szép természeti környezetben fekszik, számos épülete műemlék. Egyike az UNESCO világörökség részét képező Fertő/Neusiedlersee kultúrtáj jelentős településeinek, része a Fertő-Hanság Nemzeti Parknak. A községet átszeli a Fertő-parti országút, valamint a tó körül épült kerékpárút. Két határátkelőhellyel rendelkezik.'),
    ('Fertőszentmiklós', 'Magyarország északnyugati részén, az Ikva-síkon helyezkedik el, Soprontól 28 kilométerre délkeletre. 125 méteres tengerszint feletti magasságban fekszik. Talaja felső pliocén agyag és homok, erre rakódott le a homok, agyag, vályog és löszvályog. Ezért laza üledékes illetve és löszös üledékes barnaföld és barna erdőtalaj. A térségben a szántóföldi növénytermesztés mellett jelentős az erdőgazdálkodás.'),
    ('Fertőszéplak', 'A Kisalföld és az Alpokalja találkozásánál, a Fertő tótól délre, az Ikva-síkon található. Felszíne változatos: keletre a Kisalföld feltöltött síksága, nyugatra az Alpokalja, északra a Fertő lapálya határolja. Éghajlata szélsőséges: a nyár meleg, a tél hideg, gyakori az északi–északnyugati szél. Az évi csapadék kb. 600 mm. Helyi sajátosság a Fertő vízének tükröző hatása okozta magas hőmérséklet, a zöldség- és szőlőtermelést jótékonyan befolyásoló sugárzás.'),
    ('Fiad', 'A Dunántúli-dombság Somogyi-dombságában fekszik, Kaposvártól, a megyeszékhelytől körülbelül 40 kilométerre északra. A falut páratlan szép környezet veszi körül a Koppány-völgyében, az erdőségek vadban gazdagok, a vadászok kedvelt területe e táj. Zsáktelepülés, közúton csak a Kaposvárt Szántóddal összekötő 6505-ös útról Bonnyapusztánál nyugatra letérve érhető el, a közel 11 kilométer hosszú 65 114-es számú mellékúton.'),
    ('Filkeháza', 'A Zempléni-hegység középső részén helyezkedik el, nem messze a szlovák határtól. A megyeszékhely Miskolctól közúton 89 kilométerre északkeletre, a legközelebbi nagyobb várostól, Sátoraljaújhelytől 18 kilométerre északnyugatra található. A közvetlen szomszédos települések: észak felől Füzérkajata, kelet felől Füzérradvány, dél felől Pálháza, délnyugat felől Bózsva, nyugat felől Nyíri, északnyugat felől pedig Füzérkomlós és Füzér.'),
    ('Fityeház', 'Nagykanizsától 13 kilométerre délnyugatra fekszik, a Kiskanizsa központját Murakeresztúrral összekötő 6833-as út mentén. A levéltári adatok először 1422-ben szólnak a faluról, ekkor Fythyefelde alakban olvashatjuk. A későbbiekben Fygehaza (1531), Fytthye (1573), majd Fityeháza (1786) változatai ismeretesek. Mai végleges formájában 1877-től fordul elő.'),
    ('Foktő', 'A település közigazgatási területe két nagy kiterjedésű, egymástól távol fekvő területből áll. Bár a település közelében található, de nem tartozik közigazgatási területéhez a gerjeni komp bal parti felhajtójának környéke és a hozzá kapcsolódó gerjeni (meszesi) nyaralóterület, ezek Kalocsa város részei. A településhez tartozik a meszes üdülőterület kompjáró fölött lévő része.'),
    ('Folyás', 'A határos települések észak felől Polgár, kelet felől Görbeháza, dél felől Újszentmargita (illetve annak Bödönhát nevű településrésze), délnyugat felől Tiszakeszi, északnyugat felől pedig Tiszatarján helyezkedik el. Közúti kapcsolatban azonban csak Polgárral és Újszentmargitával áll. A sztráda egy kisebb szakasza át is halad ugyan a közigazgatási területén, de ott sem lehajtó, sem pihenőhely nem található.'),
    ('Fony', 'A Zempléni-hegység nyugati részén fekszik, a megyeszékhelytől, Miskolctól közúton mintegy 65 kilométerre északkeletre. A hegység több, 700 métert meghaladó magasságú hegye is a határai között emelkedik, ilyen például a 750 méteres Szár-kő, a 755 méter magas Borsó-hegy vagy a 783 méterig emelkedő Gergely-hegy.'),
    ('Fonyód', 'Népszerű üdülőhely és kikötőváros a Balaton déli partján helyezkedik el. Hozzá tartozik Alsóbélatelep, Bélatelep és Fonyódliget is. Lakossága (a 2019. július 1-jei adatok szerint) 5201 fő. A Balaton déli partján helyezkedik el. Déli irányból a Nagy-Berek vidéke övezi. A város pozícióját messziről felismerhetően kijelöli a tó déli partjának két legmagasabb, egymás szomszédságában emelkedő hegye, a 207 méteres Sipos-hegy és a 233 méter magasságú Vár-hegy.'),
    ('Fonó', 'Kaposvártól, Dombóvártól és Igaltól egyaránt mintegy 20-20 kilométerre fekvő külső-somogyi község. Fonó Árpád-kori település. Nevét 1250-ben említették először az oklevelekben, ekkor királynéi szolgálmányosok lakhelye volt. A Fonóról szóló első ismert írott emlék IV. vagy Kun László király idejéből, 1278-ból való. Fonó az 1563. évi török kincstári adólajstrom szerint már csak 6, az 1573-1574. évi defter szerint 10 és az 1580. évi szerint 13 házból állt, majd az 1660-as dézsmaváltságjegyzék szerint már a székesfehérvári custodiatusé volt.'),
    ('Forráskút', 'A szomszédos települések: északkelet felől Balástya, kelet felől Szatymaz, délkelet felől Zsombó, dél felől Bordány, délnyugat felől Üllés, északnyugat felől pedig Csólyospálos. Csak közúton érhető el: Kiskunmajsa és Szeged (Kiskundorozsma) felől az 5405-ös, Balástya felől az 5422-es, Üllés-Bordány felől pedig az 5426-os úton.'),
    ('Forró', 'A település a Hernád völgyében fekszik, a Cserehát keleti lábainál, Miskolctól 37 kilométerre északkeletre, Encs közvetlen szomszédságában, amelytől mindössze 3 kilométerre terül el. A környező kisebb települések közül Fancsal 5, Csobád 6 kilométerre található.'),
    ('Fulókércs', 'Ez utóbbiból a falu területén ágazik ki nyugat felé a Fáj és Litka községekbe vezető 26 146-os út. A környező települések: Fáj 3 kilométerre, Novajidrány 8 kilométerre, Pusztaradvány 7 kilométerre, Szalaszend 5 kilométerre és Szemere 4 kilométerre helyezkedik el. A legközelebbi város, Encs 12 kilométerre található. A falu neve a középkorban általában Kécs, a Kércs alak csak később, egy kiejtéskönnyítő mássalhangzó beiktatásával jött létre, ám ezzel igen ritkán találkozunk.'),
    ('Furta', 'Az Ölyvös-patak mellett fekvő település mind a mai napig megőrizte a sárréti-bihari falvak jellegzetességeit és arculatát. Nevezetes népművészeti hagyományairól, melyek közül a furtai hímzés a legmeghatározóbb. A lakosság elsősorban mezőgazdasági termelésből él, de magán hordozza a térségre jellemző hátrányos helyzetét. 1990 óta önálló községként működik.'),
    ('Fábiánháza', 'A környező települések közül Nagyecsed 2,5, Mérk 7,5, Tiborszállás 9,5, Mátészalka 15, Nyírcsaholy 8, Nyírbátor pedig 21 kilométerre található. A közvetlen szomszédos települések: észak felől Nyírcsaholy, északkelet felől Nagyecsed, délkelet felől Tiborszállás, dél felől Mérk, délnyugat felől Terem, nyugat felől pedig Nyírkáta. Különálló településrésze a jó 2 kilométerre keletre fekvő Előtelek.'),
    ('Fábiánsebestyén', 'A Körös–Maros közén, a Csongrádi-síkon helyezkedik el, a Szentes, Orosháza és Szarvas városok által közrefogott háromszög közepe táján, bár a három közül Szenteshez van a legközelebb. Északról és nyugatról is szentesi külterületek határolják, további szomszédjai kelet felől Eperjes, délkelet felől Árpádhalom, dél felől pedig Nagymágocs.'),
    ('Fácánkert', 'Neve 1936-ig Simonmajor volt. Három, korábban különálló településrész, Fácánkert-puszta, Simonmajor és Öregfalu egyesítésével jött létre. Öregfalu ma is elkülönül a központtól, a belterület legnyugatibb fekvésű, részben már külterületi utcái tartoznak hozzá. Zsáktelepülésnek tekinthető, mivel közúton csak egy útvonalon érhető el, a 6-os főútból Tolna északi peremvidékén északnyugatnak kiágazó 51 164-es számú mellékúton.'),
    ('Fáj', 'Miskolctól közúton 50 kilométerre északkeletre fekszik, a Cserehát északi részében, nem messze a szlovák határtól, a Fáji-patak völgyében. Nem tekinthető teljes mértékben zsáktelepülésnek, mert észak és dél felől is vezet út a településre, de a távolabbi vidékekről érkezők csak a Szalaszend és Fulókércs közötti 2626-os útból kiágazó 26 146-os úton juthatnak el ide.'),
    ('Fényeslitke', 'A Rétközben fekszik, a Tisza bal partján, Kisvárdától északkeletre. A szomszédos települések: észak felől Komoró, északkelet felől Mándok, kelet felől Tornyospálca, délkelet felől Jéke, délnyugat felől pedig Döge. Közigazgatási területe dél felől, egy-egy rövid, pár száz méteres szakaszon érintkezik Pap és Kisvárda határszéleivel is, északnyugaton pedig a Tisza túlpartján, légvonalban is több mint 10 kilométerre fekvő Zemplénagárd déli külterületeivel határos.'),
    ('Fót', 'A Gödöllői-dombság peremén, Budapest központjától 17, azonban XV. kerületének határától csupán 5 kilométerre északkeletre helyezkedik el. A fóti dombok az Cserhát nyugati nyúlványai. Nyugaton Dunakeszi, északkeleten Csomád és Veresegyház, keleten Mogyoród, délen Csömör, délnyugaton pedig Budapest a legközelebbi település. Legmagasabb pontja a Fóti-Somlyó dombja, ami 287 méterrel emelkedik a tengerszint fölé.'),
    ('Földes', 'Határai között áthalad, a központtól mintegy 5 kilométerre keleti-északkeleti irányban a Keleti-főcsatorna. A közvetlenül szomszédos települések: északkelet felől Hajdúszovát (14 kilométerre), kelet felől Derecske (20 kilométerre), délkelet felől Berettyóújfalu (16 kilométerre), dél felől Sáp (4 kilométerre), nyugat felől Báránd (10 kilométerre), északnyugat felől pedig Tetétlen (5 kilométerre).'),
    ('Földeák', 'Makó és Hódmezővásárhely között fekszik. Közúton Makótól 12, míg Hódmezővásárhelytől 18 kilométerre található. Szomszédjai észak felől a Hódmezővásárhelyhez tartozó Szikáncs, dél felől Makó, kelet felől ez utóbbi város nagy kiterjedésű külterületei, nyugat felől pedig Óföldeák. Belterületén négy buszmegálló van, a legnagyobb forgalmú a „Földeák községháza” elnevezésű.'),
    ('Füle', 'Főutcája a Polgárdi és Balatonakarattya, a 7-es és a 71-es, illetve 710-es főutak között húzódó 7205-ös út, közúton csak ezen érhető el kelet és nyugat felől is. A környező települések közül Polgárdi 3, Balatonfőkajár 4, Csajág 7, Lepsény 8, Küngös pedig 10,5 kilométer távolságra található. A mai település több korábbit is magába foglal: Nagyfülét, Kisfülét, Szentmártonfülét.'),
    ('Fülesd', 'A közvetlenül határos települések: északkelet felől Kölcse, délkelet felől Vámosoroszi, dél-délnyugat felől Kisszekeres, délnyugat felől Mánd, nyugat felől Komoró, északnyugat felől pedig Túristvándi. A környező, jelentősebb települések közül Fehérgyarmat 13,5, Tiszabecs és Túristvándi 12–12, Kölcse pedig 4 kilométer távolságra található. Déli szomszédja, Vámosoroszi felől a 4133-as úton érhető el.'),
    ('Fülpösdaróc', 'A környező települések közül Mátészalka 16, Fehérgyarmat 8, Győrtelek pedig 4 kilométer távolságra található. A község neve az Árpád-korban foglalkozást jelentő magyar daróc köznévből származik, amelyet valamelyik szláv nyelvből vettünk át. Jelentése a Szab.Szatm. szerint nincs megnyugtatóan tisztázva. A név eredetét többen, többféleképpen magyarázzák.'),
    ('Fülöp', 'Utcaképe, épületeinek elrendezése alapján tipikus szabolcsi településnek tekinthető, mert a lakóházak az értéktelenebb dombos részekre épültek, az "egy utca két sor ház" település alakzata szerint. A szomszédos települések a határ magyar oldalán: észak felől Nyírbéltek, északkelet felől Penészlek, dél felől Nyírábrány, nyugat felől Nyíracsád, északnyugat felől pedig Nyírlugos.'),
    ('Fülöpháza', 'A Kiskunság keleti részén fekszik, Kecskeméttől nyugatra. A szomszédos települések: északkelet felől Kerekegyháza, délkelet felől Ballószög, dél felől Ágasegyháza, nyugat felől pedig Fülöpszállás és Szabadszállás. Közigazgatási területének csaknem a fele – a belterületétől nyugatra eső területrészének majdnem az egésze – a Kiskunsági Nemzeti Park Fülöpházi homokbuckák (vagy Fülöpházi buckavidék) nevű részegységéhez tartozó, szigorúan védett terület.'),
    ('Fülöpjakab', 'Kecskemét és Kiskunfélegyháza között helyezkedik el, utóbbihoz közelebb. A szomszédos települések: észak felől Városföld, északkelet felől Kunszállás, dél felől Bugac, nyugat felől Jakabszállás, északnyugat felől pedig Kecskemét Matkó nevű külterületi városrésze. A 18. és 19. században a mai község területe Jakabszállás pusztának az a része volt, melyet a jászkun redemptio idejétől eredetileg Fülöpszállás birtokolt.'),
    ('Fülöpszállás', 'A település népessége az évszázadok során többször is jelentősen lecsökkent, és megváltozott. Lakói voltak az ősi kun betelepülők, és jelentős szerepet játszottak az újjáépítésekben és a közösségformálásban a református vallásra áttért ősök. A szomszédos települések: észak felől Szabadszállás, kelet felől Izsák, dél felől Soltszentimre, délnyugat felől Dunatetétlen, nyugat felől pedig Solt.'),
    ('Fürged', 'Fekvése tehát természetszerűleg meghatározza adottságait: jobbára löszös talajú dombvidék, síksággal és kisebb fennsíkkal váltakozva. A község is maga egy ilyen fennsíkon fekszik, ahonnan gyönyörű kilátás nyílik a vidékre. A határos települések: északon Felsőnyék, északkeleten Ozora, délen Tamási, nyugaton Nagyszokoly és Magyarkeszi. Fürged 1871 táján Felsőnyéktől különválva önálló községgé alakult, erről azonban hivatalos adatok nem lelhetők fel.'),
    ('Füzesabony', 'Az Alföld északi peremén, a Hevesi-síkon helyezkedik el. A közvetlenül határos települések: észak felől Maklár, kelet felől Szihalom, délkelet felől Mezőtárkány, dél felől Dormánd, délnyugat felől Erdőtelek, nyugat felől Kál, északnyugat felől pedig Kerecsend.'),
    ('Füzesgyarmat', 'A város szénhidrogén-kutatásáról és a termálvizéről nevezetes. A megye hozzá legközelebb fekvő városa Szeghalom. Biharnagybajom és Szeghalom között Békéscsabától 60 kilométer-re északra fekszik. A karcagi útvonal, a Karcag - Bucsa közötti útszakasz közelmúltban történt felújítása óta ugyancsak elfogadható minőségű.'),
    ('Füzér', 'Itt található Magyarország legészakibb határpontja. A Hegyköz idegenforgalmának egyik központja, látnivalói közül kiemelkedő Füzér vára helyezkedik el. Miskolctól közúton 95 kilométerre északkeletre, a magyar–szlovák határ mellett található. Közigazgatási területén fekszik Magyarország legészakibb pontja, valamint az ország egyik legmagasabb hegycsúcsa, a Nagy-Milic (896 méter).'),
    ('Füzérkajata', 'A Zempléni-hegység középső részén helyezkedik el, közvetlenül a szlovák határ mellett, a megyeszékhely Miskolctól közúton 93 kilométerre északkeletre. A közvetlen szomszédos települések a határ magyar oldalán: kelet-délkelet felől Vilyvitány, délkelet felől Füzérradvány, dél felől Filkeháza, nyugat felől Füzér, északnyugat felől pedig Pusztafalu. A határ felvidéki oldala felől a három legközelebbi település Biste (Byšta), Kázmér (Kazimír) és Kolbása (Brezina).'),
    ('Füzérkomlós', 'A Zempléni-hegység középső részén helyezkedik el, a megyeszékhely Miskolctól mintegy 90 kilométerre északkeletre, Sátoraljaújhelytől nagyjából 22 kilométerre északnyugatra. A közvetlen szomszédos települések: észak felől Füzér, délkelet felől Filkeháza, dél felől Nyíri, északnyugat felől pedig Hollóháza. A környező települések közül Füzér 5, Hollóháza, Nyíri és Pusztafalu egyaránt nagyjából 6-6 kilométer távolságra fekszik.'),
    ('Füzérradvány', 'Miskolctól közúton 89 kilométerre északkeletre, Sátoraljaújhelytől mintegy 20 kilométerre található. A településhez legközelebb eső város a mindössze 2 kilométerre fekvő Pálháza. A környező települések közül Filkeháza 4, Bózsva 5 kilométerre található. Füzérradvány közúton csak Pálházán át közelíthető meg. Füzérradvány (Radvány) nevét 1262-ben említették először az oklevelekben Rodowan alakban írva.'),
    ('Főnyed', 'Marcalitól északnyugatra, Vörs, Tikos és Sávoly közt fekvő település. Egy, az 1703 előtti évből való fegyverjog-összeírás szerint már csak puszta volt és a Festetics család birtokai közé tartozott. 1773-ban már önálló jobbágyközség volt, majd az 1900-as évek elején Festetics Tasziló hercegnek volt itt nagyobb birtoka.'),
    ('Fűzvölgy', 'Neve 2004-ig Füzvölgy volt. Fűzvölgy Nagykanizsától mintegy 10 kilométerre északkeletre található. A település a Principális-csatorna völgyében, sík területen fekszik, talaja jórészt homokos. A közvetlenül határos települések: észak felől Magyarszentmiklós, kelet felől Újudvar, dél felől Hosszúvölgy, nyugat felől pedig Homokkomárom. Hosszúvölggyel egy számozatlan önkormányzati út köti össze.'),
    ('Gacsály', 'A szomszédos települések: észak felől Túrricse, északkelet felől Tisztaberek, kelet felől Rozsály, dél felől Csengersima, délnyugat felől Császló, északnyugat felől pedig Kisnamény (az említettek közül a két legközelebbi szomszédja Rozsály és Császló, mindkettőtől jó 2-2 kilométernyi távolságban fekszik). Délkelet felől a legközelebbi község az alig 5 kilométerre eső Zajta, de a két település közigazgatási területei nem érintkeznek egymással.'),
    ('Gadna', 'Miskolctól közúton 42 kilométerre északra helyezkedik el, a Vadász-patak völgyében. A közvetlenül határos települések: észak felől Gagybátor, kelet felől Abaújlak, dél felől Felsővadász, nyugat felől pedig Irota. Délnyugaton pontszerűen érintkezik még a közigazgatási területe Szakácsiéval is. Első említése 1330-ból ered (Ganna), neve a szláv gad (kígyó) szóból származik. 1320-ban már templomát is említették.'),
    ('Gadács', 'Igaltól keletre, Somogyacsa és Somogyszil közt fekszik. Gadács Árpád-kori település, 1138-ban már a dömösi prépostság birtokaként említették az oklevelek. Az 1563-as török kincstári fejadólajstromban 9, az 1573-1574, az 1578 és az 1580. évi fejadólajstromban pedig 10-10 házzal volt felvéve.')
) AS v(name, panel_leiras)
WHERE c.name = v.name;

-- 1/4. fájl kész.
